package com.ankan.Questions;

public class OffRamp {
    public static void main(String[] args) {
        int[] exits = {0, 0, 0, 0, 0, 0};
        int x1 = 0;

        for (int x = 0; x < 4; x++) {
            exits[0] = x;
        }
        for (int x = 0; x < 4; x++) {
            exits[1] = x;
        }

        x1 = 0;
        while(x1++ < 3) exits[2] = x1;
        x1 = 0;
        while(++x1 < 3) exits[3] = x1;

        x1 = 0;
        do {
            exits[4] = x1;
        } while (x1++ < 7);
        x1 = 0;
        do {
            exits[5] = x1;
        } while (++x1 < 7);

        for(int x: exits) {System.out.print(x + " ");}
    }
}

package com.ankan.Questions;

public class OffRamp {
    public static void main(String[] args) {
        int[] output = {0, 0, 0, 0, 0, 0};
        int counter = 0;

        for (int idx = 0; idx < 4; idx++) {
            output[0] = idx;
        }
        for (int idx = 0; idx < 4; idx++) {
            output[1] = idx;
        }

        counter = 0;
        while(counter++ < 3) output[2] = counter;
        counter = 0;
        while(++counter < 3) output[3] = counter;

        counter = 0;
        do {
            output[4] = counter;
        } while (counter++ < 7);
        counter = 0;
        do {
            output[5] = counter;
        } while (++counter < 7);

        for(int val: output) {System.out.print(val + " ");}
    }
}

