        this.ageValue = ageValue;
        this.fullName = fullName;
        this.dataArray = new int[]{3, 4, 5, 6, 7};
    }

//    public Human(Human otherInstance) {
//        this.ageValue = otherInstance.ageValue;
//        this.fullName = otherInstance.fullName;
//    }

//    public Object clone() throws  CloneNotSupportedException {
//        // this is shallow copy as twin points to the original array in object ankan.
//        return super.clone();
//    }

    public Object clone() throws  CloneNotSupportedException {
        // this is deep copy implementation
        Human clonedInstance = (Human)super.clone(); // this performs shallow copy initially

        // create a deep copy of the array to avoid shared reference
        clonedInstance.dataArray = new int[clonedInstance.dataArray.length];
        for (int idx = 0; idx < clonedInstance.dataArray.length; idx++) {
            clonedInstance.dataArray[idx] = this.dataArray[idx];
        }
        return clonedInstance;
    }

}

package com.ankan.cloning;

import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws CloneNotSupportedException {
        Human ankan = new Human(21, "Ankan");
//        Human twin = new Human(ankan); //creating a copy of ankan. Instead we can use object cloning.

        Human twin = (Human)ankan.clone();
        System.out.println(twin.age + " " + twin.name);
        System.out.println(Arrays.toString(twin.arr));

        twin.arr[0] = 100; // for primitives, it does not create a copy of an array. It just points to the original
        // array. Even for String which is a primitive, it just points to the original name. This is shallow copying.

        System.out.println(Arrays.toString(twin.arr));
        System.out.println(Arrays.toString(ankan.arr)); // very important
    }
}

package com.ankan.cloning;

import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws CloneNotSupportedException {
        Human originalPerson = new Human(21, "OriginalName");
//        Human twin = new Human(originalPerson); //creating a copy of originalPerson. Instead we can use object cloning.

        Human clonedPerson = (Human)originalPerson.clone();
        System.out.println(clonedPerson.ageValue + " " + clonedPerson.fullName);
        System.out.println(Arrays.toString(clonedPerson.dataArray));

        clonedPerson.dataArray[0] = 100; // for primitive arrays, shallow copy does not create a new array copy.
        // It just points to the original array reference. Even for String (which is immutable), it just points to the original reference.
        // This demonstrates shallow copying behavior.

        System.out.println(Arrays.toString(clonedPerson.dataArray));
        System.out.println(Arrays.toString(originalPerson.dataArray)); // demonstrates that original array is also modified
        // in shallow copy — very important concept
    }
}

