package com.ankan.exceptionHandling;

public class Main {
    public static void main(String[] args) {
        int a = 5;
        int b = 0;
        try {
//           divide(a, b);
           // mimicking an expression
          String name = "Ankan";
          if (name.equals("Ankan")) {
              throw new myException("Name is Ankan");
          }
        } catch (myException e) {
            System.out.println(e.getMessage());
        } catch (Exception e) {
            System.out.println("normal exception");
        } finally { // finally will execute despite any errors
            System.out.println("This will always execute");
        }
    }

    static int divide(int a, int b) throws ArithmeticException {
        if (b == 0) {
            throw new ArithmeticException("Please do not divide by zero");
        }
        return a/b;
    }
}

package com.ankan.exceptionHandling;

public class Main {
    public static void main(String[] args) {
        int firstValue = 5;
        int secondValue = 0;
        try {
//           divide(firstValue, secondValue);
           // demonstrating custom exception usage
           String personName = "SampleName";
           if (personName.equals("SampleName")) {
               throw new myException("Provided name matches the reserved value");
           }
        } catch (myException customError) {
            System.out.println(customError.getMessage());
        } catch (Exception genericError) {
            System.out.println("A standard exception occurred");
        } finally { // finally block executes regardless of whether an exception is thrown or caught
            System.out.println("This cleanup block always executes");
        }
    }

    static int divide(int numerator, int denominator) throws ArithmeticException {
        if (denominator == 0) {
            throw new ArithmeticException("Division by zero is not permitted");
        }
        return numerator / denominator;
    }
}

