package com.ankan.fileHandling;

import java.io.*;

public class Main {
    public static void main(String[] args) {

        // create
        try{
            File fo = new File("new-file.txt");
            fo.createNewFile();
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }

        // write in the file
        try{
            FileWriter fw = new FileWriter("new-file.txt");
            fw.write("सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज |\n" + "अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुच:");
            fw.close();
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }

        // reading the file
        try {
            BufferedReader br = new BufferedReader(new FileReader("new-file.txt"));
            while (br.ready()) {
                System.out.println(br.readLine());
            }
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }

        // creating random file and deleting
        try{
            File fo = new File("random.txt");
            fo.createNewFile();
            if (fo.delete()){
                System.out.println(fo.getName());
            }
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
    }
}

package com.ankan.fileHandling;

import java.io.*;

public class Main {
    public static void main(String[] args) {

        // Step 1: Create a new file
        try{
            File newFile = new File("new-file.txt");
            newFile.createNewFile();
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 2: Write content into the file
        try{
            FileWriter fileWriter = new FileWriter("new-file.txt");
            fileWriter.write("सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज |\n" + "अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुच:");
            fileWriter.close();
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 3: Read the contents of the file
        try {
            BufferedReader bufferedReader = new BufferedReader(new FileReader("new-file.txt"));
            while (bufferedReader.ready()) {
                System.out.println(bufferedReader.readLine());
            }
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 4: Create a temporary file and then delete it
        try{
            File temporaryFile = new File("random.txt");
            temporaryFile.createNewFile();
            if (temporaryFile.delete()){
                System.out.println("Deleted: " + temporaryFile.getName());
            }
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }
    }
}

