package com.ankan.fileHandling;

import java.io.*;

public class fileReader {
    public static void main(String[] args) throws IOException {
//        // Example 1: Reading from a file using FileReader (commented)
//        try (FileReader fileReader = new FileReader("fileHandling.txt")) {
//            int characterData = fileReader.read(); // read() returns integer representation of character
//            while (fileReader.ready()) {
//                System.out.println((char) characterData);
//                characterData = fileReader.read(); // moves to the next character
//            }
//        } catch (IOException error) {
//            System.out.println(error.getMessage());
//        }
//
//        // Example 2: Reading user input from console using BufferedReader + InputStreamReader (commented)
//        try (BufferedReader consoleReader = new BufferedReader(new InputStreamReader(System.in))) {
//            // InputStreamReader converts byte stream (from System.in) to character stream
//            System.out.print("Enter some text: ");
//            System.out.println("You entered: " + consoleReader.readLine());
//        } catch (IOException error) {
//            System.out.println(error.getMessage());
//        }
//
//        // Example 3: Reading from a file using BufferedReader (commented)
//        try (BufferedReader fileBufferedReader = new BufferedReader(new FileReader("note.txt"))) {
//            while (fileBufferedReader.readLine() != null) {
//                System.out.println(fileBufferedReader.readLine());
//            }
//        } catch (IOException error) {
//            System.out.println(error.getMessage());
//        }

        // Section: Output Writers and Byte Streams

        OutputStream byteOutputStream = System.out;
//      byteOutputStream.write(😘); // emoji exceeds byte range (0-255), causes compilation error
        byteOutputStream.write(10); // ASCII 10 corresponds to newline character

        // Example: OutputStreamWriter converts character stream to byte stream
        try(OutputStreamWriter characterToByteWriter = new OutputStreamWriter(System.out)) {
            characterToByteWriter.write("Hello World \n");
            characterToByteWriter.write(97);  // 'a' in ASCII
            characterToByteWriter.write("\n");
            char[] characterArray = "Hello World".toCharArray();
            characterToByteWriter.write(characterArray);
            characterToByteWriter.write("😘");  // Unicode emoji
            characterToByteWriter.write(10);   // newline character
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Appending to a file using FileWriter
        try(FileWriter fileWriter = new FileWriter("note.txt", true)) {
            fileWriter.write(" I am currently in my 4th semester");
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Writing to a file using BufferedWriter
        try(BufferedWriter bufferedFileWriter = new BufferedWriter(new FileWriter("note.txt"))) {
            bufferedFileWriter.write("Hare Krishna");
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }
    }

/*
Important Note: Keyboard input (System.in) provides byte-based data. InputStreamReader converts this byte stream
into a character stream so that BufferedReader can read it line by line using readLine().
Character stream classes cannot directly handle byte input without this conversion.
 */
}

package com.ankan.fileHandling;

import java.io.IOException;
import java.io.InputStreamReader;

public class ioStream {
    public static void main(String[] args) {
        try (InputStreamReader isr = new InputStreamReader(System.in)) {
            System.out.print("Enter some numbers: ");
            int num = isr.read();
            while(isr.ready()) {
                System.out.println((char) num);
                num = isr.read();
            }
            isr.close();
            System.out.println();
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
    }
}

package com.ankan.fileHandling;

import java.io.IOException;
import java.io.InputStreamReader;

public class ioStream {
    public static void main(String[] args) {
        // Demonstrating InputStreamReader to read byte input from console as characters
        try (InputStreamReader consoleCharacterReader = new InputStreamReader(System.in)) {
            System.out.print("Please enter some text or numbers: ");
            int characterCode = consoleCharacterReader.read(); // reads first character as integer (ASCII/Unicode value)

            while(consoleCharacterReader.ready()) {
                System.out.print((char) characterCode); // convert integer back to character
                characterCode = consoleCharacterReader.read(); // move to next character in stream
            }
            consoleCharacterReader.close(); // explicitly close the stream (though try-with-resources does this automatically)
            System.out.println(); // add newline after output
        } catch (IOException readError) {
            System.out.println("An I/O error occurred: " + readError.getMessage());
        }
    }
}

