package com.ankan.generics;

import java.util.ArrayList;
import java.util.Arrays;

public class CustomArrayList {

    private int[] internalDataArray;
    private static int DEFAULT_CAPACITY = 10;
    private int currentSize = 0; // also works as the next available index position

    public CustomArrayList() {
        this.internalDataArray = new int[DEFAULT_CAPACITY];
    }

    public void add(int elementToAdd) {
        if (isArrayFull()) {
            resizeArray();
        }
        internalDataArray[currentSize++] = elementToAdd;
    }

    private void resizeArray() {
        int[] expandedArray = new int[internalDataArray.length * 2];

        // Copy all existing elements into the new larger array
        for (int indexPosition = 0; indexPosition < internalDataArray.length; indexPosition++) {
            expandedArray[indexPosition] = internalDataArray[indexPosition];
        }
        internalDataArray = expandedArray;
    }

    private boolean isArrayFull() {
        return currentSize == internalDataArray.length;
    }

    public int removeLastElement() {
        int removedElementValue = internalDataArray[--currentSize];
        return removedElementValue;
    }

    public int getElementAtIndex(int targetIndex) {
        return internalDataArray[targetIndex];
    }

    public int getCurrentSize() {
        return currentSize;
    }

    public void updateValueAtIndex(int targetIndex, int newValue) {
        internalDataArray[targetIndex] = newValue;
    }

    @Override
    public String toString() {
        return "CustomArrayList { " +
                "data = " + Arrays.toString(internalDataArray) +
                ", currentSize = " + currentSize +
                '}';
    }

    public static void main(String[] args) {
        // Standard Java ArrayList example (commented)
        // ArrayList list = new ArrayList();

        // Using our custom ArrayList implementation
        CustomArrayList customList = new CustomArrayList();
//        customList.add(3);
//        customList.add(5);
//        customList.add(9);

        // Populate the list with even numbers
        for (int iterationCount = 0; iterationCount < 14; iterationCount++) {
            customList.add(2 * iterationCount);
        }

        System.out.println("Custom ArrayList contents: " + customList);

        // Demonstration of Java's generic ArrayList with String type
        ArrayList<String> stringArrayList = new ArrayList<>();
        stringArrayList.add("sample text");

        // Educational note about Generics
        // Generics enable parameterized type checking at compile time
        // Example: ArrayList<Integer>, ArrayList<String> etc.
    }
}

