package com.ankan.inheritance;

public class BoxWeight extends Box {
    double boxWeight; // Weight of the box (could represent mass or shipping weight)

    // Default constructor - initializes weight to -1 (sentinel value)
    public BoxWeight() {
        this.boxWeight = -1.0;
    }

//    // Example of why static methods cannot be overridden (commented)
//    // @Override annotation is not allowed on static methods
//    static void displayGreeting() {
//        System.out.println("Greetings from BoxWeight class!");
//    }

    // Copy constructor - creates a BoxWeight from an existing BoxWeight object
    BoxWeight(BoxWeight existingBoxWeight) {
        super(existingBoxWeight); // Calls the Box(Box old) copy constructor
        // Explanation: super(existingBoxWeight) refers to the parent class constructor
        // Box(Box old) which copies length, height, and width from the source object

        this.boxWeight = existingBoxWeight.boxWeight;

        // Important OOP note: It's the reference variable type, not the actual object type,
        // that determines which members can be accessed at compile time.
        // System.out.println(super.boxWeight); // This would not work - parent class doesn't have weight
    }

    // Constructor that only sets the weight
    public BoxWeight(double weightValue) {
        this.boxWeight = weightValue;
        // Note: Parent class fields (length, height, width) remain uninitialized (default 0.0)
    }

    // Constructor for cube-shaped boxes (all dimensions equal) with specified weight
    public BoxWeight(double sideLength, double weightValue) {
        super(sideLength); // Calls Box(double side) cube constructor
        this.boxWeight = weightValue;
    }

    // Fully parameterized constructor - sets all dimensions and weight
    public BoxWeight(double boxLength, double boxHeight, double boxWidth, double weightValue) {
        super(boxLength, boxHeight, boxWidth); // Calls Box(double l, double h, double w) constructor
        this.boxWeight = weightValue;

        // Demonstrating field access - 'this.w' accesses the width field from current class
        // 'super.w' accesses the width field from parent class (same value in this case)
        System.out.println("Width accessed via 'this': " + this.width);
        System.out.println("Width accessed via 'super': " + super.width);
    }

    // Constructor that combines a regular Box object with additional weight
    public BoxWeight(Box existingBox, double weightValue) {
        super(existingBox); // Copies dimensions from the existing Box object
        this.boxWeight = weightValue;
    }

    // Additional method to display box weight information (educational enhancement)
    public void displayWeightInfo() {
        System.out.println("Box weight: " + boxWeight + " units");
    }
}

package com.ankan.inheritance;

interface Side {
    String getSide();
    }

class Head implements Side {
    public String getSide() {
        return "Head ";
    }
}
class Tail implements Side {
    public String getSide() {
        return "Tail ";
    }
}
class Coin {
    public static void overload(Head side) { System.out.print(side.getSide()); }
    public static void overload(Tail side) { System.out.print(side.getSide()); }
    public static void overload(Side side) { System.out.print("Side "); }
    public static void overload(Object side) { System.out.print("Object "); }
    public static void main(String []args) {
        Side firstAttempt = new Head();
        Tail secondAttempt = new Tail();
        overload(firstAttempt);
        overload((Object)firstAttempt);
        overload(secondAttempt);
        overload((Side)secondAttempt);
    }
}

package com.ankan.inheritance;

// Interface defining a contract for objects that have a side descriptor
interface Side {
    String getSide();
}

// Concrete implementation for Head side
class Head implements Side {
    public String getSide() {
        return "Head ";
    }
}

// Concrete implementation for Tail side
class Tail implements Side {
    public String getSide() {
        return "Tail ";
    }
}

// Demonstration class showing method overloading and type casting resolution
class Coin {

    // Overloaded method accepting Head type (most specific)
    public static void overload(Head sideObject) { 
        System.out.print(sideObject.getSide()); 
    }

    // Overloaded method accepting Tail type (most specific)
    public static void overload(Tail sideObject) { 
        System.out.print(sideObject.getSide()); 
    }

    // Overloaded method accepting Side interface type (more general)
    public static void overload(Side sideObject) { 
        System.out.print("Side "); 
    }

    // Overloaded method accepting Object type (most general)
    public static void overload(Object sideObject) { 
        System.out.print("Object "); 
    }

    public static void main(String[] args) {
        // Reference type is Side (interface), actual object type is Head
        Side firstAttemptReference = new Head();  // Upcasting: Head → Side

        // Reference type is Tail (concrete class), actual object type is Tail
        Tail secondAttemptReference = new Tail();

        // Case 1: Compiler sees Side reference → chooses overload(Side side)
        // Even though actual object is Head, method selection happens at COMPILE TIME
        // based on reference type, not runtime object type
        overload(firstAttemptReference);  // Output: "Side "

        // Case 2: Explicit cast to Object → forces overload(Object side)
        // Casting overrides the reference type determination
        overload((Object)firstAttemptReference);  // Output: "Object "

        // Case 3: Reference type is Tail (no casting needed)
        // Compiler sees exact match with overload(Tail side)
        overload(secondAttemptReference);  // Output: "Tail "

        // Case 4: Explicit cast to Side interface
        // Even though secondAttemptReference is Tail, casting to Side makes compiler
        // choose overload(Side side) instead of overload(Tail side)
        overload((Side)secondAttemptReference);  // Output: "Side "

        // Educational Output Summary (optional demonstration):
        System.out.println(); // Newline for clean output separation
        System.out.println("--- Overloading Resolution Rules ---");
        System.out.println("1. Method overloading is determined at COMPILE TIME");
        System.out.println("2. The reference type (not object type) determines which overload is called");
        System.out.println("3. Explicit casting can override the default reference type");
        System.out.println("4. Most specific matching method is preferred when no cast is applied");
    }
}

