package com.ankan.inheritance;

public class Main {
    public static void main(String[] args) {
        // Creating a standard Box object with custom dimensions
        Box regularBox = new Box(51, 31, 77);
        System.out.println("Regular Box dimensions: " + regularBox.length + " x " + regularBox.width + " x " + regularBox.height);
        // System.out.println(regularBox.boxWeight); // ERROR: Parent class reference cannot access child class fields

        // Creating BoxWeight objects using different constructors
        BoxWeight defaultWeightBox = new BoxWeight();  // Uses default constructor
        BoxWeight fullyParameterizedBox = new BoxWeight(2, 3, 4, 8);  // Sets all dimensions and weight

        System.out.println("BoxWeight object - Weight: " + defaultWeightBox.boxWeight + 
                           ", Dimensions: " + defaultWeightBox.length + " x " + 
                           defaultWeightBox.width + " x " + defaultWeightBox.height);

        // Demonstrating upcasting: Child object referenced by Parent reference variable
        Box upcastedBoxReference = new BoxWeight(2, 3, 4, 8);
        // System.out.println(upcastedBoxReference.boxWeight); // COMPILE ERROR: Parent reference cannot see child fields
        // Explanation: The reference variable type (Box) determines which members are accessible at compile time
        // Even though the actual heap object is BoxWeight, the stack reference upcastedBoxReference is of type Box
        System.out.println("Upcasted Box can only access parent fields: width = " + upcastedBoxReference.width);

        /*
        Important Inheritance Rules:
        =============================
        1. Parent class references CANNOT access child-specific fields/methods
        2. The reference type (not object type) determines compile-time accessibility
        3. Downcasting (Child ref = (Child) parentRef) requires explicit cast and may fail at runtime

        Invalid Example (would cause compilation error):
        BoxWeight invalidDowncast = new Box(2, 3, 4);
        Reason: Cannot assign parent object to child reference without proper casting
        */

        // Creating BoxPrice object (demonstrates multi-level inheritance)
        BoxPrice pricedBox = new BoxPrice(5, 8, 90);

        // Demonstrating static method behavior (cannot be overridden)
        Box staticMethodDemoParent = new BoxWeight();
        staticMethodDemoParent.displayGreeting();  // Calls Box version (reference type determines which static method)

        BoxWeight staticMethodDemoChild = new BoxWeight();
        staticMethodDemoChild.displayGreeting();   // Calls inherited static method from Box (not overridden)

        // Educational Note:
        // Static methods are associated with the CLASS, not with individual objects
        // Therefore, method overriding (which is runtime polymorphism) does NOT apply to static methods
        // Static methods can be inherited from parent classes but cannot be overridden in child classes
        // The method called depends on the reference type, not the actual object type

        System.out.println("\n--- Key Takeaways ---");
        System.out.println("✅ Parent references can point to child objects (Upcasting)");
        System.out.println("❌ Parent references cannot access child-specific fields");
        System.out.println("📌 Reference type determines compile-time member access");
        System.out.println("⚡ Static methods are inherited but NOT overridden");
        System.out.println("🎯 Overloading = compile-time | Overriding = runtime");
    }
}

