package com.ankan.interfaces.nested;

public class A {
    // nested interface
    public interface NestedInterface {
        boolean isOdd(int num);
    }
}

class B implements A.NestedInterface {
    @Override
    public boolean isOdd(int num) {
        return (num & 1) == 1;
    }
}

package com.ankan.interfaces.nested;

public class A {
    // Nested interface - declared inside class A
    // Can be public, private, protected, or package-private
    // Useful for grouping related interfaces or when the interface is tightly coupled with the class
    public interface NumberParityChecker {
        boolean checkIfNumberIsOdd(int inputNumber);
    }
}

// Class B implements the nested interface using fully qualified name A.NestedInterface
class B implements A.NumberParityChecker {

    @Override
    public boolean checkIfNumberIsOdd(int inputNumber) {
        // Using bitwise AND operator for efficient odd/even detection
        // (num & 1) returns 1 for odd numbers, 0 for even numbers
        return (inputNumber & 1) == 1;
    }

    // Optional: Demonstration method
    public static void main(String[] args) {
        B parityChecker = new B();

        // Test the isOdd functionality
        System.out.println("--- Odd Number Checker Demonstration ---");
        System.out.println("Is 7 odd? " + parityChecker.checkIfNumberIsOdd(7));   // true
        System.out.println("Is 10 odd? " + parityChecker.checkIfNumberIsOdd(10)); // false
        System.out.println("Is -3 odd? " + parityChecker.checkIfNumberIsOdd(-3)); // true (negative odd)

        // Polymorphic reference using nested interface type
        A.NumberParityChecker interfaceReference = parityChecker;
        System.out.println("\nUsing interface reference - Is 5 odd? " + interfaceReference.checkIfNumberIsOdd(5));

        // Educational note:
        // Nested interfaces are implicitly static (even without the static keyword)
        // They can be accessed using the outer class name: A.NestedInterface
    }
}

package com.ankan.interfaces.nested;

public class Main {
    public static void main(String[] args) {
        B obj = new B();
        System.out.println(obj.isOdd(6));
    }
}

package com.ankan.interfaces.nested;

public class Main {
    public static void main(String[] args) {
        // Creating an instance of class B which implements the nested interface
        B oddNumberChecker = new B();

        // Testing the isOdd functionality with sample value
        // Expected output: false (since 6 is even)
        System.out.println("Is 6 odd? " + oddNumberChecker.checkIfNumberIsOdd(6));

        // Additional demonstrations (commented)
        // System.out.println("Is 15 odd? " + oddNumberChecker.checkIfNumberIsOdd(15)); // true
        // System.out.println("Is 0 odd? " + oddNumberChecker.checkIfNumberIsOdd(0));   // false

        // Demonstrating access through nested interface type
        A.NumberParityChecker interfaceBasedReference = oddNumberChecker;
        System.out.println("Is 9 odd? (via interface reference) " + interfaceBasedReference.checkIfNumberIsOdd(9));

        // Educational note:
        // The nested interface is accessed as A.NumberParityChecker
        // Classes implementing it must use the fully qualified name: implements A.NumberParityChecker
    }
}

