    public void upgradeEngine() {
        System.out.println("\n--- Upgrading Engine ---");
        System.out.println("Replacing existing engine with ElectricEngine...");
        this.carEngine = new ElectricEngine();
        System.out.println("Upgrade complete! Car now has ElectricEngine");
