// create a class
// for every single student
class Student {
    int rno;
    String name;
    float marks = 90;

    // we need a way to add the values of the above
    // properties object by object

    // we need one word to access every object. It basically means what object are we referring to in that particular
    // thing

    void greeting() {
        System.out.println("Hello! My name is " + this.name);
    }

    void changeName(String name) {
        this.name = name;
    }

    Student (Student other) {
        this.name = other.name;
        this.rno = other.rno;
        this.marks = other.marks;
    }

    Student () {
        // this is how you call a constructor from another constructor
        // internally: new Student (13, "default person", 100.0f);
        this (13, "default person", 100.0f);
    }


    // Student arpit = new Student(17, "Arpit", 89.7f);
    // here, this will be replaced with arpit
    Student (int rno, String name, float marks) {
        this.rno = rno;
        this.name = name;
        this.marks = marks;
    }

}

package com.ankan.introduction;

public class Main {
    public static void main(String[] args) {
        // Example 1: Store 5 roll numbers using primitive array
        int[] rollNumbersArray = new int[5];

        // Example 2: Store 5 names using String array
        String[] studentNamesArray = new String[5];

        // Example 3: Store data for 5 students using separate arrays (not ideal OOP approach)
        int[] studentRollNumbers = new int[5];
        String[] studentNames = new String[5];
        float[] studentMarks = new float[5];

        // Preferred OOP approach: Array of Student objects
        Student[] studentsList = new Student[5];

        // Creating Student objects using parameterized constructor
        Student kunalStudent = new Student(15, "Kunal Kushwaha", 85.4f);
        Student rahulStudent = new Student(18, "Rahul Rana", 90.3f);

        // Alternative approach: Set properties individually (commented)
        // kunalStudent.rollNumber = 13;
        // kunalStudent.studentName = "Kunal Kushwaha";
        // kunalStudent.marksPercentage = 88.5f;

        // Call instance methods (commented)
        // kunalStudent.updateStudentName("Shoe lover");
        // kunalStudent.displayGreeting();

        // Display student details
        System.out.println("--- Kunal's Details ---");
        System.out.println("Roll Number: " + kunalStudent.rollNumber);
        System.out.println("Name: " + kunalStudent.studentName);
        System.out.println("Marks: " + kunalStudent.marksPercentage);

        // Copy constructor demonstration
        Student copiedStudent = new Student(kunalStudent);
        System.out.println("\n--- Copied Student (from Kunal) ---");
        System.out.println("Copied student name: " + copiedStudent.studentName);

        // Default constructor demonstration
        Student defaultStudent = new Student();
        System.out.println("\n--- Default Student ---");
        System.out.println("Default student name: " + defaultStudent.studentName);

        // Reference variable demonstration (both variables point to same object)
        Student studentReferenceOne = new Student();
        Student studentReferenceTwo = studentReferenceOne;

        // Modifying object through one reference affects the other
        studentReferenceOne.studentName = "Modified Name Example";

        System.out.println("\n--- Reference Variable Demonstration ---");
        System.out.println("studentReferenceTwo.name: " + studentReferenceTwo.studentName);
        System.out.println("studentReferenceTwo.rollNumber: " + studentReferenceTwo.rollNumber);

        // Creating student with custom roll number, name, and marks
        Student customStudent = new Student(23051814, "Ankan Chatterjee", 8.2f);
        System.out.println("\n--- Custom Student ---");
        System.out.println("Custom student name: " + customStudent.studentName);
    }
}

// Class representing a Student entity
// Encapsulates student-related data (roll number, name, marks) and behaviors
class Student {
    // Instance variables (fields)
    int rollNumber;           // Unique identifier for each student
    String studentName;       // Student's full name
    float marksPercentage;    // Student's marks (e.g., 85.4 means 85.4%)

    // Method to display greeting message
    void displayGreeting() {
        System.out.println("Hello! My name is " + this.studentName);
    }

    // Method to change/update student's name
    void updateStudentName(String newName) {
        this.studentName = newName;
    }

    // Copy constructor - creates a new Student object from an existing one
    Student(Student sourceStudent) {
        this.studentName = sourceStudent.studentName;
        this.rollNumber = sourceStudent.rollNumber;
        this.marksPercentage = sourceStudent.marksPercentage;
    }

    // Default constructor - initializes with default values by calling parameterized constructor
    Student() {
        // Calls the 3-parameter constructor with default values
        // Internally equivalent to: new Student(13, "default person", 100.0f);
        this(13, "Default Student Name", 100.0f);
    }

    // Parameterized constructor - initializes all instance variables
    // When creating object like: Student arpit = new Student(17, "Arpit", 89.7f);
    // The keyword 'this' refers to the object being created (arpit in this example)
    Student(int studentRollNumber, String studentFullName, float studentMarks) {
        this.rollNumber = studentRollNumber;
        this.studentName = studentFullName;
        this.marksPercentage = studentMarks;
    }
}

package com.ankan.introduction;

public class WrapperClass {
    public static void main(String[] args) {
//        int a = 10;
//        int b = 30;
//
//        Integer num = 45;

        A pair = new A(10, 30);
        swap(pair);

        System.out.println(pair.a + " " + pair.b);

        final int bonus = 2; // using final fixes the value of the variable
        // bonus = 3; can't be done

        // final A Kunal = new A("Kunal Kushwaha");
        // Kunal.name = "Ankan";
        // When final is used for non-primitive data-types, their instances can be changed but the
        // object itself cannot be changed.
        // Kunal = new com.ankan.com.ankan.packages.A("new object");


    }
    static void swap (A pair) {
        int temp = pair.a;
        pair.a = pair.b;
        pair.b = temp;
    } // Since the swap didn't work, we use a wrapper class.
    // final student Kunal = new Student ()
    // Kunal.name = "new-name"; can be done
    // But Kunal = other object cannot happen
}

class A { // wrapper class
    final int num = 10; // final variable needs to be initialised first. final used for primitive data-types; their
    // values
    // can't be changed. But when final is used for non-primitive data-types, their instances can be changed but the
    // object itself cannot be changed.
    Integer a, b;  // When final is used for non-primitive data-types, their instances can be changed but the object
    // itself cannot be changed. But when an object is used as fields inside another object, it can be changed, as it
    // changes the reference to the object A, not the Integer object itself.

    public A(Integer a, Integer b) {
        this.a = a;
        this.b = b;
    }

    @Override
    protected void finalize() throws Throwable {
        System.out.println("Object is destroyed");
    }
}

package com.ankan.introduction;

public class WrapperClass {
    public static void main(String[] args) {
        // Primitive variables demonstration (commented)
        // int firstValue = 10;
        // int secondValue = 30;

        // Wrapper class demonstration
        // Integer numberWrapper = 45;  // Autoboxing: int → Integer

        // Creating a Pair object to demonstrate swap functionality
        Pair numberPair = new Pair(10, 30);
        swapValues(numberPair);  // Pass by reference (object reference is passed)

        // Swap actually works because we're modifying object fields, not primitive variables
        System.out.println("After swap - first value: " + numberPair.firstValue + 
                           ", second value: " + numberPair.secondValue);

        // 'final' keyword demonstration with primitive type
        final int FIXED_BONUS_AMOUNT = 2;  // Using final makes the variable constant
        // BONUS_AMOUNT = 3;  // Compilation error: cannot reassign a final variable

        // 'final' with non-primitive objects demonstration (commented)
        // final Student kunalStudent = new Student("Kunal Kushwaha");
        // kunalStudent.studentName = "Ankan Chatterjee";  // Valid: Can modify object's internal state
        // kunalStudent = new Student("New Student");      // Compilation error: Cannot reassign final reference

        // Explanation:
        // For non-primitive types, 'final' prevents reassigning the reference variable
        // BUT the object's internal fields CAN still be modified
    }

    // Swap method that modifies the Pair object's fields
    // This works because objects are passed by reference (the reference is passed by value)
    static void swapValues(Pair numberPairs) {
        int temporaryStorage = numberPairs.firstValue;
        numberPairs.firstValue = numberPairs.secondValue;
        numberPairs.secondValue = temporaryStorage;
    }
}

// Wrapper class that holds two integer values
class Pair {
    // Instance variables (wrapped in a container object)
    Integer firstValue;   // Wrapper class for int (can be null)
    Integer secondValue;  // Wrapper class for int (can be null)

    // Constructor to initialize the Pair object
    public Pair(Integer firstNumber, Integer secondNumber) {
        this.firstValue = firstNumber;
        this.secondValue = secondNumber;
    }

    // Final variable demonstration (commented)
    // final int CONSTANT_VALUE = 10;  // Must be initialized when declared
    // For primitives: 'final' prevents value modification
    // For non-primitives: 'final' prevents reference reassignment (but object state can change)

    // Garbage collection demonstration method
    @Override
    protected void finalize() throws Throwable {
        System.out.println("Pair object has been destroyed by garbage collector");
        super.finalize();
    }
}

// Additional educational notes:
// 
// 1. Wrapper Classes (Integer, Double, Boolean, etc.):
//    - Convert primitives to objects
//    - Provide utility methods (parsing, conversion, etc.)
//    - Enable use of primitives in Collections (ArrayList<Integer>, etc.)
//
// 2. Autoboxing: Automatic conversion primitive → wrapper (int → Integer)
// 3. Unboxing: Automatic conversion wrapper → primitive (Integer → int)
//
// 4. 'final' keyword behavior:
//    - Primitive: Value cannot be changed
//    - Object reference: Reference cannot point to new object, but object's fields can be modified
//    - Method: Cannot be overridden by subclasses
//    - Class: Cannot be extended
//
// 5. Pass by Value vs Reference in Java:
//    - Primitives passed by value (copy) - original unchanged
//    - Objects passed by reference value - object contents can be modified

