        // Only ONE instance of Singleton class can ever be created

        Singleton firstInstance = Singleton.getInstance();
        Singleton secondInstance = Singleton.getInstance();
        Singleton thirdInstance = Singleton.getInstance();

        // All three reference variables point to the exact same object in memory
        // This ensures only one instance exists throughout the application

        System.out.println("--- Singleton Pattern Demonstration ---");
        System.out.println("First instance hashcode: " + firstInstance.hashCode());
        System.out.println("Second instance hashcode: " + secondInstance.hashCode());
        System.out.println("Third instance hashcode: " + thirdInstance.hashCode());
        System.out.println("All three references point to the SAME object: " + 
                           (firstInstance == secondInstance && secondInstance == thirdInstance));

        // Accessing a class from another package (com.ankan.access.A)
        A externalClassObject = new A(10, "Sample Name");

        // Demonstrating getter method usage (public access)
        int retrievedValue = externalClassObject.getNumValue();
        System.out.println("\nRetrieved value using getter: " + retrievedValue);

        // Direct field access would cause compilation error if field is protected/private
        // int directAccess = externalClassObject.numValue; // ERROR: Cannot access protected field from different package
    }
}

