    // Validate a string
    boolean isValid = ParenthesesGenerator.isValidParentheses("(()())");
    System.out.println("\nIs '(()())' valid? " + isValid); // true

    // Print formatted output
    ParenthesesGenerator.printAllParenthesesCombinations(3);
}

