/**
 * An implementation of the Arithmetic Coding algorithm.
 *
 * <p>
 * Arithmetic coding is a form of entropy encoding used in lossless data
 * compression. It encodes an entire message into a single number, a fraction n
 * where (0.0 <= n < 1.0). Unlike Huffman coding, which assigns a specific
 * bit sequence to each symbol, arithmetic coding represents the message as a
 * sub-interval of the [0, 1) interval.
 * </p>
 *
 * <p>
 * This implementation uses BigDecimal for precision to handle the shrinking
 * intervals, making it suitable for educational purposes to demonstrate the
 * core logic.
 * </p>
 *
 * <p>
 * Time Complexity: O(n*m) for compression and decompression where n is the
 * length of the input and m is the number of unique symbols, due to the need
 * to calculate symbol probabilities.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Arithmetic_coding">Wikipedia:
 * Arithmetic coding</a></li>
 * </ul>
 * </p>
 */
public final class ArithmeticCoding {

private ArithmeticCoding() {
}

/**
 * Compresses a string using the Arithmetic Coding algorithm.
 *
 * @param inputData The string to be compressed.
 * @return The compressed representation as a BigDecimal number.
 * @throws IllegalArgumentException if the input string is null or empty.
 */
public static BigDecimal compress(String inputData) {
if (inputData == null || inputData.isEmpty()) {
throw new IllegalArgumentException("Input string cannot be null or empty.");
}
Map<Character, SymbolValue> probabilityMap = buildProbabilityTable(inputData);
BigDecimal intervalLow = BigDecimal.ZERO;
BigDecimal intervalHigh = BigDecimal.ONE;
for (char currentSymbol : inputData.toCharArray()) {
BigDecimal currentRange = intervalHigh.subtract(intervalLow);
SymbolValue symbolData = probabilityMap.get(currentSymbol);
intervalHigh = intervalLow.add(currentRange.multiply(symbolData.upperBound()));
intervalLow = intervalLow.add(currentRange.multiply(symbolData.lowerBound()));
}
return intervalLow;
}

/**
 * Decompresses a BigDecimal number back into the original string.
 *
 * @param compressedData The compressed BigDecimal number.
 * @param originalLength The length of the original uncompressed string.
 * @param probabilityMap The probability table used during compression.
 * @return The original, uncompressed string.
 */
public static String decompress(BigDecimal compressedData, int originalLength, Map<Character, SymbolValue> probabilityMap) {
StringBuilder restoredText = new StringBuilder();
List<Map.Entry<Character, SymbolValue>> sortedEntries = new ArrayList<>(probabilityMap.entrySet());
sortedEntries.sort(Map.Entry.comparingByKey());
BigDecimal currentLow = BigDecimal.ZERO;
BigDecimal currentHigh = BigDecimal.ONE;
for (int step = 0; step < originalLength; step++) {
BigDecimal rangeSize = currentHigh.subtract(currentLow);
for (Map.Entry<Character, SymbolValue> entry : sortedEntries) {
SymbolValue symbolData = entry.getValue();
BigDecimal symbolLower = currentLow.add(rangeSize.multiply(symbolData.lowerBound()));
BigDecimal symbolUpper = currentLow.add(rangeSize.multiply(symbolData.upperBound()));
if (compressedData.compareTo(symbolLower) >= 0 && compressedData.compareTo(symbolUpper) < 0) {
restoredText.append(entry.getKey());
currentLow = symbolLower;
currentHigh = symbolUpper;
break;
}
}
}
return restoredText.toString();
}

/**
 * Calculates the frequency and probability range for each character in the
 * input string in a deterministic order.
 *
 * @param sourceText The input string.
 * @return A map from each character to a Symbol object containing its
 * probability range.
 */
public static Map<Character, SymbolValue> buildProbabilityTable(String sourceText) {
Map<Character, Integer> frequencyMap = new HashMap<>();
for (char currentChar : sourceText.toCharArray()) {
frequencyMap.put(currentChar, frequencyMap.getOrDefault(currentChar, 0) + 1);
}
List<Character> sortedKeys = new ArrayList<>(frequencyMap.keySet());
Collections.sort(sortedKeys);
Map<Character, SymbolValue> probabilityMap = new HashMap<>();
BigDecimal cumulativeLower = BigDecimal.ZERO;
int totalChars = sourceText.length();
for (char currentSymbol : sortedKeys) {
BigDecimal symbolProbability = BigDecimal.valueOf(frequencyMap.get(currentSymbol)).divide(BigDecimal.valueOf(totalChars), MathContext.DECIMAL128);
BigDecimal cumulativeUpper = cumulativeLower.add(symbolProbability);
probabilityMap.put(currentSymbol, new SymbolValue(cumulativeLower, cumulativeUpper));
cumulativeLower = cumulativeUpper;
}
return probabilityMap;
}

/**
 * Helper class to store the probability range [low, high) for a symbol.
 */
public record SymbolValue(BigDecimal lowerBound, BigDecimal upperBound) {
}
}

package com.thealgorithms.compression;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * Implementation of the Burrows-Wheeler Transform (BWT) and its inverse.
 * <p>
 * BWT is a reversible data transformation algorithm that rearranges a string into runs of
 * similar characters. While not a compression algorithm itself, it significantly improves
 * the compressibility of data for subsequent algorithms like Move-to-Front encoding and
 * Run-Length Encoding.
 * </p>
 *
 * <p>The transform works by:
 * <ol>
 *   <li>Generating all rotations of the input string</li>
 *   <li>Sorting these rotations lexicographically</li>
 *   <li>Taking the last column of the sorted matrix as output</li>
 *   <li>Recording the index of the original string in the sorted matrix</li>
 * </ol>
 * </p>
 *
 * <p><b>Important:</b> The input string should end with a unique end-of-string marker
 * (typically '$') that:
 * <ul>
 *   <li>Does not appear anywhere else in the text</li>
 *   <li>Is lexicographically smaller than all other characters</li>
 *   <li>Ensures unique rotations and enables correct inverse transformation</li>
 * </ul>
 * Without this marker, the inverse transform may not correctly reconstruct the original string.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n² log n) where n is the string length</li>
 *   <li>Inverse transform: O(n) using the LF-mapping technique</li>
 * </ul>
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:  "banana$"
 * Output: BWTResult("annb$aa", 4)
 *         - "annb$aa" is the transformed string (groups similar characters)
 *         - 4 is the index of the original string in the sorted rotations
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Burrows%E2%80%93Wheeler_transform">Burrows–Wheeler transform (Wikipedia)</a>
 */
public final class BurrowsWheelerTransform {

    private BurrowsWheelerTransform() {
    }

    /**
     * A container for the result of the forward BWT.
     * <p>
     * Contains the transformed string and the index of the original string
     * in the sorted rotations matrix, both of which are required for the
     * inverse transformation.
     * </p>
     */
    public static class BWTResult {
        /** The transformed string (last column of the sorted rotation matrix) */
        public final String transformed;

        /** The index of the original string in the sorted rotations matrix */
        public final int originalIndex;

        /**
         * Constructs a BWTResult with the transformed string and original index.
         *
         * @param transformed the transformed string (L-column)
         * @param originalIndex the index of the original string in sorted rotations
         */
        public BWTResult(String transformed, int originalIndex) {
            this.transformed = transformed;
            this.originalIndex = originalIndex;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (obj == null || getClass() != obj.getClass()) {
                return false;
            }
            BWTResult bwtResult = (BWTResult) obj;
            return originalIndex == bwtResult.originalIndex && transformed.equals(bwtResult.transformed);
        }

        @Override
        public int hashCode() {
            return 31 * transformed.hashCode() + originalIndex;
        }

        @Override
        public String toString() {
            return "BWTResult[transformed=" + transformed + ", originalIndex=" + originalIndex + "]";
        }
    }

    /**
     * Performs the forward Burrows-Wheeler Transform on the input string.
     * <p>
     * The algorithm generates all cyclic rotations of the input, sorts them
     * lexicographically, and returns the last column of this sorted matrix
     * along with the position of the original string.
     * </p>
     *
     * <p><b>Note:</b> It is strongly recommended that the input string ends with
     * a unique end-of-string marker (e.g., '$') that is lexicographically smaller
     * than any other character in the string. This ensures correct inversion.</p>
     *
     * @param text the input string to transform; must not be {@code null}
     * @return a {@link BWTResult} object containing the transformed string (L-column)
     *         and the index of the original string in the sorted rotations matrix;
     *         returns {@code BWTResult("", -1)} for empty input
     * @throws NullPointerException if {@code text} is {@code null}
     */
    public static BWTResult transform(String text) {
        if (text == null || text.isEmpty()) {
            return new BWTResult("", -1);
        }

        int n = text.length();

        // Generate all rotations of the input string
        String[] rotations = new String[n];
        for (int i = 0; i < n; i++) {
            rotations[i] = text.substring(i) + text.substring(0, i);
        }

        // Sort rotations lexicographically
        Arrays.sort(rotations);
        int originalIndex = Arrays.binarySearch(rotations, text);
        StringBuilder lastColumn = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            lastColumn.append(rotations[i].charAt(n - 1));
        }

        return new BWTResult(lastColumn.toString(), originalIndex);
    }

    /**
     * Performs the inverse Burrows-Wheeler Transform using the LF-mapping technique.
     * <p>
     * The LF-mapping (Last-First mapping) is an efficient method to reconstruct
     * the original string from the BWT output without explicitly reconstructing
     * the entire sorted rotations matrix.
     * </p>
     *
     * <p>The algorithm works by:
     * <ol>
     *   <li>Creating the first column by sorting the BWT string</li>
     *   <li>Building a mapping from first column indices to last column indices</li>
     *   <li>Following this mapping starting from the original index to reconstruct the string</li>
     * </ol>
     * </p>
     *
     * @param bwtString the transformed string (L-column) from the forward transform; must not be {@code null}
     * @param originalIndex the index of the original string row from the forward transform;
     *                      use -1 for empty strings
     * @return the original, untransformed string; returns empty string if input is empty or {@code originalIndex} is -1
     * @throws NullPointerException if {@code bwtString} is {@code null}
     * @throws IllegalArgumentException if {@code originalIndex} is out of valid range (except -1)
     */
    public static String inverseTransform(String bwtString, int originalIndex) {
        if (bwtString == null || bwtString.isEmpty() || originalIndex == -1) {
            return "";
        }

        int n = bwtString.length();
        if (originalIndex < 0 || originalIndex >= n) {
            throw new IllegalArgumentException("Original index must be between 0 and " + (n - 1) + ", got: " + originalIndex);
        }

        char[] lastColumn = bwtString.toCharArray();
        char[] firstColumn = bwtString.toCharArray();
        Arrays.sort(firstColumn);

        // Create the "next" array for LF-mapping.
        // next[i] stores the row index in the last column that corresponds to firstColumn[i]
        int[] next = new int[n];

        // Track the count of each character seen so far in the last column
        Map<Character, Integer> countMap = new HashMap<>();

        // Store the first occurrence index of each character in the first column
        Map<Character, Integer> firstOccurrence = new HashMap<>();

        for (int i = 0; i < n; i++) {
            if (!firstOccurrence.containsKey(firstColumn[i])) {
                firstOccurrence.put(firstColumn[i], i);
            }
        }

        // Build the LF-mapping
        for (int i = 0; i < n; i++) {
            char c = lastColumn[i];
            int count = countMap.getOrDefault(c, 0);
            int firstIndex = firstOccurrence.get(c);
            next[firstIndex + count] = i;
            countMap.put(c, count + 1);
        }

        // Reconstruct the original string by following the LF-mapping
        StringBuilder originalString = new StringBuilder(n);
        int currentRow = originalIndex;
        for (int i = 0; i < n; i++) {
            originalString.append(firstColumn[currentRow]);
            currentRow = next[currentRow];
        }

        return originalString.toString();
    }
}

package com.thealgorithms.compression;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * Implementation of the Burrows-Wheeler Transform (BWT) and its inverse.
 * <p>
 * BWT is a reversible data transformation algorithm that rearranges a string into runs of
 * similar characters. While not a compression algorithm itself, it significantly improves
 * the compressibility of data for subsequent algorithms like Move-to-Front encoding and
 * Run-Length Encoding.
 * </p>
 *
 * <p>The transform works by:
 * <ol>
 *   <li>Generating all rotations of the input string</li>
 *   <li>Sorting these rotations lexicographically</li>
 *   <li>Taking the last column of the sorted matrix as output</li>
 *   <li>Recording the index of the original string in the sorted matrix</li>
 * </ol>
 * </p>
 *
 * <p><b>Important:</b> The input string should end with a unique end-of-string marker
 * (typically '$') that:
 * <ul>
 *   <li>Does not appear anywhere else in the text</li>
 *   <li>Is lexicographically smaller than all other characters</li>
 *   <li>Ensures unique rotations and enables correct inverse transformation</li>
 * </ul>
 * Without this marker, the inverse transform may not correctly reconstruct the original string.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n² log n) where n is the string length</li>
 *   <li>Inverse transform: O(n) using the LF-mapping technique</li>
 * </ul>
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:  "banana$"
 * Output: BWTResult("annb$aa", 4)
 *         - "annb$aa" is the transformed string (groups similar characters)
 *         - 4 is the index of the original string in the sorted rotations
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Burrows%E2%80%93Wheeler_transform">Burrows–Wheeler transform (Wikipedia)</a>
 */
public final class BurrowsWheelerTransform {

private BurrowsWheelerTransform() {
}

/**
 * A container for the result of the forward BWT.
 * <p>
 * Contains the transformed string and the index of the original string
 * in the sorted rotations matrix, both of which are required for the
 * inverse transformation.
 * </p>
 */
public static class TransformResult {
public final String encodedData;
public final int originalPosition;

public TransformResult(String encodedData, int originalPosition) {
this.encodedData = encodedData;
this.originalPosition = originalPosition;
}

@Override
public boolean equals(Object otherObject) {
if (this == otherObject) return true;
if (otherObject == null || getClass() != otherObject.getClass()) return false;
TransformResult that = (TransformResult) otherObject;
return originalPosition == that.originalPosition && encodedData.equals(that.encodedData);
}

@Override
public int hashCode() {
return 31 * encodedData.hashCode() + originalPosition;
}

@Override
public String toString() {
return "TransformResult[encodedData=" + encodedData + ", originalPosition=" + originalPosition + "]";
}
}

/**
 * Performs the forward Burrows-Wheeler Transform on the input string.
 * <p>
 * The algorithm generates all cyclic rotations of the input, sorts them
 * lexicographically, and returns the last column of this sorted matrix
 * along with the position of the original string.
 * </p>
 *
 * <p><b>Note:</b> It is strongly recommended that the input string ends with
 * a unique end-of-string marker (e.g., '$') that is lexicographically smaller
 * than any other character in the string. This ensures correct inversion.</p>
 *
 * @param sourceText the input string to transform; must not be {@code null}
 * @return a {@link TransformResult} object containing the transformed string (L-column)
 *         and the index of the original string in the sorted rotations matrix;
 *         returns {@code TransformResult("", -1)} for empty input
 * @throws NullPointerException if {@code sourceText} is {@code null}
 */
public static TransformResult encode(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return new TransformResult("", -1);
}
int textLength = sourceText.length();
String[] rotationArray = new String[textLength];
for (int offset = 0; offset < textLength; offset++) {
rotationArray[offset] = sourceText.substring(offset) + sourceText.substring(0, offset);
}
Arrays.sort(rotationArray);
int originalIndex = Arrays.binarySearch(rotationArray, sourceText);
StringBuilder lastColumnBuilder = new StringBuilder(textLength);
for (int index = 0; index < textLength; index++) {
lastColumnBuilder.append(rotationArray[index].charAt(textLength - 1));
}
return new TransformResult(lastColumnBuilder.toString(), originalIndex);
}

/**
 * Performs the inverse Burrows-Wheeler Transform using the LF-mapping technique.
 * <p>
 * The LF-mapping (Last-First mapping) is an efficient method to reconstruct
 * the original string from the BWT output without explicitly reconstructing
 * the entire sorted rotations matrix.
 * </p>
 *
 * <p>The algorithm works by:
 * <ol>
 *   <li>Creating the first column by sorting the BWT string</li>
 *   <li>Building a mapping from first column indices to last column indices</li>
 *   <li>Following this mapping starting from the original index to reconstruct the string</li>
 * </ol>
 * </p>
 *
 * @param encodedData the transformed string (L-column) from the forward transform; must not be {@code null}
 * @param originalPosition the index of the original string row from the forward transform;
 *                      use -1 for empty strings
 * @return the original, untransformed string; returns empty string if input is empty or {@code originalPosition} is -1
 * @throws NullPointerException if {@code encodedData} is {@code null}
 * @throws IllegalArgumentException if {@code originalPosition} is out of valid range (except -1)
 */
public static String decode(String encodedData, int originalPosition) {
if (encodedData == null || encodedData.isEmpty() || originalPosition == -1) {
return "";
}
int dataLength = encodedData.length();
if (originalPosition < 0 || originalPosition >= dataLength) {
throw new IllegalArgumentException("Original index must be between 0 and " + (dataLength - 1) + ", got: " + originalPosition);
}
char[] lastColumnChars = encodedData.toCharArray();
char[] firstColumnChars = encodedData.toCharArray();
Arrays.sort(firstColumnChars);
int[] nextMapping = new int[dataLength];
Map<Character, Integer> charCounter = new HashMap<>();
Map<Character, Integer> firstOccurrenceMap = new HashMap<>();
for (int index = 0; index < dataLength; index++) {
if (!firstOccurrenceMap.containsKey(firstColumnChars[index])) {
firstOccurrenceMap.put(firstColumnChars[index], index);
}
}
for (int index = 0; index < dataLength; index++) {
char currentChar = lastColumnChars[index];
int currentCount = charCounter.getOrDefault(currentChar, 0);
int firstOccurrenceIndex = firstOccurrenceMap.get(currentChar);
nextMapping[firstOccurrenceIndex + currentCount] = index;
charCounter.put(currentChar, currentCount + 1);
}
StringBuilder restoredText = new StringBuilder(dataLength);
int currentRow = originalPosition;
for (int step = 0; step < dataLength; step++) {
restoredText.append(firstColumnChars[currentRow]);
currentRow = nextMapping[currentRow];
}
return restoredText.toString();
}
}

package com.thealgorithms.compression;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

/**
 * Huffman Coding Compression Algorithm Implementation.
 * <p>
 * Huffman Coding is a popular greedy algorithm used for lossless data compression.
 * It reduces the overall size of data by assigning variable-length, prefix-free
 * binary codes to input characters, ensuring that more frequent characters receive
 * the shortest possible codes.
 * </p>
 * <p>
 * <strong>Key Features:</strong>
 * <ul>
 * <li>Uses a PriorityQueue (min-heap) to efficiently construct the optimal prefix tree.</li>
 * <li>Fail-fast design throws exceptions for unsupported characters and malformed binary payloads.</li>
 * <li>Immutable internal dictionary state prevents external tampering with generated codes.</li>
 * <li>Robust handling of edge cases, including single-character strings and incomplete sequences.</li>
 * </ul>
 * </p>
 * @author Chahat Sandhu, <a href="https://github.com/singhc7">singhc7</a>
 * @see <a href="https://en.wikipedia.org/wiki/Huffman_coding">Huffman Coding (Wikipedia)</a>
 */
public class HuffmanCoding {

    private Node root;
    private final Map<Character, String> huffmanCodes;

    /**
     * Represents a node within the Huffman Tree.
     * Implements {@link Comparable} to allow sorting by frequency in a PriorityQueue.
     */
    private static class Node implements Comparable<Node> {
        final char ch;
        final int freq;
        final Node left;
        final Node right;

        /**
         * Constructs a leaf node containing a specific character and its frequency.
         *
         * @param ch   The character stored in this leaf.
         * @param freq The frequency of occurrence of the character.
         */
        Node(char ch, int freq) {
            this.ch = ch;
            this.freq = freq;
            this.left = null;
            this.right = null;
        }

        /**
         * Constructs an internal node that merges two child nodes.
         * The character is defaulted to the null character ('\0').
         *
         * @param freq  The combined frequency of the left and right child nodes.
         * @param left  The left child node.
         * @param right The right child node.
         */
        Node(int freq, Node left, Node right) {
            this.ch = '\0';
            this.freq = freq;
            this.left = left;
            this.right = right;
        }

        /**
         * Determines if the current node is a leaf (contains no children).
         *
         * @return {@code true} if both left and right children are null, {@code false} otherwise.
         */
        boolean isLeaf() {
            return left == null && right == null;
        }

        /**
         * Compares this node with another node based on their frequencies.
         * Used by the PriorityQueue to maintain the min-heap property.
         *
         * @param other The other Node to compare against.
         * @return A negative integer, zero, or a positive integer as this node's frequency
         * is less than, equal to, or greater than the specified node's frequency.
         */
        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.freq, other.freq);
        }
    }

    /**
     * Initializes the Huffman Tree and generates immutable prefix-free codes
     * based on the character frequencies in the provided text.
     *
     * @param text The input string used to calculate frequencies and build the optimal tree.
     * If null or empty, an empty tree and dictionary are created.
     */
    public HuffmanCoding(String text) {
        if (text == null || text.isEmpty()) {
            this.huffmanCodes = Collections.emptyMap();
            return;
        }

        Map<Character, String> tempCodes = new HashMap<>();
        buildTree(text);
        generateCodes(root, "", tempCodes);

        if (tempCodes.size() == 1) {
            tempCodes.put(root.ch, "0");
        }

        this.huffmanCodes = Collections.unmodifiableMap(tempCodes);
    }

    /**
     * Computes character frequencies and constructs the Huffman Tree using a min-heap.
     * The optimal tree is built by repeatedly extracting the two lowest-frequency nodes
     * and merging them until a single root node remains.
     *
     * @param text The input text to analyze.
     */
    private void buildTree(String text) {
        Map<Character, Integer> freqMap = new HashMap<>();
        for (char c : text.toCharArray()) {
            freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (Map.Entry<Character, Integer> entry : freqMap.entrySet()) {
            pq.add(new Node(entry.getKey(), entry.getValue()));
        }

        while (pq.size() > 1) {
            Node left = pq.poll();
            Node right = pq.poll();
            pq.add(new Node(left.freq + right.freq, left, right));
        }

        root = pq.poll();
    }

    /**
     * Recursively traverses the Huffman Tree to generate prefix-free binary codes.
     * Left traversals append a '0' to the code, while right traversals append a '1'.
     *
     * @param node The current node in the traversal.
     * @param code The accumulated binary string for the current path.
     * @param map  The temporary dictionary to populate with the final character-to-code mappings.
     */
    private void generateCodes(Node node, String code, Map<Character, String> map) {
        if (node == null) {
            return;
        }
        if (node.isLeaf()) {
            map.put(node.ch, code);
            return;
        }
        generateCodes(node.left, code + "0", map);
        generateCodes(node.right, code + "1", map);
    }

    /**
     * Encodes the given plaintext string into a binary string using the generated Huffman dictionary.
     *
     * @param text The plaintext string to compress.
     * @return A string of '0's and '1's representing the compressed data.
     * Returns an empty string if the input is null or empty.
     * @throws IllegalStateException    If attempting to encode when the Huffman tree is empty.
     * @throws IllegalArgumentException If the input text contains a character not present
     * in the original text used to build the tree.
     */
    public String encode(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        if (root == null) {
            throw new IllegalStateException("Huffman tree is empty.");
        }

        StringBuilder sb = new StringBuilder();
        for (char c : text.toCharArray()) {
            if (!huffmanCodes.containsKey(c)) {
                throw new IllegalArgumentException(String.format("Character '%c' (U+%04X) not found in Huffman dictionary.", c, (int) c));
            }
            sb.append(huffmanCodes.get(c));
        }
        return sb.toString();
    }

    /**
     * Decodes the given binary string back into the original plaintext using the Huffman Tree.
     * Validates the integrity of the binary payload during traversal.
     *
     * @param encodedText The binary string of '0's and '1's to decompress.
     * @return The reconstructed plaintext string. Returns an empty string if the input is null or empty.
     * @throws IllegalStateException    If attempting to decode when the Huffman tree is empty.
     * @throws IllegalArgumentException If the binary string contains characters other than '0' or '1',
     * or if the sequence ends abruptly without reaching a leaf node.
     */
    public String decode(String encodedText) {
        if (encodedText == null || encodedText.isEmpty()) {
            return "";
        }
        if (root == null) {
            throw new IllegalStateException("Huffman tree is empty.");
        }

        StringBuilder sb = new StringBuilder();

        if (root.isLeaf()) {
            for (char bit : encodedText.toCharArray()) {
                if (bit != '0') {
                    throw new IllegalArgumentException("Invalid binary sequence for single-character tree.");
                }
                sb.append(root.ch);
            }
            return sb.toString();
        }

        Node current = root;
        for (char bit : encodedText.toCharArray()) {
            if (bit != '0' && bit != '1') {
                throw new IllegalArgumentException("Encoded text contains invalid characters: " + bit);
            }

            current = (bit == '0') ? current.left : current.right;

            if (current.isLeaf()) {
                sb.append(current.ch);
                current = root;
            }
        }

        if (current != root) {
            throw new IllegalArgumentException("Malformed encoded string: incomplete sequence ending.");
        }

        return sb.toString();
    }

    /**
     * Retrieves the generated Huffman dictionary mapping characters to their binary codes.
     *
     * @return An unmodifiable map containing the character-to-binary-code mappings to prevent
     * external mutation of the algorithm's state.
     */
    public Map<Character, String> getHuffmanCodes() {
        return huffmanCodes;
    }
}

package com.thealgorithms.compression;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

/**
 * Huffman Coding Compression Algorithm Implementation.
 * <p>
 * Huffman Coding is a popular greedy algorithm used for lossless data compression.
 * It reduces the overall size of data by assigning variable-length, prefix-free
 * binary codes to input characters, ensuring that more frequent characters receive
 * the shortest possible codes.
 * </p>
 * <p>
 * <strong>Key Features:</strong>
 * <ul>
 * <li>Uses a PriorityQueue (min-heap) to efficiently construct the optimal prefix tree.</li>
 * <li>Fail-fast design throws exceptions for unsupported characters and malformed binary payloads.</li>
 * <li>Immutable internal dictionary state prevents external tampering with generated codes.</li>
 * <li>Robust handling of edge cases, including single-character strings and incomplete sequences.</li>
 * </ul>
 * </p>
 * @author Chahat Sandhu, <a href="https://github.com/singhc7">singhc7</a>
 * @see <a href="https://en.wikipedia.org/wiki/Huffman_coding">Huffman Coding (Wikipedia)</a>
 */
public class HuffmanCoding {

private TreeNode rootNode;
private final Map<Character, String> encodingTable;

private static class TreeNode implements Comparable<TreeNode> {
final char characterValue;
final int frequencyCount;
final TreeNode leftChild;
final TreeNode rightChild;

TreeNode(char characterValue, int frequencyCount) {
this.characterValue = characterValue;
this.frequencyCount = frequencyCount;
this.leftChild = null;
this.rightChild = null;
}

TreeNode(int frequencyCount, TreeNode leftChild, TreeNode rightChild) {
this.characterValue = '\0';
this.frequencyCount = frequencyCount;
this.leftChild = leftChild;
this.rightChild = rightChild;
}

boolean isLeafNode() {
return leftChild == null && rightChild == null;
}

@Override
public int compareTo(TreeNode otherNode) {
return Integer.compare(this.frequencyCount, otherNode.frequencyCount);
}
}

/**
 * Initializes the Huffman Tree and generates immutable prefix-free codes
 * based on the character frequencies in the provided text.
 *
 * @param sourceText The input string used to calculate frequencies and build the optimal tree.
 * If null or empty, an empty tree and dictionary are created.
 */
public HuffmanCoding(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
this.encodingTable = Collections.emptyMap();
return;
}
Map<Character, String> temporaryTable = new HashMap<>();
buildEncodingTree(sourceText);
generateCodes(rootNode, "", temporaryTable);
if (temporaryTable.size() == 1) {
temporaryTable.put(rootNode.characterValue, "0");
}
this.encodingTable = Collections.unmodifiableMap(temporaryTable);
}

/**
 * Computes character frequencies and constructs the Huffman Tree using a min-heap.
 * The optimal tree is built by repeatedly extracting the two lowest-frequency nodes
 * and merging them until a single root node remains.
 *
 * @param sourceText The input text to analyze.
 */
private void buildEncodingTree(String sourceText) {
Map<Character, Integer> frequencyMapping = new HashMap<>();
for (char currentChar : sourceText.toCharArray()) {
frequencyMapping.put(currentChar, frequencyMapping.getOrDefault(currentChar, 0) + 1);
}
PriorityQueue<TreeNode> minHeap = new PriorityQueue<>();
for (Map.Entry<Character, Integer> entry : frequencyMapping.entrySet()) {
minHeap.add(new TreeNode(entry.getKey(), entry.getValue()));
}
while (minHeap.size() > 1) {
TreeNode leftNode = minHeap.poll();
TreeNode rightNode = minHeap.poll();
minHeap.add(new TreeNode(leftNode.frequencyCount + rightNode.frequencyCount, leftNode, rightNode));
}
rootNode = minHeap.poll();
}

/**
 * Recursively traverses the Huffman Tree to generate prefix-free binary codes.
 * Left traversals append a '0' to the code, while right traversals append a '1'.
 *
 * @param currentNode The current node in the traversal.
 * @param currentCode The accumulated binary string for the current path.
 * @param codeMapping The temporary dictionary to populate with the final character-to-code mappings.
 */
private void generateCodes(TreeNode currentNode, String currentCode, Map<Character, String> codeMapping) {
if (currentNode == null) {
return;
}
if (currentNode.isLeafNode()) {
codeMapping.put(currentNode.characterValue, currentCode);
return;
}
generateCodes(currentNode.leftChild, currentCode + "0", codeMapping);
generateCodes(currentNode.rightChild, currentCode + "1", codeMapping);
}

/**
 * Encodes the given plaintext string into a binary string using the generated Huffman dictionary.
 *
 * @param sourceText The plaintext string to compress.
 * @return A string of '0's and '1's representing the compressed data.
 * Returns an empty string if the input is null or empty.
 * @throws IllegalStateException    If attempting to encode when the Huffman tree is empty.
 * @throws IllegalArgumentException If the input text contains a character not present
 * in the original text used to build the tree.
 */
public String encode(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return "";
}
if (rootNode == null) {
throw new IllegalStateException("Huffman tree is empty.");
}
StringBuilder encodedOutput = new StringBuilder();
for (char currentChar : sourceText.toCharArray()) {
if (!encodingTable.containsKey(currentChar)) {
throw new IllegalArgumentException(String.format("Character '%c' (U+%04X) not found in Huffman dictionary.", currentChar, (int) currentChar));
}
encodedOutput.append(encodingTable.get(currentChar));
}
return encodedOutput.toString();
}

/**
 * Decodes the given binary string back into the original plaintext using the Huffman Tree.
 * Validates the integrity of the binary payload during traversal.
 *
 * @param encodedData The binary string of '0's and '1's to decompress.
 * @return The reconstructed plaintext string. Returns an empty string if the input is null or empty.
 * @throws IllegalStateException    If attempting to decode when the Huffman tree is empty.
 * @throws IllegalArgumentException If the binary string contains characters other than '0' or '1',
 * or if the sequence ends abruptly without reaching a leaf node.
 */
public String decode(String encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
if (rootNode == null) {
throw new IllegalStateException("Huffman tree is empty.");
}
StringBuilder decodedOutput = new StringBuilder();
if (rootNode.isLeafNode()) {
for (char currentBit : encodedData.toCharArray()) {
if (currentBit != '0') {
throw new IllegalArgumentException("Invalid binary sequence for single-character tree.");
}
decodedOutput.append(rootNode.characterValue);
}
return decodedOutput.toString();
}
TreeNode traversalNode = rootNode;
for (char currentBit : encodedData.toCharArray()) {
if (currentBit != '0' && currentBit != '1') {
throw new IllegalArgumentException("Encoded text contains invalid characters: " + currentBit);
}
traversalNode = (currentBit == '0') ? traversalNode.leftChild : traversalNode.rightChild;
if (traversalNode.isLeafNode()) {
decodedOutput.append(traversalNode.characterValue);
traversalNode = rootNode;
}
}
if (traversalNode != rootNode) {
throw new IllegalArgumentException("Malformed encoded string: incomplete sequence ending.");
}
return decodedOutput.toString();
}

/**
 * Retrieves the generated Huffman dictionary mapping characters to their binary codes.
 *
 * @return An unmodifiable map containing the character-to-binary-code mappings to prevent
 * external mutation of the algorithm's state.
 */
public Map<Character, String> getHuffmanCodes() {
return encodingTable;
}
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.List;

/**
 * An implementation of the Lempel-Ziv 77 (LZ77) compression algorithm.
 * <p>
 * LZ77 is a lossless data compression algorithm that works by finding repeated
 * occurrences of data in a sliding window. It replaces subsequent occurrences
 * with references (offset, length) to the first occurrence within the window.
 * </p>
 * <p>
 * This implementation uses a simple sliding window and lookahead buffer approach.
 * Output format is a sequence of tuples (offset, length, next_character).
 * </p>
 * <p>
 * Time Complexity: O(n*W) in this naive implementation, where n is the input length
 * and W is the window size, due to the search for the longest match. More advanced
 * data structures (like suffix trees) can improve this.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ77">Wikipedia: LZ77</a></li>
 * </ul>
 * </p>
 */
public final class LZ77 {

    private static final int DEFAULT_WINDOW_SIZE = 4096;
    private static final int DEFAULT_LOOKAHEAD_BUFFER_SIZE = 16;
    private static final char END_OF_STREAM = '\u0000';
    private LZ77() {
    }

    /**
     * Represents a token in the LZ77 compressed output.
     * Stores the offset back into the window, the length of the match,
     * and the next character after the match (or END_OF_STREAM if at end).
     */
    public record Token(int offset, int length, char nextChar) {
    }

    /**
     * Compresses the input text using the LZ77 algorithm.
     *
     * @param text The input string to compress. Must not be null.
     * @param windowSize The size of the sliding window (search buffer). Must be positive.
     * @param lookaheadBufferSize The size of the lookahead buffer. Must be positive.
     * @return A list of {@link Token} objects representing the compressed data.
     * @throws IllegalArgumentException if windowSize or lookaheadBufferSize are not positive.
     */
    public static List<Token> compress(String text, int windowSize, int lookaheadBufferSize) {
        if (text == null) {
            return new ArrayList<>();
        }
        if (windowSize <= 0 || lookaheadBufferSize <= 0) {
            throw new IllegalArgumentException("Window size and lookahead buffer size must be positive.");
        }

        List<Token> compressedOutput = new ArrayList<>();
        int currentPosition = 0;

        while (currentPosition < text.length()) {
            int bestMatchDistance = 0;
            int bestMatchLength = 0;

            // Define the start of the search window
            int searchBufferStart = Math.max(0, currentPosition - windowSize);
            // Define the end of the lookahead buffer (don't go past text length)
            int lookaheadEnd = Math.min(currentPosition + lookaheadBufferSize, text.length());

            // Search for the longest match in the window
            for (int i = searchBufferStart; i < currentPosition; i++) {
                int currentMatchLength = 0;

                // Check how far the match extends into the lookahead buffer
                // This allows for overlapping matches (e.g., "aaa" can match with offset 1)
                while (currentPosition + currentMatchLength < lookaheadEnd) {
                    int sourceIndex = i + currentMatchLength;

                    // Handle overlapping matches (run-length encoding within LZ77)
                    // When we've matched beyond our starting position, wrap around using modulo
                    if (sourceIndex >= currentPosition) {
                        int offset = currentPosition - i;
                        sourceIndex = i + (currentMatchLength % offset);
                    }

                    if (text.charAt(sourceIndex) == text.charAt(currentPosition + currentMatchLength)) {
                        currentMatchLength++;
                    } else {
                        break;
                    }
                }

                // If this match is longer than the best found so far
                if (currentMatchLength > bestMatchLength) {
                    bestMatchLength = currentMatchLength;
                    bestMatchDistance = currentPosition - i; // Calculate offset from current position
                }
            }

            char nextChar;
            if (currentPosition + bestMatchLength < text.length()) {
                nextChar = text.charAt(currentPosition + bestMatchLength);
            } else {
                nextChar = END_OF_STREAM;
            }

            // Add the token to the output
            compressedOutput.add(new Token(bestMatchDistance, bestMatchLength, nextChar));

            // Move the current position forward
            // If we're at the end and had a match, just move by the match length
            if (nextChar == END_OF_STREAM) {
                currentPosition += bestMatchLength;
            } else {
                currentPosition += bestMatchLength + 1;
            }
        }

        return compressedOutput;
    }

    /**
     * Compresses the input text using the LZ77 algorithm with default buffer sizes.
     *
     * @param text The input string to compress. Must not be null.
     * @return A list of {@link Token} objects representing the compressed data.
     */
    public static List<Token> compress(String text) {
        return compress(text, DEFAULT_WINDOW_SIZE, DEFAULT_LOOKAHEAD_BUFFER_SIZE);
    }

    /**
     * Decompresses a list of LZ77 tokens back into the original string.
     *
     * @param compressedData The list of {@link Token} objects. Must not be null.
     * @return The original, uncompressed string.
     */
    public static String decompress(List<Token> compressedData) {
        if (compressedData == null) {
            return "";
        }

        StringBuilder decompressedText = new StringBuilder();

        for (Token token : compressedData) {
            // Copy matched characters from the sliding window
            if (token.length > 0) {
                int startIndex = decompressedText.length() - token.offset;

                // Handle overlapping matches (e.g., when length > offset)
                for (int i = 0; i < token.length; i++) {
                    decompressedText.append(decompressedText.charAt(startIndex + i));
                }
            }

            // Append the next character (if not END_OF_STREAM)
            if (token.nextChar != END_OF_STREAM) {
                decompressedText.append(token.nextChar);
            }
        }

        return decompressedText.toString();
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.List;

/**
 * An implementation of the Lempel-Ziv 77 (LZ77) compression algorithm.
 * <p>
 * LZ77 is a lossless data compression algorithm that works by finding repeated
 * occurrences of data in a sliding window. It replaces subsequent occurrences
 * with references (offset, length) to the first occurrence within the window.
 * </p>
 * <p>
 * This implementation uses a simple sliding window and lookahead buffer approach.
 * Output format is a sequence of tuples (offset, length, next_character).
 * </p>
 * <p>
 * Time Complexity: O(n*W) in this naive implementation, where n is the input length
 * and W is the window size, due to the search for the longest match. More advanced
 * data structures (like suffix trees) can improve this.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ77">Wikipedia: LZ77</a></li>
 * </ul>
 * </p>
 */
public final class LZ77 {

private static final int DEFAULT_WINDOW_SIZE = 4096;
private static final int DEFAULT_LOOKAHEAD_BUFFER_SIZE = 16;
private static final char END_MARKER = '\u0000';

private LZ77() {
}

/**
 * Represents a token in the LZ77 compressed output.
 * Stores the offset back into the window, the length of the match,
 * and the next character after the match (or END_MARKER if at end).
 */
public record CompressionToken(int distanceOffset, int matchLength, char nextCharacter) {
}

/**
 * Compresses the input text using the LZ77 algorithm.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @param windowSize The size of the sliding window (search buffer). Must be positive.
 * @param lookaheadSize The size of the lookahead buffer. Must be positive.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 * @throws IllegalArgumentException if windowSize or lookaheadSize are not positive.
 */
public static List<CompressionToken> compress(String sourceText, int windowSize, int lookaheadSize) {
if (sourceText == null) {
return new ArrayList<>();
}
if (windowSize <= 0 || lookaheadSize <= 0) {
throw new IllegalArgumentException("Window size and lookahead buffer size must be positive.");
}
List<CompressionToken> encodedTokens = new ArrayList<>();
int currentPos = 0;
while (currentPos < sourceText.length()) {
int bestOffset = 0;
int bestLen = 0;
int searchStart = Math.max(0, currentPos - windowSize);
int lookaheadEnd = Math.min(currentPos + lookaheadSize, sourceText.length());
for (int searchPos = searchStart; searchPos < currentPos; searchPos++) {
int currentLen = 0;
while (currentPos + currentLen < lookaheadEnd) {
int sourceIdx = searchPos + currentLen;
if (sourceIdx >= currentPos) {
int relativeOffset = currentPos - searchPos;
sourceIdx = searchPos + (currentLen % relativeOffset);
}
if (sourceText.charAt(sourceIdx) == sourceText.charAt(currentPos + currentLen)) {
currentLen++;
} else {
break;
}
}
if (currentLen > bestLen) {
bestLen = currentLen;
bestOffset = currentPos - searchPos;
}
}
char nextChar;
if (currentPos + bestLen < sourceText.length()) {
nextChar = sourceText.charAt(currentPos + bestLen);
} else {
nextChar = END_MARKER;
}
encodedTokens.add(new CompressionToken(bestOffset, bestLen, nextChar));
if (nextChar == END_MARKER) {
currentPos += bestLen;
} else {
currentPos += bestLen + 1;
}
}
return encodedTokens;
}

/**
 * Compresses the input text using the LZ77 algorithm with default buffer sizes.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 */
public static List<CompressionToken> compress(String sourceText) {
return compress(sourceText, DEFAULT_WINDOW_SIZE, DEFAULT_LOOKAHEAD_BUFFER_SIZE);
}

/**
 * Decompresses a list of LZ77 tokens back into the original string.
 *
 * @param encodedData The list of {@link CompressionToken} objects. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(List<CompressionToken> encodedData) {
if (encodedData == null) {
return "";
}
StringBuilder decodedText = new StringBuilder();
for (CompressionToken currentToken : encodedData) {
if (currentToken.matchLength() > 0) {
int startIndex = decodedText.length() - currentToken.distanceOffset();
for (int copyPos = 0; copyPos < currentToken.matchLength(); copyPos++) {
decodedText.append(decodedText.charAt(startIndex + copyPos));
}
}
if (currentToken.nextCharacter() != END_MARKER) {
decodedText.append(currentToken.nextCharacter());
}
}
return decodedText.toString();
}
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv 78 (LZ78) compression algorithm.
 * <p>
 * LZ78 is a dictionary-based lossless data compression algorithm. It processes
 * input data sequentially, building a dictionary of phrases encountered so far.
 * It outputs pairs (dictionary_index, next_character), representing
 * the longest match found in the dictionary plus the character that follows it.
 * </p>
 * <p>
 * This implementation builds the dictionary dynamically during compression.
 * The dictionary index 0 represents the empty string (no prefix).
 * </p>
 * <p>
 * Time Complexity: O(n) on average for compression and decompression, assuming
 * efficient dictionary lookups (using a HashMap), where n is the
 * length of the input string.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ78">Wikipedia: LZ78</a></li>
 * </ul>
 * </p>
 */
public final class LZ78 {

    /**
     * Special character used to mark end of stream when needed.
     */
    private static final char END_OF_STREAM = '\u0000';

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private LZ78() {
    }

    /**
     * Represents a token in the LZ78 compressed output.
     * Stores the index of the matching prefix in the dictionary and the next character.
     * Index 0 represents the empty string (no prefix).
     */
    public record Token(int index, char nextChar) {
    }

    /**
     * A node in the dictionary trie structure.
     * Each node represents a phrase and can have child nodes for extended phrases.
     */
    private static final class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        int index = -1; // -1 means not assigned yet
    }

    /**
     * Compresses the input text using the LZ78 algorithm.
     *
     * @param text The input string to compress. Must not be null.
     * @return A list of {@link Token} objects representing the compressed data.
     */
    public static List<Token> compress(String text) {
        if (text == null || text.isEmpty()) {
            return new ArrayList<>();
        }

        List<Token> compressedOutput = new ArrayList<>();
        TrieNode root = new TrieNode();
        int nextDictionaryIndex = 1;

        TrieNode currentNode = root;
        int lastMatchedIndex = 0;

        for (int i = 0; i < text.length(); i++) {
            char currentChar = text.charAt(i);

            if (currentNode.children.containsKey(currentChar)) {
                currentNode = currentNode.children.get(currentChar);
                lastMatchedIndex = currentNode.index;
            } else {
                // Output: (index of longest matching prefix, current character)
                compressedOutput.add(new Token(lastMatchedIndex, currentChar));

                TrieNode newNode = new TrieNode();
                newNode.index = nextDictionaryIndex++;
                currentNode.children.put(currentChar, newNode);

                currentNode = root;
                lastMatchedIndex = 0;
            }
        }

        // Handle remaining phrase at end of input
        if (currentNode != root) {
            compressedOutput.add(new Token(lastMatchedIndex, END_OF_STREAM));
        }

        return compressedOutput;
    }

    /**
     * Decompresses a list of LZ78 tokens back into the original string.
     *
     * @param compressedData The list of {@link Token} objects. Must not be null.
     * @return The original, uncompressed string.
     */
    public static String decompress(List<Token> compressedData) {
        if (compressedData == null || compressedData.isEmpty()) {
            return "";
        }

        StringBuilder decompressedText = new StringBuilder();
        Map<Integer, String> dictionary = new HashMap<>();
        int nextDictionaryIndex = 1;

        for (Token token : compressedData) {
            String prefix = (token.index == 0) ? "" : dictionary.get(token.index);

            if (token.nextChar == END_OF_STREAM) {
                decompressedText.append(prefix);
            } else {
                String currentPhrase = prefix + token.nextChar;
                decompressedText.append(currentPhrase);
                dictionary.put(nextDictionaryIndex++, currentPhrase);
            }
        }

        return decompressedText.toString();
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv 78 (LZ78) compression algorithm.
 * <p>
 * LZ78 is a dictionary-based lossless data compression algorithm. It processes
 * input data sequentially, building a dictionary of phrases encountered so far.
 * It outputs pairs (dictionary_index, next_character), representing
 * the longest match found in the dictionary plus the character that follows it.
 * </p>
 * <p>
 * This implementation builds the dictionary dynamically during compression.
 * The dictionary index 0 represents the empty string (no prefix).
 * </p>
 * <p>
 * Time Complexity: O(n) on average for compression and decompression, assuming
 * efficient dictionary lookups (using a HashMap), where n is the
 * length of the input string.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ78">Wikipedia: LZ78</a></li>
 * </ul>
 * </p>
 */
public final class LZ78 {

/**
 * Special character used to mark end of stream when needed.
 */
private static final char STREAM_END_MARKER = '\u0000';

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private LZ78() {
}

/**
 * Represents a token in the LZ78 compressed output.
 * Stores the index of the matching prefix in the dictionary and the next character.
 * Index 0 represents the empty string (no prefix).
 */
public record CompressionUnit(int dictionaryIndex, char followingChar) {
}

/**
 * A node in the dictionary trie structure.
 * Each node represents a phrase and can have child nodes for extended phrases.
 */
private static final class TrieNode {
Map<Character, TrieNode> childNodes = new HashMap<>();
int assignedIndex = -1;
}

/**
 * Compresses the input text using the LZ78 algorithm.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @return A list of {@link CompressionUnit} objects representing the compressed data.
 */
public static List<CompressionUnit> compress(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return new ArrayList<>();
}
List<CompressionUnit> encodedOutput = new ArrayList<>();
TrieNode rootNode = new TrieNode();
int nextIndex = 1;
TrieNode currentNode = rootNode;
int currentMatchIndex = 0;
for (int position = 0; position < sourceText.length(); position++) {
char currentSymbol = sourceText.charAt(position);
if (currentNode.childNodes.containsKey(currentSymbol)) {
currentNode = currentNode.childNodes.get(currentSymbol);
currentMatchIndex = currentNode.assignedIndex;
} else {
encodedOutput.add(new CompressionUnit(currentMatchIndex, currentSymbol));
TrieNode newDictionaryNode = new TrieNode();
newDictionaryNode.assignedIndex = nextIndex++;
currentNode.childNodes.put(currentSymbol, newDictionaryNode);
currentNode = rootNode;
currentMatchIndex = 0;
}
}
if (currentNode != rootNode) {
encodedOutput.add(new CompressionUnit(currentMatchIndex, STREAM_END_MARKER));
}
return encodedOutput;
}

/**
 * Decompresses a list of LZ78 tokens back into the original string.
 *
 * @param encodedData The list of {@link CompressionUnit} objects. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(List<CompressionUnit> encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
StringBuilder decodedText = new StringBuilder();
Map<Integer, String> phraseDictionary = new HashMap<>();
int nextIndex = 1;
for (CompressionUnit currentUnit : encodedData) {
String prefixValue = (currentUnit.dictionaryIndex() == 0) ? "" : phraseDictionary.get(currentUnit.dictionaryIndex());
if (currentUnit.followingChar() == STREAM_END_MARKER) {
decodedText.append(prefixValue);
} else {
String fullPhrase = prefixValue + currentUnit.followingChar();
decodedText.append(fullPhrase);
phraseDictionary.put(nextIndex++, fullPhrase);
}
}
return decodedText.toString();
}
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv-Welch (LZW) algorithm.
 *
 * <p>
 * LZW is a universal lossless data compression algorithm created by Abraham
 * Lempel, Jacob Ziv, and Terry Welch. It works by building a dictionary of
 * strings encountered during compression and replacing occurrences of those
 * strings with a shorter code.
 * </p>
 *
 * <p>
 * This implementation handles standard ASCII characters and provides methods for
 * both compression and decompression.
 * <ul>
 * <li>Compressing "TOBEORNOTTOBEORTOBEORNOT" results in a list of integer
 * codes.</li>
 * <li>Decompressing that list of codes results back in the original
 * string.</li>
 * </ul>
 * </p>
 *
 * <p>
 * Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Lempel%E2%80%93Ziv%E2%80%93Welch">Wikipedia:
 * Lempel–Ziv–Welch</a></li>
 * </ul>
 * </p>
 */
public final class LZW {

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private LZW() {
    }

    /**
     * Compresses a string using the LZW algorithm.
     *
     * @param uncompressed The string to be compressed. Can be null.
     * @return A list of integers representing the compressed data. Returns an empty
     * list if the input is null or empty.
     */
    public static List<Integer> compress(String uncompressed) {
        if (uncompressed == null || uncompressed.isEmpty()) {
            return new ArrayList<>();
        }

        // Initialize dictionary with single characters (ASCII 0-255)
        int dictSize = 256;
        Map<String, Integer> dictionary = new HashMap<>();
        for (int i = 0; i < dictSize; i++) {
            dictionary.put("" + (char) i, i);
        }

        String w = "";
        List<Integer> result = new ArrayList<>();
        for (char c : uncompressed.toCharArray()) {
            String wc = w + c;
            if (dictionary.containsKey(wc)) {
                // If the new string is in the dictionary, extend the current string
                w = wc;
            } else {
                // Otherwise, output the code for the current string
                result.add(dictionary.get(w));
                // Add the new string to the dictionary
                dictionary.put(wc, dictSize++);
                // Start a new current string
                w = "" + c;
            }
        }

        // Output the code for the last remaining string
        result.add(dictionary.get(w));
        return result;
    }

    /**
     * Decompresses a list of integers back into a string using the LZW algorithm.
     *
     * @param compressed A list of integers representing the compressed data. Can be
     *                   null.
     * @return The original, uncompressed string. Returns an empty string if the
     * input is null or empty.
     */
    public static String decompress(List<Integer> compressed) {
        if (compressed == null || compressed.isEmpty()) {
            return "";
        }

        // Initialize dictionary with single characters (ASCII 0-255)
        int dictSize = 256;
        Map<Integer, String> dictionary = new HashMap<>();
        for (int i = 0; i < dictSize; i++) {
            dictionary.put(i, "" + (char) i);
        }

        // Decompress the first code
        String w = "" + (char) (int) compressed.removeFirst();
        StringBuilder result = new StringBuilder(w);

        for (int k : compressed) {
            String entry;
            if (dictionary.containsKey(k)) {
                // The code is in the dictionary
                entry = dictionary.get(k);
            } else if (k == dictSize) {
                // Special case for sequences like "ababab"
                entry = w + w.charAt(0);
            } else {
                throw new IllegalArgumentException("Bad compressed k: " + k);
            }

            result.append(entry);

            // Add new sequence to the dictionary
            dictionary.put(dictSize++, w + entry.charAt(0));

            w = entry;
        }
        return result.toString();
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv-Welch (LZW) algorithm.
 *
 * <p>
 * LZW is a universal lossless data compression algorithm created by Abraham
 * Lempel, Jacob Ziv, and Terry Welch. It works by building a dictionary of
 * strings encountered during compression and replacing occurrences of those
 * strings with a shorter code.
 * </p>
 *
 * <p>
 * This implementation handles standard ASCII characters and provides methods for
 * both compression and decompression.
 * <ul>
 * <li>Compressing "TOBEORNOTTOBEORTOBEORNOT" results in a list of integer
 * codes.</li>
 * <li>Decompressing that list of codes results back in the original
 * string.</li>
 * </ul>
 * </p>
 *
 * <p>
 * Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Lempel%E2%80%93Ziv%E2%80%93Welch">Wikipedia:
 * Lempel–Ziv–Welch</a></li>
 * </ul>
 * </p>
 */
public final class LZW {

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private LZW() {
}

/**
 * Compresses a string using the LZW algorithm.
 *
 * @param sourceData The string to be compressed. Can be null.
 * @return A list of integers representing the compressed data. Returns an empty
 * list if the input is null or empty.
 */
public static List<Integer> compress(String sourceData) {
if (sourceData == null || sourceData.isEmpty()) {
return new ArrayList<>();
}
int nextCodeValue = 256;
Map<String, Integer> codeDictionary = new HashMap<>();
for (int asciiValue = 0; asciiValue < nextCodeValue; asciiValue++) {
codeDictionary.put("" + (char) asciiValue, asciiValue);
}
String currentSequence = "";
List<Integer> encodedResult = new ArrayList<>();
for (char currentChar : sourceData.toCharArray()) {
String extendedSequence = currentSequence + currentChar;
if (codeDictionary.containsKey(extendedSequence)) {
currentSequence = extendedSequence;
} else {
encodedResult.add(codeDictionary.get(currentSequence));
codeDictionary.put(extendedSequence, nextCodeValue++);
currentSequence = "" + currentChar;
}
}
encodedResult.add(codeDictionary.get(currentSequence));
return encodedResult;
}

/**
 * Decompresses a list of integers back into a string using the LZW algorithm.
 *
 * @param encodedData A list of integers representing the compressed data. Can be
 *                   null.
 * @return The original, uncompressed string. Returns an empty string if the
 * input is null or empty.
 */
public static String decompress(List<Integer> encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
int nextCodeValue = 256;
Map<Integer, String> reverseDictionary = new HashMap<>();
for (int asciiValue = 0; asciiValue < nextCodeValue; asciiValue++) {
reverseDictionary.put(asciiValue, "" + (char) asciiValue);
}
List<Integer> remainingCodes = new ArrayList<>(encodedData);
String currentSequence = reverseDictionary.get(remainingCodes.removeFirst());
StringBuilder decodedResult = new StringBuilder(currentSequence);
for (int currentCode : remainingCodes) {
String decodedEntry;
if (reverseDictionary.containsKey(currentCode)) {
decodedEntry = reverseDictionary.get(currentCode);
} else if (currentCode == nextCodeValue) {
decodedEntry = currentSequence + currentSequence.charAt(0);
} else {
throw new IllegalArgumentException("Invalid compressed code encountered: " + currentCode);
}
decodedResult.append(decodedEntry);
reverseDictionary.put(nextCodeValue++, currentSequence + decodedEntry.charAt(0));
currentSequence = decodedEntry;
}
return decodedResult.toString();
}
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Implementation of the Move-to-Front (MTF) transform and its inverse.
 * <p>
 * MTF is a data transformation algorithm that encodes each symbol in the input
 * as its current position in a dynamically-maintained list, then moves that symbol
 * to the front of the list. This transformation is particularly effective when used
 * after the Burrows-Wheeler Transform (BWT), as BWT groups similar characters together.
 * </p>
 *
 * <p>The transform converts runs of repeated characters into sequences of small integers
 * (often zeros), which are highly compressible by subsequent entropy encoding algorithms
 * like Run-Length Encoding (RLE) or Huffman coding. This technique is used in the
 * bzip2 compression algorithm.
 * </p>
 *
 * <p><b>How it works:</b>
 * <ol>
 *   <li>Maintain a list of symbols (the alphabet), initially in a fixed order</li>
 *   <li>For each input symbol:
 *     <ul>
 *       <li>Output its current index in the list</li>
 *       <li>Move that symbol to the front of the list</li>
 *     </ul>
 *   </li>
 * </ol>
 * This means frequently occurring symbols quickly move to the front and are encoded
 * with small indices (often 0), while rare symbols remain near the back.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n × m) where n is input length and m is alphabet size</li>
 *   <li>Inverse transform: O(n × m)</li>
 * </ul>
 * Note: Using {@link LinkedList} for O(1) insertions and O(m) search operations.
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:    "annb$aa"
 * Alphabet: "$abn" (initial order)
 * Output:   [1, 3, 0, 3, 3, 3, 0]
 *
 * Step-by-step:
 * - 'a': index 1 in [$,a,b,n] → output 1, list becomes [a,$,b,n]
 * - 'n': index 3 in [a,$,b,n] → output 3, list becomes [n,a,$,b]
 * - 'n': index 0 in [n,a,$,b] → output 0, list stays [n,a,$,b]
 * - 'b': index 3 in [n,a,$,b] → output 3, list becomes [b,n,a,$]
 * - etc.
 *
 * Notice how repeated 'n' characters produce zeros after the first occurrence!
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Move-to-front_transform">Move-to-front transform (Wikipedia)</a>
 */
public final class MoveToFront {

    private MoveToFront() {
    }

    /**
     * Performs the forward Move-to-Front transform.
     * <p>
     * Converts the input string into a list of integers, where each integer represents
     * the position of the corresponding character in a dynamically-maintained alphabet list.
     * </p>
     *
     * <p><b>Note:</b> All characters in the input text must exist in the provided alphabet,
     * otherwise an {@link IllegalArgumentException} is thrown. The alphabet should contain
     * all unique characters that may appear in the input.</p>
     *
     * @param text the input string to transform; if empty, returns an empty list
     * @param initialAlphabet a string containing the initial ordered set of symbols
     *                        (e.g., "$abn" or the full ASCII set); must not be empty
     *                        when {@code text} is non-empty
     * @return a list of integers representing the transformed data, where each integer
     *         is the index of the corresponding input character in the current alphabet state
     * @throws IllegalArgumentException if {@code text} is non-empty and {@code initialAlphabet}
     *                                  is {@code null} or empty
     * @throws IllegalArgumentException if any character in {@code text} is not found in
     *                                  {@code initialAlphabet}
     */
    public static List<Integer> transform(String text, String initialAlphabet) {
        if (text == null || text.isEmpty()) {
            return new ArrayList<>();
        }
        if (initialAlphabet == null || initialAlphabet.isEmpty()) {
            throw new IllegalArgumentException("Alphabet cannot be null or empty when text is not empty.");
        }

        List<Integer> output = new ArrayList<>(text.length());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        // This is more efficient than ArrayList for the move-to-front pattern
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (char c : text.toCharArray()) {
            int index = alphabet.indexOf(c);
            if (index == -1) {
                throw new IllegalArgumentException("Symbol '" + c + "' not found in the initial alphabet.");
            }

            output.add(index);

            // Move the character to the front
            Character symbol = alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output;
    }

    /**
     * Performs the inverse Move-to-Front transform.
     * <p>
     * Reconstructs the original string from the list of indices produced by the
     * forward transform. This requires the exact same initial alphabet that was
     * used in the forward transform.
     * </p>
     *
     * <p><b>Important:</b> The {@code initialAlphabet} parameter must be identical
     * to the one used in the forward transform, including character order, or the
     * output will be incorrect.</p>
     *
     * @param indices The list of integers from the forward transform.
     * @param initialAlphabet the exact same initial alphabet string used for the forward transform;
     *                        if {@code null} or empty, returns an empty string
     * @return the original, untransformed string
     * @throws IllegalArgumentException if any index in {@code indices} is negative or
     *                                  exceeds the current alphabet size
     */
    public static String inverseTransform(Collection<Integer> indices, String initialAlphabet) {
        if (indices == null || indices.isEmpty() || initialAlphabet == null || initialAlphabet.isEmpty()) {
            return "";
        }

        StringBuilder output = new StringBuilder(indices.size());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (int index : indices) {
            if (index < 0 || index >= alphabet.size()) {
                throw new IllegalArgumentException("Index " + index + " is out of bounds for the current alphabet of size " + alphabet.size() + ".");
            }

            // Get the symbol at the index
            char symbol = alphabet.get(index);
            output.append(symbol);

            // Move the symbol to the front (mirroring the forward transform)
            alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output.toString();
    }
}

