 * @return the hexadecimal representation of the decimal number
 */
public static String decToHex(int decimalValue) {
StringBuilder hexBuilder = new StringBuilder(BYTE_SEGMENTS);
int tempValue = decimalValue;
for (int segmentPos = BYTE_SEGMENTS - 1; segmentPos >= 0; --segmentPos) {
int currentSegment = tempValue & SEGMENT_MASK;
hexBuilder.insert(0, HEX_CHARACTERS[currentSegment]);
tempValue >>= BITS_PER_SEGMENT;
}
return stripLeadingZeros(hexBuilder.toString().toLowerCase());
}

private static String stripLeadingZeros(String inputString) {
if (inputString == null || inputString.isEmpty()) {
return inputString;
}
int startPosition = 0;
while (startPosition < inputString.length() && inputString.charAt(startPosition) == '0') {
startPosition++;
}
return startPosition == inputString.length() ? "0" : inputString.substring(startPosition);
}
