package com.thealgorithms.conversions;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;

/**
 * A utility class for converting between IPv6 and IPv4 addresses.
 *
 * - Converts IPv4 to IPv6-mapped IPv6 address.
 * - Extracts IPv4 address from IPv6-mapped IPv6.
 * - Handles exceptions for invalid inputs.
 *
 * @author Hardvan
 */
public final class IPv6Converter {
    private IPv6Converter() {
    }

    /**
     * Converts an IPv4 address (e.g., "192.0.2.128") to an IPv6-mapped IPv6 address.
     * Example: IPv4 "192.0.2.128" -> IPv6 "::ffff:192.0.2.128"
     *
     * @param ipv4Address The IPv4 address in string format.
     * @return The corresponding IPv6-mapped IPv6 address.
     * @throws UnknownHostException If the IPv4 address is invalid.
     * @throws IllegalArgumentException If the IPv6 address is not a mapped IPv4 address.
     */
    public static String ipv4ToIpv6(String ipv4Address) throws UnknownHostException {
        if (ipv4Address == null || ipv4Address.isEmpty()) {
            throw new UnknownHostException("IPv4 address is empty.");
        }

        InetAddress ipv4 = InetAddress.getByName(ipv4Address);
        byte[] ipv4Bytes = ipv4.getAddress();

        // Create IPv6-mapped IPv6 address (starts with ::ffff:)
        byte[] ipv6Bytes = new byte[16];
        ipv6Bytes[10] = (byte) 0xff;
        ipv6Bytes[11] = (byte) 0xff;
        System.arraycopy(ipv4Bytes, 0, ipv6Bytes, 12, 4);

        // Manually format to "::ffff:x.x.x.x" format
        StringBuilder ipv6String = new StringBuilder("::ffff:");
        for (int i = 12; i < 16; i++) {
            ipv6String.append(ipv6Bytes[i] & 0xFF);
            if (i < 15) {
                ipv6String.append('.');
            }
        }
        return ipv6String.toString();
    }

    /**
     * Extracts the IPv4 address from an IPv6-mapped IPv6 address.
     * Example: IPv6 "::ffff:192.0.2.128" -> IPv4 "192.0.2.128"
     *
     * @param ipv6Address The IPv6 address in string format.
     * @return The extracted IPv4 address.
     * @throws UnknownHostException If the IPv6 address is invalid or not a mapped IPv4 address.
     */
    public static String ipv6ToIpv4(String ipv6Address) throws UnknownHostException {
        InetAddress ipv6 = InetAddress.getByName(ipv6Address);
        byte[] ipv6Bytes = ipv6.getAddress();

        // Check if the address is an IPv6-mapped IPv4 address
        if (isValidIpv6MappedIpv4(ipv6Bytes)) {
            byte[] ipv4Bytes = Arrays.copyOfRange(ipv6Bytes, 12, 16);
            InetAddress ipv4 = InetAddress.getByAddress(ipv4Bytes);
            return ipv4.getHostAddress();
        } else {
            throw new IllegalArgumentException("Not a valid IPv6-mapped IPv4 address.");
        }
    }

    /**
     * Helper function to check if the given byte array represents
     * an IPv6-mapped IPv4 address (prefix 0:0:0:0:0:ffff).
     *
     * @param ipv6Bytes Byte array representation of the IPv6 address.
     * @return True if the address is IPv6-mapped IPv4, otherwise false.
     */
    private static boolean isValidIpv6MappedIpv4(byte[] ipv6Bytes) {
        // IPv6-mapped IPv4 addresses are 16 bytes long, with the first 10 bytes set to 0,
        // followed by 0xff, 0xff, and the last 4 bytes representing the IPv4 address.
        if (ipv6Bytes.length != 16) {
            return false;
        }

        for (int i = 0; i < 10; i++) {
            if (ipv6Bytes[i] != 0) {
                return false;
            }
        }

        return ipv6Bytes[10] == (byte) 0xff && ipv6Bytes[11] == (byte) 0xff;
    }
}

package com.thealgorithms.conversions;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;

/**
 * A utility class for converting between IPv6 and IPv4 addresses.
 *
 * - Converts IPv4 to IPv6-mapped IPv6 address.
 * - Extracts IPv4 address from IPv6-mapped IPv6.
 * - Handles exceptions for invalid inputs.
 *
 * @author Hardvan
 */
public final class IPv6Converter {
private IPv6Converter() {
}

/**
 * Converts an IPv4 address (e.g., "192.0.2.128") to an IPv6-mapped IPv6 address.
 * Example: IPv4 "192.0.2.128" -> IPv6 "::ffff:192.0.2.128"
 *
 * @param ipv4String The IPv4 address in string format.
 * @return The corresponding IPv6-mapped IPv6 address.
 * @throws UnknownHostException If the IPv4 address is invalid.
 * @throws IllegalArgumentException If the IPv6 address is not a mapped IPv4 address.
 */
public static String ipv4ToIpv6(String ipv4String) throws UnknownHostException {
if (ipv4String == null || ipv4String.isEmpty()) {
throw new UnknownHostException("IPv4 address is empty.");
}
InetAddress ipv4Address = InetAddress.getByName(ipv4String);
byte[] ipv4Bytes = ipv4Address.getAddress();
byte[] ipv6Bytes = new byte[16];
ipv6Bytes[10] = (byte) 0xff;
ipv6Bytes[11] = (byte) 0xff;
System.arraycopy(ipv4Bytes, 0, ipv6Bytes, 12, 4);
StringBuilder mappedIpv6 = new StringBuilder("::ffff:");
for (int segment = 12; segment < 16; segment++) {
mappedIpv6.append(ipv6Bytes[segment] & 0xFF);
if (segment < 15) {
mappedIpv6.append('.');
}
}
return mappedIpv6.toString();
}

/**
 * Extracts the IPv4 address from an IPv6-mapped IPv6 address.
 * Example: IPv6 "::ffff:192.0.2.128" -> IPv4 "192.0.2.128"
 *
 * @param ipv6String The IPv6 address in string format.
 * @return The extracted IPv4 address.
 * @throws UnknownHostException If the IPv6 address is invalid or not a mapped IPv4 address.
 */
public static String ipv6ToIpv4(String ipv6String) throws UnknownHostException {
InetAddress ipv6Address = InetAddress.getByName(ipv6String);
byte[] ipv6Bytes = ipv6Address.getAddress();
if (isMappedIpv4Address(ipv6Bytes)) {
byte[] ipv4Bytes = Arrays.copyOfRange(ipv6Bytes, 12, 16);
InetAddress ipv4Result = InetAddress.getByAddress(ipv4Bytes);
return ipv4Result.getHostAddress();
} else {
throw new IllegalArgumentException("Not a valid IPv6-mapped IPv4 address.");
}
}

/**
 * Helper function to check if the given byte array represents
 * an IPv6-mapped IPv4 address (prefix 0:0:0:0:0:ffff).
 *
 * @param ipv6Bytes Byte array representation of the IPv6 address.
 * @return True if the address is IPv6-mapped IPv4, otherwise false.
 */
private static boolean isMappedIpv4Address(byte[] ipv6Bytes) {
if (ipv6Bytes.length != 16) {
return false;
}
for (int offset = 0; offset < 10; offset++) {
if (ipv6Bytes[offset] != 0) {
return false;
}
}
return ipv6Bytes[10] == (byte) 0xff && ipv6Bytes[11] == (byte) 0xff;
}
}

package com.thealgorithms.conversions;

import java.util.Map;

/**
 * A utility class to convert integers to their English word representation.
 *
 * <p>The class supports conversion of numbers from 0 to 2,147,483,647
 * (the maximum value of a 32-bit signed integer). It divides the number
 * into groups of three digits (thousands, millions, billions, etc.) and
 * translates each group into words.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   IntegerToEnglish.integerToEnglishWords(12345);
 *   // Output: "Twelve Thousand Three Hundred Forty Five"
 * </pre>
 *
 * <p>This class uses two maps:</p>
 * <ul>
 *   <li>BASE_NUMBERS_MAP: Holds English words for numbers 0-20, multiples of 10 up to 90, and 100.</li>
 *   <li>THOUSAND_POWER_MAP: Maps powers of 1000 (e.g., Thousand, Million, Billion).</li>
 * </ul>
 */
public final class IntegerToEnglish {

    private static final Map<Integer, String> BASE_NUMBERS_MAP = Map.ofEntries(Map.entry(0, ""), Map.entry(1, "One"), Map.entry(2, "Two"), Map.entry(3, "Three"), Map.entry(4, "Four"), Map.entry(5, "Five"), Map.entry(6, "Six"), Map.entry(7, "Seven"), Map.entry(8, "Eight"), Map.entry(9, "Nine"),
        Map.entry(10, "Ten"), Map.entry(11, "Eleven"), Map.entry(12, "Twelve"), Map.entry(13, "Thirteen"), Map.entry(14, "Fourteen"), Map.entry(15, "Fifteen"), Map.entry(16, "Sixteen"), Map.entry(17, "Seventeen"), Map.entry(18, "Eighteen"), Map.entry(19, "Nineteen"), Map.entry(20, "Twenty"),
        Map.entry(30, "Thirty"), Map.entry(40, "Forty"), Map.entry(50, "Fifty"), Map.entry(60, "Sixty"), Map.entry(70, "Seventy"), Map.entry(80, "Eighty"), Map.entry(90, "Ninety"), Map.entry(100, "Hundred"));

    private static final Map<Integer, String> THOUSAND_POWER_MAP = Map.ofEntries(Map.entry(1, "Thousand"), Map.entry(2, "Million"), Map.entry(3, "Billion"));

    private IntegerToEnglish() {
    }

    /**
     * Converts numbers less than 1000 into English words.
     *
     * @param number the integer value (0-999) to convert
     * @return the English word representation of the input number
     */
    private static String convertToWords(int number) {
        int remainder = number % 100;
        StringBuilder result = new StringBuilder();

        if (remainder <= 20) {
            result.append(BASE_NUMBERS_MAP.get(remainder));
        } else if (BASE_NUMBERS_MAP.containsKey(remainder)) {
            result.append(BASE_NUMBERS_MAP.get(remainder));
        } else {
            int tensDigit = remainder / 10;
            int onesDigit = remainder % 10;
            String tens = BASE_NUMBERS_MAP.getOrDefault(tensDigit * 10, "");
            String ones = BASE_NUMBERS_MAP.getOrDefault(onesDigit, "");
            result.append(tens);
            if (ones != null && !ones.isEmpty()) {
                result.append(" ").append(ones);
            }
        }

        int hundredsDigit = number / 100;
        if (hundredsDigit > 0) {
            if (result.length() > 0) {
                result.insert(0, " ");
            }
            result.insert(0, String.format("%s Hundred", BASE_NUMBERS_MAP.get(hundredsDigit)));
        }

        return result.toString().trim();
    }

    /**
     * Converts a non-negative integer to its English word representation.
     *
     * @param number the integer to convert (0-2,147,483,647)
     * @return the English word representation of the input number
     */
    public static String integerToEnglishWords(int number) {
        if (number == 0) {
            return "Zero";
        }

        StringBuilder result = new StringBuilder();
        int index = 0;

        while (number > 0) {
            int remainder = number % 1000;
            number /= 1000;

            if (remainder > 0) {
                String subResult = convertToWords(remainder);
                if (!subResult.isEmpty()) {
                    if (index > 0) {
                        subResult += " " + THOUSAND_POWER_MAP.get(index);
                    }
                    if (result.length() > 0) {
                        result.insert(0, " ");
                    }
                    result.insert(0, subResult);
                }
            }

            index++;
        }

        return result.toString().trim();
    }
}

package com.thealgorithms.conversions;

import java.util.Map;

/**
 * A utility class to convert integers to their English word representation.
 *
 * <p>The class supports conversion of numbers from 0 to 2,147,483,647
 * (the maximum value of a 32-bit signed integer). It divides the number
 * into groups of three digits (thousands, millions, billions, etc.) and
 * translates each group into words.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   IntegerToEnglish.integerToEnglishWords(12345);
 *   // Output: "Twelve Thousand Three Hundred Forty Five"
 * </pre>
 *
 * <p>This class uses two maps:</p>
 * <ul>
 *   <li>BASE_NUMBERS_MAP: Holds English words for numbers 0-20, multiples of 10 up to 90, and 100.</li>
 *   <li>THOUSAND_POWER_MAP: Maps powers of 1000 (e.g., Thousand, Million, Billion).</li>
 * </ul>
 */
public final class IntegerToEnglish {

private static final Map<Integer, String> BASIC_NUMBERS = Map.ofEntries(
Map.entry(0, ""), Map.entry(1, "One"), Map.entry(2, "Two"), Map.entry(3, "Three"),
Map.entry(4, "Four"), Map.entry(5, "Five"), Map.entry(6, "Six"), Map.entry(7, "Seven"),
Map.entry(8, "Eight"), Map.entry(9, "Nine"), Map.entry(10, "Ten"), Map.entry(11, "Eleven"),
Map.entry(12, "Twelve"), Map.entry(13, "Thirteen"), Map.entry(14, "Fourteen"),
Map.entry(15, "Fifteen"), Map.entry(16, "Sixteen"), Map.entry(17, "Seventeen"),
Map.entry(18, "Eighteen"), Map.entry(19, "Nineteen"), Map.entry(20, "Twenty"),
Map.entry(30, "Thirty"), Map.entry(40, "Forty"), Map.entry(50, "Fifty"),
Map.entry(60, "Sixty"), Map.entry(70, "Seventy"), Map.entry(80, "Eighty"),
Map.entry(90, "Ninety"), Map.entry(100, "Hundred")
);

private static final Map<Integer, String> THOUSAND_GROUPS = Map.of(
1, "Thousand", 2, "Million", 3, "Billion"
);

private IntegerToEnglish() {
}

/**
 * Converts numbers less than 1000 into English words.
 *
 * @param numericValue the integer value (0-999) to convert
 * @return the English word representation of the input number
 */
private static String convertGroupToWords(int numericValue) {
int remainderPart = numericValue % 100;
StringBuilder wordBuilder = new StringBuilder();
if (remainderPart <= 20) {
wordBuilder.append(BASIC_NUMBERS.get(remainderPart));
} else if (BASIC_NUMBERS.containsKey(remainderPart)) {
wordBuilder.append(BASIC_NUMBERS.get(remainderPart));
} else {
int tensValue = remainderPart / 10;
int unitsValue = remainderPart % 10;
String tensSegment = BASIC_NUMBERS.getOrDefault(tensValue * 10, "");
String unitsSegment = BASIC_NUMBERS.getOrDefault(unitsValue, "");
wordBuilder.append(tensSegment);
if (!unitsSegment.isEmpty()) {
wordBuilder.append(" ").append(unitsSegment);
}
}
int hundredsPart = numericValue / 100;
if (hundredsPart > 0) {
if (wordBuilder.length() > 0) {
wordBuilder.insert(0, " ");
}
wordBuilder.insert(0, String.format("%s Hundred", BASIC_NUMBERS.get(hundredsPart)));
}
return wordBuilder.toString().trim();
}

/**
 * Converts a non-negative integer to its English word representation.
 *
 * @param sourceNumber the integer to convert (0-2,147,483,647)
 * @return the English word representation of the input number
 */
public static String integerToEnglishWords(int sourceNumber) {
if (sourceNumber == 0) {
return "Zero";
}
StringBuilder finalResult = new StringBuilder();
int groupIndex = 0;
int remainingValue = sourceNumber;
while (remainingValue > 0) {
int currentGroup = remainingValue % 1000;
remainingValue /= 1000;
if (currentGroup > 0) {
String groupText = convertGroupToWords(currentGroup);
if (!groupText.isEmpty()) {
if (groupIndex > 0) {
groupText += " " + THOUSAND_GROUPS.get(groupIndex);
}
if (finalResult.length() > 0) {
finalResult.insert(0, " ");
}
finalResult.insert(0, groupText);
}
}
groupIndex++;
}
return finalResult.toString().trim();
}
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert integers into Roman numerals.
 *
 * <p>Roman numerals follow these rules:
 * <ul>
 *   <li>I = 1</li>
 *   <li>IV = 4</li>
 *   <li>V = 5</li>
 *   <li>IX = 9</li>
 *   <li>X = 10</li>
 *   <li>XL = 40</li>
 *   <li>L = 50</li>
 *   <li>XC = 90</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>Conversion is based on repeatedly subtracting the largest possible Roman numeral value
 * from the input number until it reaches zero. For example, 1994 is converted as:
 * <pre>
 *   1994 -> MCMXCIV (1000 + 900 + 90 + 4)
 * </pre>
 */
public final class IntegerToRoman {

    // Array of Roman numeral values in descending order
    private static final int[] ALL_ROMAN_NUMBERS_IN_ARABIC = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};

    // Corresponding Roman numeral symbols
    private static final String[] ALL_ROMAN_NUMBERS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    private IntegerToRoman() {
    }

    /**
     * Converts an integer to its Roman numeral representation.
     * Steps:
     * <ol>
     *     <li>Iterate over the Roman numeral values in descending order</li>
     *     <li>Calculate how many times a numeral fits</li>
     *     <li>Append the corresponding symbol</li>
     *     <li>Subtract the value from the number</li>
     *     <li>Repeat until the number is zero</li>
     *     <li>Return the Roman numeral representation</li>
     * </ol>
     *
     * @param num the integer value to convert (must be greater than 0)
     * @return the Roman numeral representation of the input integer
     *         or an empty string if the input is non-positive
     */
    public static String integerToRoman(int num) {
        if (num <= 0) {
            return "";
        }

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < ALL_ROMAN_NUMBERS_IN_ARABIC.length; i++) {
            int times = num / ALL_ROMAN_NUMBERS_IN_ARABIC[i];
            builder.append(ALL_ROMAN_NUMBERS[i].repeat(Math.max(0, times)));
            num -= times * ALL_ROMAN_NUMBERS_IN_ARABIC[i];
        }

        return builder.toString();
    }
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert integers into Roman numerals.
 *
 * <p>Roman numerals follow these rules:
 * <ul>
 *   <li>I = 1</li>
 *   <li>IV = 4</li>
 *   <li>V = 5</li>
 *   <li>IX = 9</li>
 *   <li>X = 10</li>
 *   <li>XL = 40</li>
 *   <li>L = 50</li>
 *   <li>XC = 90</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>Conversion is based on repeatedly subtracting the largest possible Roman numeral value
 * from the input number until it reaches zero. For example, 1994 is converted as:
 * <pre>
 *   1994 -> MCMXCIV (1000 + 900 + 90 + 4)
 * </pre>
 */
public final class IntegerToRoman {

private static final int[] ARABIC_VALUES = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
private static final String[] ROMAN_SYMBOLS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

private IntegerToRoman() {
}

/**
 * Converts an integer to its Roman numeral representation.
 * Steps:
 * <ol>
 *     <li>Iterate over the Roman numeral values in descending order</li>
 *     <li>Calculate how many times a numeral fits</li>
 *     <li>Append the corresponding symbol</li>
 *     <li>Subtract the value from the number</li>
 *     <li>Repeat until the number is zero</li>
 *     <li>Return the Roman numeral representation</li>
 * </ol>
 *
 * @param inputNumber the integer value to convert (must be greater than 0)
 * @return the Roman numeral representation of the input integer
 *         or an empty string if the input is non-positive
 */
public static String integerToRoman(int inputNumber) {
if (inputNumber <= 0) {
return "";
}
StringBuilder romanResult = new StringBuilder();
int remainingValue = inputNumber;
for (int position = 0; position < ARABIC_VALUES.length; position++) {
int repeatCount = remainingValue / ARABIC_VALUES[position];
romanResult.append(String.valueOf(ROMAN_SYMBOLS[position]).repeat(Math.max(0, repeatCount)));
remainingValue -= repeatCount * ARABIC_VALUES[position];
}
return romanResult.toString();
}
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts text to Morse code and vice-versa.
 * Text to Morse code: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: "HELLO WORLD" -> ".... . .-.. .-.. --- | .-- --- .-. .-.. -.."
 *
 * Morse code to text: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: ".... . .-.. .-.. --- | .-- --- .-. .-.. -.." -> "HELLO WORLD"
 *
 * Applications: Used in radio communications and algorithmic challenges.
 *
 * @author Hardvan
 */
public final class MorseCodeConverter {
    private MorseCodeConverter() {
    }

    private static final Map<Character, String> MORSE_MAP = new HashMap<>();
    private static final Map<String, Character> REVERSE_MAP = new HashMap<>();

    static {
        MORSE_MAP.put('A', ".-");
        MORSE_MAP.put('B', "-...");
        MORSE_MAP.put('C', "-.-.");
        MORSE_MAP.put('D', "-..");
        MORSE_MAP.put('E', ".");
        MORSE_MAP.put('F', "..-.");
        MORSE_MAP.put('G', "--.");
        MORSE_MAP.put('H', "....");
        MORSE_MAP.put('I', "..");
        MORSE_MAP.put('J', ".---");
        MORSE_MAP.put('K', "-.-");
        MORSE_MAP.put('L', ".-..");
        MORSE_MAP.put('M', "--");
        MORSE_MAP.put('N', "-.");
        MORSE_MAP.put('O', "---");
        MORSE_MAP.put('P', ".--.");
        MORSE_MAP.put('Q', "--.-");
        MORSE_MAP.put('R', ".-.");
        MORSE_MAP.put('S', "...");
        MORSE_MAP.put('T', "-");
        MORSE_MAP.put('U', "..-");
        MORSE_MAP.put('V', "...-");
        MORSE_MAP.put('W', ".--");
        MORSE_MAP.put('X', "-..-");
        MORSE_MAP.put('Y', "-.--");
        MORSE_MAP.put('Z', "--..");

        // Build reverse map for decoding
        MORSE_MAP.forEach((k, v) -> REVERSE_MAP.put(v, k));
    }

    /**
     * Converts text to Morse code.
     * Each letter is separated by a space and each word is separated by a pipe (|).
     *
     * @param text The text to convert to Morse code.
     * @return The Morse code representation of the text.
     */
    public static String textToMorse(String text) {
        StringBuilder morse = new StringBuilder();
        String[] words = text.toUpperCase().split(" ");
        for (int i = 0; i < words.length; i++) {
            for (char c : words[i].toCharArray()) {
                morse.append(MORSE_MAP.getOrDefault(c, "")).append(" ");
            }
            if (i < words.length - 1) {
                morse.append("| ");
            }
        }
        return morse.toString().trim();
    }

    /**
     * Converts Morse code to text.
     * Each letter is separated by a space and each word is separated by a pipe (|).
     *
     * @param morse The Morse code to convert to text.
     * @return The text representation of the Morse code.
     */
    public static String morseToText(String morse) {
        StringBuilder text = new StringBuilder();
        String[] words = morse.split(" \\| ");
        for (int i = 0; i < words.length; i++) {
            for (String code : words[i].split(" ")) {
                text.append(REVERSE_MAP.getOrDefault(code, '?'));
            }
            if (i < words.length - 1) {
                text.append(" ");
            }
        }
        return text.toString();
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts text to Morse code and vice-versa.
 * Text to Morse code: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: "HELLO WORLD" -> ".... . .-.. .-.. --- | .-- --- .-. .-.. -.."
 *
 * Morse code to text: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: ".... . .-.. .-.. --- | .-- --- .-. .-.. -.." -> "HELLO WORLD"
 *
 * Applications: Used in radio communications and algorithmic challenges.
 *
 * @author Hardvan
 */
public final class MorseCodeConverter {
private MorseCodeConverter() {
}

private static final Map<Character, String> ENCODE_MAP = new HashMap<>();
private static final Map<String, Character> DECODE_MAP = new HashMap<>();

static {
ENCODE_MAP.put('A', ".-");
ENCODE_MAP.put('B', "-...");
ENCODE_MAP.put('C', "-.-.");
ENCODE_MAP.put('D', "-..");
ENCODE_MAP.put('E', ".");
ENCODE_MAP.put('F', "..-.");
ENCODE_MAP.put('G', "--.");
ENCODE_MAP.put('H', "....");
ENCODE_MAP.put('I', "..");
ENCODE_MAP.put('J', ".---");
ENCODE_MAP.put('K', "-.-");
ENCODE_MAP.put('L', ".-..");
ENCODE_MAP.put('M', "--");
ENCODE_MAP.put('N', "-.");
ENCODE_MAP.put('O', "---");
ENCODE_MAP.put('P', ".--.");
ENCODE_MAP.put('Q', "--.-");
ENCODE_MAP.put('R', ".-.");
ENCODE_MAP.put('S', "...");
ENCODE_MAP.put('T', "-");
ENCODE_MAP.put('U', "..-");
ENCODE_MAP.put('V', "...-");
ENCODE_MAP.put('W', ".--");
ENCODE_MAP.put('X', "-..-");
ENCODE_MAP.put('Y', "-.--");
ENCODE_MAP.put('Z', "--..");
ENCODE_MAP.forEach((keySymbol, codeValue) -> DECODE_MAP.put(codeValue, keySymbol));
}

/**
 * Converts text to Morse code.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param sourceText The text to convert to Morse code.
 * @return The Morse code representation of the text.
 */
public static String textToMorse(String sourceText) {
StringBuilder encodedResult = new StringBuilder();
String[] wordSegments = sourceText.toUpperCase().split(" ");
for (int segmentPos = 0; segmentPos < wordSegments.length; segmentPos++) {
for (char currentChar : wordSegments[segmentPos].toCharArray()) {
encodedResult.append(ENCODE_MAP.getOrDefault(currentChar, "")).append(" ");
}
if (segmentPos < wordSegments.length - 1) {
encodedResult.append("| ");
}
}
return encodedResult.toString().trim();
}

/**
 * Converts Morse code to text.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param encodedData The Morse code to convert to text.
 * @return The text representation of the Morse code.
 */
public static String morseToText(String encodedData) {
StringBuilder decodedResult = new StringBuilder();
String[] wordCodes = encodedData.split(" \\| ");
for (int wordPos = 0; wordPos < wordCodes.length; wordPos++) {
for (String symbolCode : wordCodes[wordPos].split(" ")) {
decodedResult.append(DECODE_MAP.getOrDefault(symbolCode, '?'));
}
if (wordPos < wordCodes.length - 1) {
decodedResult.append(" ");
}
}
return decodedResult.toString();
}
}

package com.thealgorithms.conversions;

import java.math.BigDecimal;

/**
 A Java-based utility for converting numeric values into their English word
 representations. Whether you need to convert a small number, a large number
 with millions and billions, or even a number with decimal places, this utility
 has you covered.
 *
 */
public final class NumberToWords {

    private NumberToWords() {
    }

    private static final String[] UNITS = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};

    private static final String[] TENS = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};

    private static final String[] POWERS = {"", "Thousand", "Million", "Billion", "Trillion"};

    private static final String ZERO = "Zero";
    private static final String POINT = " Point";
    private static final String NEGATIVE = "Negative ";

    public static String convert(BigDecimal number) {
        if (number == null) {
            return "Invalid Input";
        }

        // Check for negative sign
        boolean isNegative = number.signum() < 0;

        // Split the number into whole and fractional parts
        BigDecimal[] parts = number.abs().divideAndRemainder(BigDecimal.ONE);
        BigDecimal wholePart = parts[0]; // Keep whole part as BigDecimal
        String fractionalPartStr = parts[1].compareTo(BigDecimal.ZERO) > 0 ? parts[1].toPlainString().substring(2) : ""; // Get fractional part only if it exists

        // Convert whole part to words
        StringBuilder result = new StringBuilder();
        if (isNegative) {
            result.append(NEGATIVE);
        }
        result.append(convertWholeNumberToWords(wholePart));

        // Convert fractional part to words
        if (!fractionalPartStr.isEmpty()) {
            result.append(POINT);
            for (char digit : fractionalPartStr.toCharArray()) {
                int digitValue = Character.getNumericValue(digit);
                result.append(" ").append(digitValue == 0 ? ZERO : UNITS[digitValue]);
            }
        }

        return result.toString().trim();
    }

    private static String convertWholeNumberToWords(BigDecimal number) {
        if (number.compareTo(BigDecimal.ZERO) == 0) {
            return ZERO;
        }

        StringBuilder words = new StringBuilder();
        int power = 0;

        while (number.compareTo(BigDecimal.ZERO) > 0) {
            // Get the last three digits
            BigDecimal[] divisionResult = number.divideAndRemainder(BigDecimal.valueOf(1000));
            int chunk = divisionResult[1].intValue();

            if (chunk > 0) {
                String chunkWords = convertChunk(chunk);
                if (power > 0) {
                    words.insert(0, POWERS[power] + " ");
                }
                words.insert(0, chunkWords + " ");
            }

            number = divisionResult[0]; // Continue with the remaining part
            power++;
        }

        return words.toString().trim();
    }

    private static String convertChunk(int number) {
        String chunkWords;

        if (number < 20) {
            chunkWords = UNITS[number];
        } else if (number < 100) {
            chunkWords = TENS[number / 10] + (number % 10 > 0 ? " " + UNITS[number % 10] : "");
        } else {
            chunkWords = UNITS[number / 100] + " Hundred" + (number % 100 > 0 ? " " + convertChunk(number % 100) : "");
        }

        return chunkWords;
    }
}

package com.thealgorithms.conversions;

import java.math.BigDecimal;

/**
 A Java-based utility for converting numeric values into their English word
 representations. Whether you need to convert a small number, a large number
 with millions and billions, or even a number with decimal places, this utility
 has you covered.
 *
 */
public final class NumberToWords {

private NumberToWords() {
}

private static final String[] BASIC_UNITS = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
private static final String[] DECADE_NAMES = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
private static final String[] MAGNITUDE_SUFFIX = {"", "Thousand", "Million", "Billion", "Trillion"};
private static final String ZERO_TEXT = "Zero";
private static final String DECIMAL_MARKER = " Point";
private static final String NEGATIVE_PREFIX = "Negative ";

public static String convert(BigDecimal numericValue) {
if (numericValue == null) {
return "Invalid Input";
}
boolean hasNegativeSign = numericValue.signum() < 0;
BigDecimal[] integerFractionParts = numericValue.abs().divideAndRemainder(BigDecimal.ONE);
BigDecimal integerComponent = integerFractionParts[0];
String fractionComponent = integerFractionParts[1].compareTo(BigDecimal.ZERO) > 0 ? integerFractionParts[1].toPlainString().substring(2) : "";
StringBuilder outputText = new StringBuilder();
if (hasNegativeSign) {
outputText.append(NEGATIVE_PREFIX);
}
outputText.append(convertIntegerPart(integerComponent));
if (!fractionComponent.isEmpty()) {
outputText.append(DECIMAL_MARKER);
for (char digitChar : fractionComponent.toCharArray()) {
int digitValue = Character.getNumericValue(digitChar);
outputText.append(" ").append(digitValue == 0 ? ZERO_TEXT : BASIC_UNITS[digitValue]);
}
}
return outputText.toString().trim();
}

private static String convertIntegerPart(BigDecimal integerValue) {
if (integerValue.compareTo(BigDecimal.ZERO) == 0) {
return ZERO_TEXT;
}
StringBuilder wordResult = new StringBuilder();
int magnitudeIndex = 0;
BigDecimal remainingValue = integerValue;
while (remainingValue.compareTo(BigDecimal.ZERO) > 0) {
BigDecimal[] divisionResult = remainingValue.divideAndRemainder(BigDecimal.valueOf(1000));
int threeDigitGroup = divisionResult[1].intValue();
if (threeDigitGroup > 0) {
String groupWords = convertThreeDigitGroup(threeDigitGroup);
if (magnitudeIndex > 0) {
wordResult.insert(0, MAGNITUDE_SUFFIX[magnitudeIndex] + " ");
}
wordResult.insert(0, groupWords + " ");
}
remainingValue = divisionResult[0];
magnitudeIndex++;
}
return wordResult.toString().trim();
}

private static String convertThreeDigitGroup(int groupValue) {
String resultSegment;
if (groupValue < 20) {
resultSegment = BASIC_UNITS[groupValue];
} else if (groupValue < 100) {
resultSegment = DECADE_NAMES[groupValue / 10] + (groupValue % 10 > 0 ? " " + BASIC_UNITS[groupValue % 10] : "");
} else {
resultSegment = BASIC_UNITS[groupValue / 100] + " Hundred" + (groupValue % 100 > 0 ? " " + convertThreeDigitGroup(groupValue % 100) : "");
}
return resultSegment;
}
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert an octal (base-8) number into its binary (base-2) representation.
 *
 * <p>This class provides methods to:
 * <ul>
 *     <li>Convert an octal number to its binary equivalent</li>
 *     <li>Convert individual octal digits to binary</li>
 * </ul>
 *
 * <h2>Octal to Binary Conversion:</h2>
 * <p>An octal number is converted to binary by converting each octal digit to its 3-bit binary equivalent.
 * The result is a long representing the full binary equivalent of the octal number.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   long binary = OctalToBinary.convertOctalToBinary(52); // Output: 101010 (52 in octal is 101010 in binary)
 * </pre>
 *
 * @author Bama Charan Chhandogi
 * @see <a href="https://en.wikipedia.org/wiki/Octal">Octal Number System</a>
 * @see <a href="https://en.wikipedia.org/wiki/Binary_number">Binary Number System</a>
 */
public final class OctalToBinary {
    private OctalToBinary() {
    }

    /**
     * Converts an octal number to its binary representation.
     *
     * <p>Each octal digit is individually converted to its 3-bit binary equivalent, and the binary
     * digits are concatenated to form the final binary number.</p>
     *
     * @param octalNumber the octal number to convert (non-negative integer)
     * @return the binary equivalent as a long
     */
    public static long convertOctalToBinary(int octalNumber) {
        long binaryNumber = 0;
        int digitPosition = 1;

        while (octalNumber != 0) {
            int octalDigit = octalNumber % 10;
            long binaryDigit = convertOctalDigitToBinary(octalDigit);

            binaryNumber += binaryDigit * digitPosition;

            octalNumber /= 10;
            digitPosition *= 1000;
        }

        return binaryNumber;
    }

    /**
     * Converts a single octal digit (0-7) to its binary equivalent.
     *
     * <p>For example:
     * <ul>
     *     <li>Octal digit 7 is converted to binary 111</li>
     *     <li>Octal digit 3 is converted to binary 011</li>
     * </ul>
     * </p>
     *
     * @param octalDigit a single octal digit (0-7)
     * @return the binary equivalent as a long
     */
    public static long convertOctalDigitToBinary(int octalDigit) {
        long binaryDigit = 0;
        int binaryMultiplier = 1;

        while (octalDigit != 0) {
            int octalDigitRemainder = octalDigit % 2;
            binaryDigit += octalDigitRemainder * binaryMultiplier;

            octalDigit /= 2;
            binaryMultiplier *= 10;
        }

        return binaryDigit;
    }
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert an octal (base-8) number into its binary (base-2) representation.
 *
 * <p>This class provides methods to:
 * <ul>
 *     <li>Convert an octal number to its binary equivalent</li>
 *     <li>Convert individual octal digits to binary</li>
 * </ul>
 *
 * <h2>Octal to Binary Conversion:</h2>
 * <p>An octal number is converted to binary by converting each octal digit to its 3-bit binary equivalent.
 * The result is a long representing the full binary equivalent of the octal number.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   long binary = OctalToBinary.convertOctalToBinary(52); // Output: 101010 (52 in octal is 101010 in binary)
 * </pre>
 *
 * @author Bama Charan Chhandogi
 * @see <a href="https://en.wikipedia.org/wiki/Octal">Octal Number System</a>
 * @see <a href="https://en.wikipedia.org/wiki/Binary_number">Binary Number System</a>
 */
public final class OctalToBinary {
private OctalToBinary() {
}

/**
 * Converts an octal number to its binary representation.
 *
 * <p>Each octal digit is individually converted to its 3-bit binary equivalent, and the binary
 * digits are concatenated to form the final binary number.</p>
 *
 * @param octalInput the octal number to convert (non-negative integer)
 * @return the binary equivalent as a long
 */
public static long convertOctalToBinary(int octalInput) {
long binaryResult = 0;
int placeMultiplier = 1;
int remainingOctal = octalInput;
while (remainingOctal != 0) {
int currentDigit = remainingOctal % 10;
long binarySegment = convertDigitToBinary(currentDigit);
binaryResult += binarySegment * placeMultiplier;
remainingOctal /= 10;
placeMultiplier *= 1000;
}
return binaryResult;
}

/**
 * Converts a single octal digit (0-7) to its binary equivalent.
 *
 * <p>For example:
 * <ul>
 *     <li>Octal digit 7 is converted to binary 111</li>
 *     <li>Octal digit 3 is converted to binary 011</li>
 * </ul>
 * </p>
 *
 * @param digitValue a single octal digit (0-7)
 * @return the binary equivalent as a long
 */
public static long convertDigitToBinary(int digitValue) {
long binaryEquivalent = 0;
int positionWeight = 1;
int tempValue = digitValue;
while (tempValue != 0) {
int remainderBit = tempValue % 2;
binaryEquivalent += remainderBit * positionWeight;
tempValue /= 2;
positionWeight *= 10;
}
return binaryEquivalent;
}
}

package com.thealgorithms.conversions;

/**
 * Class for converting an octal number to a decimal number. Octal numbers are based on 8, using digits from 0 to 7.
 *
 */
public final class OctalToDecimal {
    private static final int OCTAL_BASE = 8;

    private OctalToDecimal() {
    }

    /**
     * Converts a given octal number (as a string) to its decimal representation.
     * If the input is not a valid octal number (i.e., contains characters other than 0-7),
     * the method throws an IllegalArgumentException.
     *
     * @param inputOctal The octal number as a string
     * @return The decimal equivalent of the octal number
     * @throws IllegalArgumentException if the input is not a valid octal number
     */
    public static int convertOctalToDecimal(String inputOctal) {
        if (inputOctal == null || inputOctal.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        int decimalValue = 0;

        for (int i = 0; i < inputOctal.length(); i++) {
            char currentChar = inputOctal.charAt(i);

            if (currentChar < '0' || currentChar > '7') {
                throw new IllegalArgumentException("Incorrect input: Expecting an octal number (digits 0-7)");
            }

            int currentDigit = currentChar - '0';
            decimalValue = decimalValue * OCTAL_BASE + currentDigit;
        }

        return decimalValue;
    }
}

