package com.thealgorithms.conversions;

import java.util.Arrays;

/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
    private RgbHsvConversion() {
    }

    public static void main(String[] args) {
        // Expected RGB-values taken from https://www.rapidtables.com/convert/color/hsv-to-rgb.html

        // Test hsvToRgb-method
        assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
        assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
        assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
        assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
        assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
        assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
        assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
        assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
        assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
        assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});

        // Test rgbToHsv-method
        // approximate-assertions needed because of small deviations due to converting between
        // int-values and double-values.
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
        assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
        assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
    }

    /**
     * Conversion from the HSV-representation to the RGB-representation.
     *
     * @param hue Hue of the color.
     * @param saturation Saturation of the color.
     * @param value Brightness-value of the color.
     * @return The tuple of RGB-components.
     */
    public static int[] hsvToRgb(double hue, double saturation, double value) {
        if (hue < 0 || hue > 360) {
            throw new IllegalArgumentException("hue should be between 0 and 360");
        }

        if (saturation < 0 || saturation > 1) {
            throw new IllegalArgumentException("saturation should be between 0 and 1");
        }

        if (value < 0 || value > 1) {
            throw new IllegalArgumentException("value should be between 0 and 1");
        }

        double chroma = value * saturation;
        double hueSection = hue / 60;
        double secondLargestComponent = chroma * (1 - Math.abs(hueSection % 2 - 1));
        double matchValue = value - chroma;

        return getRgbBySection(hueSection, chroma, matchValue, secondLargestComponent);
    }

    /**
     * Conversion from the RGB-representation to the HSV-representation.
     *
     * @param red Red-component of the color.
     * @param green Green-component of the color.
     * @param blue Blue-component of the color.
     * @return The tuple of HSV-components.
     */
    public static double[] rgbToHsv(int red, int green, int blue) {
        if (red < 0 || red > 255) {
            throw new IllegalArgumentException("red should be between 0 and 255");
        }

        if (green < 0 || green > 255) {
            throw new IllegalArgumentException("green should be between 0 and 255");
        }

        if (blue < 0 || blue > 255) {
            throw new IllegalArgumentException("blue should be between 0 and 255");
        }

        double dRed = (double) red / 255;
        double dGreen = (double) green / 255;
        double dBlue = (double) blue / 255;
        double value = Math.max(Math.max(dRed, dGreen), dBlue);
        double chroma = value - Math.min(Math.min(dRed, dGreen), dBlue);
        double saturation = value == 0 ? 0 : chroma / value;
        double hue;

        if (chroma == 0) {
            hue = 0;
        } else if (value == dRed) {
            hue = 60 * (0 + (dGreen - dBlue) / chroma);
        } else if (value == dGreen) {
            hue = 60 * (2 + (dBlue - dRed) / chroma);
        } else {
            hue = 60 * (4 + (dRed - dGreen) / chroma);
        }

        hue = (hue + 360) % 360;

        return new double[] {hue, saturation, value};
    }

    private static boolean approximatelyEqualHsv(double[] hsv1, double[] hsv2) {
        boolean bHue = Math.abs(hsv1[0] - hsv2[0]) < 0.2;
        boolean bSaturation = Math.abs(hsv1[1] - hsv2[1]) < 0.002;
        boolean bValue = Math.abs(hsv1[2] - hsv2[2]) < 0.002;

        return bHue && bSaturation && bValue;
    }

    private static int[] getRgbBySection(double hueSection, double chroma, double matchValue, double secondLargestComponent) {
        int red;
        int green;
        int blue;

        if (hueSection >= 0 && hueSection <= 1) {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 1 && hueSection <= 2) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 2 && hueSection <= 3) {
            red = convertToInt(matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        } else if (hueSection > 3 && hueSection <= 4) {
            red = convertToInt(matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(chroma + matchValue);
        } else if (hueSection > 4 && hueSection <= 5) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(chroma + matchValue);
        } else {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        }

        return new int[] {red, green, blue};
    }

    private static int convertToInt(double input) {
        return (int) Math.round(255 * input);
    }
}

package com.thealgorithms.conversions;

import java.util.Arrays;

/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
private RgbHsvConversion() {
}

public static void main(String[] args) {
assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
}

/**
 * Conversion from the HSV-representation to the RGB-representation.
 *
 * @param hueValue Hue of the color.
 * @param saturationValue Saturation of the color.
 * @param brightnessValue Brightness-value of the color.
 * @return The tuple of RGB-components.
 */
public static int[] hsvToRgb(double hueValue, double saturationValue, double brightnessValue) {
if (hueValue < 0 || hueValue > 360) {
throw new IllegalArgumentException("hue should be between 0 and 360");
}
if (saturationValue < 0 || saturationValue > 1) {
throw new IllegalArgumentException("saturation should be between 0 and 1");
}
if (brightnessValue < 0 || brightnessValue > 1) {
throw new IllegalArgumentException("value should be between 0 and 1");
}
double chromaAmount = brightnessValue * saturationValue;
double hueSegment = hueValue / 60;
double secondaryComponent = chromaAmount * (1 - Math.abs(hueSegment % 2 - 1));
double brightnessOffset = brightnessValue - chromaAmount;
return getRgbFromSegment(hueSegment, chromaAmount, brightnessOffset, secondaryComponent);
}

/**
 * Conversion from the RGB-representation to the HSV-representation.
 *
 * @param redValue Red-component of the color.
 * @param greenValue Green-component of the color.
 * @param blueValue Blue-component of the color.
 * @return The tuple of HSV-components.
 */
public static double[] rgbToHsv(int redValue, int greenValue, int blueValue) {
if (redValue < 0 || redValue > 255) {
throw new IllegalArgumentException("red should be between 0 and 255");
}
if (greenValue < 0 || greenValue > 255) {
throw new IllegalArgumentException("green should be between 0 and 255");
}
if (blueValue < 0 || blueValue > 255) {
throw new IllegalArgumentException("blue should be between 0 and 255");
}
double normalizedRed = (double) redValue / 255;
double normalizedGreen = (double) greenValue / 255;
double normalizedBlue = (double) blueValue / 255;
double maxComponent = Math.max(Math.max(normalizedRed, normalizedGreen), normalizedBlue);
double minComponent = Math.min(Math.min(normalizedRed, normalizedGreen), normalizedBlue);
double chromaDifference = maxComponent - minComponent;
double saturationResult = maxComponent == 0 ? 0 : chromaDifference / maxComponent;
double hueResult;
if (chromaDifference == 0) {
hueResult = 0;
} else if (maxComponent == normalizedRed) {
hueResult = 60 * (0 + (normalizedGreen - normalizedBlue) / chromaDifference);
} else if (maxComponent == normalizedGreen) {
hueResult = 60 * (2 + (normalizedBlue - normalizedRed) / chromaDifference);
} else {
hueResult = 60 * (4 + (normalizedRed - normalizedGreen) / chromaDifference);
}
hueResult = (hueResult + 360) % 360;
return new double[] {hueResult, saturationResult, maxComponent};
}

private static boolean approximatelyEqualHsv(double[] hsvFirst, double[] hsvSecond) {
boolean hueMatch = Math.abs(hsvFirst[0] - hsvSecond[0]) < 0.2;
boolean saturationMatch = Math.abs(hsvFirst[1] - hsvSecond[1]) < 0.002;
boolean valueMatch = Math.abs(hsvFirst[2] - hsvSecond[2]) < 0.002;
return hueMatch && saturationMatch && valueMatch;
}

private static int[] getRgbFromSegment(double hueSegment, double chromaAmount, double brightnessOffset, double secondaryComponent) {
int redChannel, greenChannel, blueChannel;
if (hueSegment >= 0 && hueSegment <= 1) {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 1 && hueSegment <= 2) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 2 && hueSegment <= 3) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
} else if (hueSegment > 3 && hueSegment <= 4) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else if (hueSegment > 4 && hueSegment <= 5) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
}
return new int[] {redChannel, greenChannel, blueChannel};
}

private static int convertToInt(double valueToConvert) {
return (int) Math.round(255 * valueToConvert);
}
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * A utility class to convert Roman numerals into integers.
 *
 * <p>Roman numerals are based on seven symbols given below:
 * <ul>
 *   <li>I = 1</li>
 *   <li>V = 5</li>
 *   <li>X = 10</li>
 *   <li>L = 50</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>If a smaller numeral appears before a larger numeral, it is subtracted.
 * Otherwise, it is added. For example:
 * <pre>
 *   MCMXCIV = 1000 + (1000 - 100) + (100 - 10) + (5 - 1) = 1994
 * </pre>
 */
public final class RomanToInteger {

    private static final Map<Character, Integer> ROMAN_TO_INT = new HashMap<>() {
        {
            put('I', 1);
            put('V', 5);
            put('X', 10);
            put('L', 50);
            put('C', 100);
            put('D', 500);
            put('M', 1000);
        }
    };

    private RomanToInteger() {
    }

    /**
     * Converts a single Roman numeral character to its integer value.
     *
     * @param symbol the Roman numeral character
     * @return the corresponding integer value
     * @throws IllegalArgumentException if the symbol is not a valid Roman numeral
     */
    private static int romanSymbolToInt(final char symbol) {
        return ROMAN_TO_INT.computeIfAbsent(symbol, c -> { throw new IllegalArgumentException("Unknown Roman symbol: " + c); });
    }

    /**
     * Converts a Roman numeral string to its integer equivalent.
     * Steps:
     * <ol>
     *     <li>Iterate over the string from right to left.</li>
     *     <li>For each character, convert it to an integer value.</li>
     *     <li>If the current value is greater than or equal to the max previous value, add it.</li>
     *     <li>Otherwise, subtract it from the sum.</li>
     *     <li>Update the max previous value.</li>
     *     <li>Return the sum.</li>
     * </ol>
     *
     * @param roman the Roman numeral string
     * @return the integer value of the Roman numeral
     * @throws IllegalArgumentException if the input contains invalid Roman characters
     * @throws NullPointerException if the input is {@code null}
     */
    public static int romanToInt(String roman) {
        if (roman == null) {
            throw new NullPointerException("Input cannot be null");
        }

        roman = roman.toUpperCase();
        int sum = 0;
        int maxPrevValue = 0;
        for (int i = roman.length() - 1; i >= 0; i--) {
            int currentValue = romanSymbolToInt(roman.charAt(i));
            if (currentValue >= maxPrevValue) {
                sum += currentValue;
                maxPrevValue = currentValue;
            } else {
                sum -= currentValue;
            }
        }

        return sum;
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * A utility class to convert Roman numerals into integers.
 *
 * <p>Roman numerals are based on seven symbols given below:
 * <ul>
 *   <li>I = 1</li>
 *   <li>V = 5</li>
 *   <li>X = 10</li>
 *   <li>L = 50</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>If a smaller numeral appears before a larger numeral, it is subtracted.
 * Otherwise, it is added. For example:
 * <pre>
 *   MCMXCIV = 1000 + (1000 - 100) + (100 - 10) + (5 - 1) = 1994
 * </pre>
 */
public final class RomanToInteger {

private static final Map<Character, Integer> SYMBOL_VALUES = new HashMap<>() {
{
put('I', 1);
put('V', 5);
put('X', 10);
put('L', 50);
put('C', 100);
put('D', 500);
put('M', 1000);
}
};

private RomanToInteger() {
}

/**
 * Converts a single Roman numeral character to its integer value.
 *
 * @param romanSymbol the Roman numeral character
 * @return the corresponding integer value
 * @throws IllegalArgumentException if the symbol is not a valid Roman numeral
 */
private static int getSymbolValue(final char romanSymbol) {
return SYMBOL_VALUES.computeIfAbsent(romanSymbol, symbol -> { throw new IllegalArgumentException("Unknown Roman symbol: " + symbol); });
}

/**
 * Converts a Roman numeral string to its integer equivalent.
 * Steps:
 * <ol>
 *     <li>Iterate over the string from right to left.</li>
 *     <li>For each character, convert it to an integer value.</li>
 *     <li>If the current value is greater than or equal to the max previous value, add it.</li>
 *     <li>Otherwise, subtract it from the sum.</li>
 *     <li>Update the max previous value.</li>
 *     <li>Return the sum.</li>
 * </ol>
 *
 * @param romanInput the Roman numeral string
 * @return the integer value of the Roman numeral
 * @throws IllegalArgumentException if the input contains invalid Roman characters
 * @throws NullPointerException if the input is {@code null}
 */
public static int romanToInt(String romanInput) {
if (romanInput == null) {
throw new NullPointerException("Input cannot be null");
}
String normalizedInput = romanInput.toUpperCase();
int totalSum = 0;
int maxPreviousValue = 0;
for (int position = normalizedInput.length() - 1; position >= 0; position--) {
int currentValue = getSymbolValue(normalizedInput.charAt(position));
if (currentValue >= maxPreviousValue) {
totalSum += currentValue;
maxPreviousValue = currentValue;
} else {
totalSum -= currentValue;
}
}
return totalSum;
}
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert between different temperature units.
 *
 * <p>This class supports conversions between the following units:
 * <ul>
 *   <li>Celsius</li>
 *   <li>Fahrenheit</li>
 *   <li>Kelvin</li>
 * </ul>
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @author krishna-medapati (https://github.com/krishna-medapati)
 * @see <a href="https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature">Wikipedia: Temperature Conversion</a>
 */
public final class TemperatureConverter {

    private TemperatureConverter() {
    }

    public static double celsiusToFahrenheit(double celsius) {
        return celsius * 9.0 / 5.0 + 32.0;
    }

    public static double celsiusToKelvin(double celsius) {
        return celsius + 273.15;
    }

    public static double fahrenheitToCelsius(double fahrenheit) {
        return (fahrenheit - 32.0) * 5.0 / 9.0;
    }

    public static double fahrenheitToKelvin(double fahrenheit) {
        return (fahrenheit - 32.0) * 5.0 / 9.0 + 273.15;
    }

    public static double kelvinToCelsius(double kelvin) {
        return kelvin - 273.15;
    }

    public static double kelvinToFahrenheit(double kelvin) {
        return (kelvin - 273.15) * 9.0 / 5.0 + 32.0;
    }
}

