package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

/**
 * A class that counts the number of different connected components in a graph
 *
 * @author Lukas Keul, Florian Mercks
 */
class Graph<E extends Comparable<E>> {

    class Node {

        E name;

        Node(E name) {
            this.name = name;
        }
    }

    class Edge {

        Node startNode;
        Node endNode;

        Edge(Node startNode, Node endNode) {
            this.startNode = startNode;
            this.endNode = endNode;
        }
    }

    ArrayList<Edge> edgeList;
    ArrayList<Node> nodeList;

    Graph() {
        edgeList = new ArrayList<Edge>();
        nodeList = new ArrayList<Node>();
    }

    /**
     * Adds a new Edge to the graph. If the nodes aren't yet in nodeList, they
     * will be added to it.
     *
     * @param startNode the starting Node from the edge
     * @param endNode the ending Node from the edge
     */
    public void addEdge(E startNode, E endNode) {
        Node start = null;
        Node end = null;
        for (Node node : nodeList) {
            if (startNode.compareTo(node.name) == 0) {
                start = node;
            } else if (endNode.compareTo(node.name) == 0) {
                end = node;
            }
        }
        if (start == null) {
            start = new Node(startNode);
            nodeList.add(start);
        }
        if (end == null) {
            end = new Node(endNode);
            nodeList.add(end);
        }

        edgeList.add(new Edge(start, end));
    }

    /**
     * Main method used for counting the connected components. Iterates through
     * the array of nodes to do a depth first search to get all nodes of the
     * graph from the actual node. These nodes are added to the array
     * markedNodes and will be ignored if they are chosen in the nodeList.
     *
     * @return returns the amount of unconnected graphs
     */
    public int countGraphs() {
        int count = 0;
        Set<Node> markedNodes = new HashSet<Node>();

        for (Node n : nodeList) {
            if (markedNodes.add(n)) {
                markedNodes.addAll(depthFirstSearch(n, new ArrayList<Node>()));
                count++;
            }
        }

        return count;
    }

    /**
     * Implementation of depth first search.
     *
     * @param n the actual visiting node
     * @param visited A list of already visited nodes in the depth first search
     * @return returns a set of visited nodes
     */
    public ArrayList<Node> depthFirstSearch(Node n, ArrayList<Node> visited) {
        visited.add(n);
        for (Edge e : edgeList) {
            if (e.startNode.equals(n) && !visited.contains(e.endNode)) {
                depthFirstSearch(e.endNode, visited);
            }
        }
        return visited;
    }
}

public final class ConnectedComponent {
    private ConnectedComponent() {
    }

    public static void main(String[] args) {
        Graph<Character> graphChars = new Graph<>();

        // Graph 1
        graphChars.addEdge('a', 'b');
        graphChars.addEdge('a', 'e');
        graphChars.addEdge('b', 'e');
        graphChars.addEdge('b', 'c');
        graphChars.addEdge('c', 'd');
        graphChars.addEdge('d', 'a');

        graphChars.addEdge('x', 'y');
        graphChars.addEdge('x', 'z');

        graphChars.addEdge('w', 'w');

        Graph<Integer> graphInts = new Graph<>();

        // Graph 2
        graphInts.addEdge(1, 2);
        graphInts.addEdge(2, 3);
        graphInts.addEdge(2, 4);
        graphInts.addEdge(3, 5);

        graphInts.addEdge(7, 8);
        graphInts.addEdge(8, 10);
        graphInts.addEdge(10, 8);

        System.out.println("Amount of different char-graphs: " + graphChars.countGraphs());
        System.out.println("Amount of different int-graphs: " + graphInts.countGraphs());
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

/**
 * A class that counts the number of different connected components in a graph
 *
 * @author Lukas Keul, Florian Mercks
 */
class Graph<NodeType extends Comparable<NodeType>> {

class GraphNode {
NodeType nodeName;

GraphNode(NodeType nodeName) {
this.nodeName = nodeName;
}
}

class ConnectionEdge {
GraphNode startNode;
GraphNode endNode;

ConnectionEdge(GraphNode startNode, GraphNode endNode) {
this.startNode = startNode;
this.endNode = endNode;
}
}

ArrayList<ConnectionEdge> edgeList;
ArrayList<GraphNode> nodeList;

Graph() {
edgeList = new ArrayList<ConnectionEdge>();
nodeList = new ArrayList<GraphNode>();
}

/**
 * Adds a new Edge to the graph. If the nodes aren't yet in nodeList, they
 * will be added to it.
 *
 * @param startNode the starting Node from the edge
 * @param endNode the ending Node from the edge
 */
public void insertEdge(NodeType startNode, NodeType endNode) {
GraphNode startVertex = null;
GraphNode endVertex = null;
for (GraphNode existingNode : nodeList) {
if (startNode.compareTo(existingNode.nodeName) == 0) {
startVertex = existingNode;
} else if (endNode.compareTo(existingNode.nodeName) == 0) {
endVertex = existingNode;
}
}
if (startVertex == null) {
startVertex = new GraphNode(startNode);
nodeList.add(startVertex);
}
if (endVertex == null) {
endVertex = new GraphNode(endNode);
nodeList.add(endVertex);
}
edgeList.add(new ConnectionEdge(startVertex, endVertex));
}

/**
 * Main method used for counting the connected components. Iterates through
 * the array of nodes to do a depth first search to get all nodes of the
 * graph from the actual node. These nodes are added to the array
 * markedNodes and will be ignored if they are chosen in the nodeList.
 *
 * @return returns the amount of unconnected graphs
 */
public int countComponents() {
int componentCount = 0;
Set<GraphNode> visitedNodes = new HashSet<GraphNode>();
for (GraphNode currentNode : nodeList) {
if (visitedNodes.add(currentNode)) {
visitedNodes.addAll(performDFS(currentNode, new ArrayList<GraphNode>()));
componentCount++;
}
}
return componentCount;
}

/**
 * Implementation of depth first search.
 *
 * @param startNode the actual visiting node
 * @param visitedNodes A list of already visited nodes in the depth first search
 * @return returns a set of visited nodes
 */
public ArrayList<GraphNode> performDFS(GraphNode startNode, ArrayList<GraphNode> visitedNodes) {
visitedNodes.add(startNode);
for (ConnectionEdge currentEdge : edgeList) {
if (currentEdge.startNode.equals(startNode) && !visitedNodes.contains(currentEdge.endNode)) {
performDFS(currentEdge.endNode, visitedNodes);
}
}
return visitedNodes;
}
}

public final class ConnectedComponent {
private ConnectedComponent() {
}

public static void main(String[] args) {
Graph<Character> charGraph = new Graph<>();
charGraph.insertEdge('a', 'b');
charGraph.insertEdge('a', 'e');
charGraph.insertEdge('b', 'e');
charGraph.insertEdge('b', 'c');
charGraph.insertEdge('c', 'd');
charGraph.insertEdge('d', 'a');
charGraph.insertEdge('x', 'y');
charGraph.insertEdge('x', 'z');
charGraph.insertEdge('w', 'w');
Graph<Integer> intGraph = new Graph<>();
intGraph.insertEdge(1, 2);
intGraph.insertEdge(2, 3);
intGraph.insertEdge(2, 4);
intGraph.insertEdge(3, 5);
intGraph.insertEdge(7, 8);
intGraph.insertEdge(8, 10);
intGraph.insertEdge(10, 8);
System.out.println("Amount of different char-graphs: " + charGraph.countComponents());
System.out.println("Amount of different int-graphs: " + intGraph.countComponents());
}
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Scanner;

class Cycle {

    private final int nodes;
    private int[][] adjacencyMatrix;
    private boolean[] visited;
    ArrayList<ArrayList<Integer>> cycles = new ArrayList<ArrayList<Integer>>();

    Cycle() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the no. of nodes: ");
        nodes = in.nextInt();
        System.out.print("Enter the no. of Edges: ");
        final int edges = in.nextInt();

        adjacencyMatrix = new int[nodes][nodes];
        visited = new boolean[nodes];

        for (int i = 0; i < nodes; i++) {
            visited[i] = false;
        }

        System.out.println("Enter the details of each edges <Start Node> <End Node>");

        for (int i = 0; i < edges; i++) {
            int start;
            int end;
            start = in.nextInt();
            end = in.nextInt();
            adjacencyMatrix[start][end] = 1;
        }
        in.close();
    }

    public void start() {
        for (int i = 0; i < nodes; i++) {
            ArrayList<Integer> temp = new ArrayList<>();
            dfs(i, i, temp);
            for (int j = 0; j < nodes; j++) {
                adjacencyMatrix[i][j] = 0;
                adjacencyMatrix[j][i] = 0;
            }
        }
    }

    private void dfs(Integer start, Integer curr, ArrayList<Integer> temp) {
        temp.add(curr);
        visited[curr] = true;
        for (int i = 0; i < nodes; i++) {
            if (adjacencyMatrix[curr][i] == 1) {
                if (i == start) {
                    cycles.add(new ArrayList<Integer>(temp));
                } else {
                    if (!visited[i]) {
                        dfs(start, i, temp);
                    }
                }
            }
        }

        if (temp.size() > 0) {
            temp.remove(temp.size() - 1);
        }
        visited[curr] = false;
    }

    public void printAll() {
        for (int i = 0; i < cycles.size(); i++) {
            for (int j = 0; j < cycles.get(i).size(); j++) {
                System.out.print(cycles.get(i).get(j) + " -> ");
            }
            System.out.println(cycles.get(i).get(0));
            System.out.println();
        }
    }
}

public final class Cycles {
    private Cycles() {
    }

    public static void main(String[] args) {
        Cycle c = new Cycle();
        c.start();
        c.printAll();
    }
}

