package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Scanner;

class CycleDetector {

private final int vertexCount;
private int[][] connectionMatrix;
private boolean[] visitedNodes;
ArrayList<ArrayList<Integer>> foundCycles = new ArrayList<ArrayList<Integer>>();

CycleDetector() {
Scanner inputReader = new Scanner(System.in);
System.out.print("Enter the no. of nodes: ");
vertexCount = inputReader.nextInt();
System.out.print("Enter the no. of Edges: ");
final int edgeCount = inputReader.nextInt();
connectionMatrix = new int[vertexCount][vertexCount];
visitedNodes = new boolean[vertexCount];
for (int nodeIndex = 0; nodeIndex < vertexCount; nodeIndex++) {
visitedNodes[nodeIndex] = false;
}
System.out.println("Enter the details of each edges <Start Node> <End Node>");
for (int edgeIndex = 0; edgeIndex < edgeCount; edgeIndex++) {
int startVertex = inputReader.nextInt();
int endVertex = inputReader.nextInt();
connectionMatrix[startVertex][endVertex] = 1;
}
inputReader.close();
}

public void findCycles() {
for (int startVertex = 0; startVertex < vertexCount; startVertex++) {
ArrayList<Integer> pathList = new ArrayList<>();
depthFirstSearch(startVertex, startVertex, pathList);
for (int resetIndex = 0; resetIndex < vertexCount; resetIndex++) {
connectionMatrix[startVertex][resetIndex] = 0;
connectionMatrix[resetIndex][startVertex] = 0;
}
}
}

private void depthFirstSearch(Integer startVertex, Integer currentVertex, ArrayList<Integer> pathList) {
pathList.add(currentVertex);
visitedNodes[currentVertex] = true;
for (int neighborIndex = 0; neighborIndex < vertexCount; neighborIndex++) {
if (connectionMatrix[currentVertex][neighborIndex] == 1) {
if (neighborIndex == startVertex) {
foundCycles.add(new ArrayList<Integer>(pathList));
} else {
if (!visitedNodes[neighborIndex]) {
depthFirstSearch(startVertex, neighborIndex, pathList);
}
}
}
}
if (pathList.size() > 0) {
pathList.remove(pathList.size() - 1);
}
visitedNodes[currentVertex] = false;
}

public void displayCycles() {
for (int cycleIndex = 0; cycleIndex < foundCycles.size(); cycleIndex++) {
for (int nodePosition = 0; nodePosition < foundCycles.get(cycleIndex).size(); nodePosition++) {
System.out.print(foundCycles.get(cycleIndex).get(nodePosition) + " -> ");
}
System.out.println(foundCycles.get(cycleIndex).get(0));
System.out.println();
}
}
}

public final class Cycles {
private Cycles() {
}

public static void main(String[] args) {
CycleDetector detector = new CycleDetector();
detector.findCycles();
detector.displayCycles();
}
}
