package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * An implementation of Dial's Algorithm for the single-source shortest path problem.
 * This algorithm is an optimization of Dijkstra's algorithm and is particularly
 * efficient for graphs with small, non-negative integer edge weights.
 *
 * It uses a bucket queue (implemented here as a List of HashSets) to store vertices,
 * where each bucket corresponds to a specific distance from the source. This is more
 * efficient than a standard priority queue when the range of edge weights is small.
 *
 * Time Complexity: O(E + W * V), where E is the number of edges, V is the number
 * of vertices, and W is the maximum weight of any edge.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Dijkstra%27s_algorithm#Dial's_algorithm">Wikipedia - Dial's Algorithm</a>
 */
public final class DialsAlgorithm {
    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private DialsAlgorithm() {
    }
    /**
     * Represents an edge in the graph, connecting to a destination vertex with a given weight.
     */
    public static class Edge {
        private final int destination;
        private final int weight;

        public Edge(int destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }

        public int getDestination() {
            return destination;
        }

        public int getWeight() {
            return weight;
        }
    }
    /**
     * Finds the shortest paths from a source vertex to all other vertices in a weighted graph.
     *
     * @param graph The graph represented as an adjacency list.
     * @param source The source vertex to start from (0-indexed).
     * @param maxEdgeWeight The maximum weight of any single edge in the graph.
     * @return An array of integers where the value at each index `i` is the
     * shortest distance from the source to vertex `i`. Unreachable vertices
     * will have a value of Integer.MAX_VALUE.
     * @throws IllegalArgumentException if the source vertex is out of bounds.
     */
    public static int[] run(List<List<Edge>> graph, int source, int maxEdgeWeight) {
        int numVertices = graph.size();
        if (source < 0 || source >= numVertices) {
            throw new IllegalArgumentException("Source vertex is out of bounds.");
        }

        // Initialize distances array
        int[] distances = new int[numVertices];
        Arrays.fill(distances, Integer.MAX_VALUE);
        distances[source] = 0;

        // The bucket queue. Size is determined by the max possible path length.
        int maxPathWeight = maxEdgeWeight * (numVertices > 0 ? numVertices - 1 : 0);
        List<Set<Integer>> buckets = new ArrayList<>(maxPathWeight + 1);
        for (int i = 0; i <= maxPathWeight; i++) {
            buckets.add(new HashSet<>());
        }

        // Add the source vertex to the first bucket
        buckets.get(0).add(source);

        // Process buckets in increasing order of distance
        for (int d = 0; d <= maxPathWeight; d++) {
            // Process all vertices in the current bucket
            while (!buckets.get(d).isEmpty()) {
                // Get and remove a vertex from the current bucket
                int u = buckets.get(d).iterator().next();
                buckets.get(d).remove(u);

                // If we've found a shorter path already, skip
                if (d > distances[u]) {
                    continue;
                }

                // Relax all adjacent edges
                for (Edge edge : graph.get(u)) {
                    int v = edge.getDestination();
                    int weight = edge.getWeight();

                    // If a shorter path to v is found
                    if (distances[u] != Integer.MAX_VALUE && distances[u] + weight < distances[v]) {
                        // If v was already in a bucket, remove it from the old one
                        if (distances[v] != Integer.MAX_VALUE) {
                            buckets.get(distances[v]).remove(v);
                        }
                        // Update distance and move v to the new bucket
                        distances[v] = distances[u] + weight;
                        buckets.get(distances[v]).add(v);
                    }
                }
            }
        }
        return distances;
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * An implementation of Dial's Algorithm for the single-source shortest path problem.
 * This algorithm is an optimization of Dijkstra's algorithm and is particularly
 * efficient for graphs with small, non-negative integer edge weights.
 *
 * It uses a bucket queue (implemented here as a List of HashSets) to store vertices,
 * where each bucket corresponds to a specific distance from the source. This is more
 * efficient than a standard priority queue when the range of edge weights is small.
 *
 * Time Complexity: O(E + W * V), where E is the number of edges, V is the number
 * of vertices, and W is the maximum weight of any edge.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Dijkstra%27s_algorithm#Dial's_algorithm">Wikipedia - Dial's Algorithm</a>
 */
public final class DialsAlgorithm {
/**
 * Private constructor to prevent instantiation of this utility class.
 */
private DialsAlgorithm() {
}
/**
 * Represents an edge in the graph, connecting to a destination vertex with a given weight.
 */
public static class WeightedEdge {
private final int targetVertex;
private final int edgeWeight;

public WeightedEdge(int targetVertex, int edgeWeight) {
this.targetVertex = targetVertex;
this.edgeWeight = edgeWeight;
}

public int getTargetVertex() {
return targetVertex;
}

public int getEdgeWeight() {
return edgeWeight;
}
}
/**
 * Finds the shortest paths from a source vertex to all other vertices in a weighted graph.
 *
 * @param adjacencyList The graph represented as an adjacency list.
 * @param startVertex The source vertex to start from (0-indexed).
 * @param maxWeightValue The maximum weight of any single edge in the graph.
 * @return An array of integers where the value at each index `i` is the
 * shortest distance from the source to vertex `i`. Unreachable vertices
 * will have a value of Integer.MAX_VALUE.
 * @throws IllegalArgumentException if the source vertex is out of bounds.
 */
public static int[] findShortestPaths(List<List<WeightedEdge>> adjacencyList, int startVertex, int maxWeightValue) {
int totalVertices = adjacencyList.size();
if (startVertex < 0 || startVertex >= totalVertices) {
throw new IllegalArgumentException("Source vertex is out of bounds.");
}
int[] shortestDistances = new int[totalVertices];
Arrays.fill(shortestDistances, Integer.MAX_VALUE);
shortestDistances[startVertex] = 0;
int maxPossiblePath = maxWeightValue * (totalVertices > 0 ? totalVertices - 1 : 0);
List<Set<Integer>> distanceBuckets = new ArrayList<>(maxPossiblePath + 1);
for (int bucketIndex = 0; bucketIndex <= maxPossiblePath; bucketIndex++) {
distanceBuckets.add(new HashSet<>());
}
distanceBuckets.get(0).add(startVertex);
for (int currentDistance = 0; currentDistance <= maxPossiblePath; currentDistance++) {
while (!distanceBuckets.get(currentDistance).isEmpty()) {
int currentVertex = distanceBuckets.get(currentDistance).iterator().next();
distanceBuckets.get(currentDistance).remove(currentVertex);
if (currentDistance > shortestDistances[currentVertex]) {
continue;
}
for (WeightedEdge neighborEdge : adjacencyList.get(currentVertex)) {
int neighborVertex = neighborEdge.getTargetVertex();
int edgeCost = neighborEdge.getEdgeWeight();
if (shortestDistances[currentVertex] != Integer.MAX_VALUE &&
shortestDistances[currentVertex] + edgeCost < shortestDistances[neighborVertex]) {
if (shortestDistances[neighborVertex] != Integer.MAX_VALUE) {
distanceBuckets.get(shortestDistances[neighborVertex]).remove(neighborVertex);
}
shortestDistances[neighborVertex] = shortestDistances[currentVertex] + edgeCost;
distanceBuckets.get(shortestDistances[neighborVertex]).add(neighborVertex);
}
}
}
}
}
return shortestDistances;
}
}

package com.thealgorithms.datastructures.graphs;

import java.util.Arrays;

/**
 * Dijkstra's algorithm for finding the shortest path from a single source vertex to all other vertices in a graph.
 */
public class DijkstraAlgorithm {

    private final int vertexCount;

    /**
     * Constructs a Dijkstra object with the given number of vertices.
     *
     * @param vertexCount The number of vertices in the graph.
     */
    public DijkstraAlgorithm(int vertexCount) {
        this.vertexCount = vertexCount;
    }

    /**
     * Executes Dijkstra's algorithm on the provided graph to find the shortest paths from the source vertex to all other vertices.
     *
     * The graph is represented as an adjacency matrix where {@code graph[i][j]} represents the weight of the edge from vertex {@code i}
     * to vertex {@code j}. A value of 0 indicates no edge exists between the vertices.
     *
     * @param graph The graph represented as an adjacency matrix.
     * @param source The source vertex.
     * @return An array where the value at each index {@code i} represents the shortest distance from the source vertex to vertex {@code i}.
     * @throws IllegalArgumentException if the source vertex is out of range.
     */
    public int[] run(int[][] graph, int source) {
        if (source < 0 || source >= vertexCount) {
            throw new IllegalArgumentException("Incorrect source");
        }

        int[] distances = new int[vertexCount];
        boolean[] processed = new boolean[vertexCount];

        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(processed, false);
        distances[source] = 0;

        for (int count = 0; count < vertexCount - 1; count++) {
            int u = getMinDistanceVertex(distances, processed);
            processed[u] = true;

            for (int v = 0; v < vertexCount; v++) {
                if (!processed[v] && graph[u][v] != 0 && distances[u] != Integer.MAX_VALUE && distances[u] + graph[u][v] < distances[v]) {
                    distances[v] = distances[u] + graph[u][v];
                }
            }
        }

        printDistances(distances);
        return distances;
    }

    /**
     * Finds the vertex with the minimum distance value from the set of vertices that have not yet been processed.
     *
     * @param distances The array of current shortest distances from the source vertex.
     * @param processed The array indicating whether each vertex has been processed.
     * @return The index of the vertex with the minimum distance value.
     */
    private int getMinDistanceVertex(int[] distances, boolean[] processed) {
        int min = Integer.MAX_VALUE;
        int minIndex = -1;

        for (int v = 0; v < vertexCount; v++) {
            if (!processed[v] && distances[v] <= min) {
                min = distances[v];
                minIndex = v;
            }
        }

        return minIndex;
    }

    /**
     * Prints the shortest distances from the source vertex to all other vertices.
     *
     * @param distances The array of shortest distances.
     */
    private void printDistances(int[] distances) {
        System.out.println("Vertex \t Distance");
        for (int i = 0; i < vertexCount; i++) {
            System.out.println(i + " \t " + distances[i]);
        }
    }
}

