package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * The EdmondsBlossomAlgorithm class implements Edmonds' Blossom Algorithm
 * to find the maximum matching in a general graph. The algorithm efficiently
 * handles cases where the graph contains odd-length cycles by contracting
 * "blossoms" and finding augmenting paths.
 *<p>
 * <a href="https://stanford.edu/~rezab/classes/cme323/S16/projects_reports/shoemaker_vare.pdf">Documentation of Algorithm (Stanford University)</a>
 * <p></p>
 * <a href="https://en.wikipedia.org/wiki/Blossom_algorithm">Wikipedia Documentation</a>
 */
public final class EdmondsBlossomAlgorithm {

private EdmondsBlossomAlgorithm() {
}

private static final int NO_MATCH = -1;

/**
 * Finds the maximum matching in a general graph (Edmonds Blossom Algorithm).
 *
 * @param edgeList A list of edges in the graph.
 * @param totalVertices The number of vertices in the graph.
 * @return A list of matched pairs of vertices.
 */
public static List<int[]> findMaximumMatching(Iterable<int[]> edgeList, int totalVertices) {
List<List<Integer>> adjacencyGraph = new ArrayList<>(totalVertices);
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
adjacencyGraph.add(new ArrayList<>());
}
for (int[] edgeData : edgeList) {
int fromNode = edgeData[0];
int toNode = edgeData[1];
adjacencyGraph.get(fromNode).add(toNode);
adjacencyGraph.get(toNode).add(fromNode);
}
int[] matchingArray = new int[totalVertices];
Arrays.fill(matchingArray, NO_MATCH);
int[] parentPointer = new int[totalVertices];
int[] baseNode = new int[totalVertices];
boolean[] blossomFlag = new boolean[totalVertices];
boolean[] queueFlag = new boolean[totalVertices];
for (int startNode = 0; startNode < totalVertices; startNode++) {
if (matchingArray[startNode] == NO_MATCH) {
Arrays.fill(parentPointer, NO_MATCH);
for (int nodeIndex = 0; nodeIndex < totalVertices; nodeIndex++) {
baseNode[nodeIndex] = nodeIndex;
}
Arrays.fill(blossomFlag, false);
Arrays.fill(queueFlag, false);
Queue<Integer> bfsQueue = new LinkedList<>();
bfsQueue.add(startNode);
queueFlag[startNode] = true;
boolean pathFound = false;
while (!bfsQueue.isEmpty() && !pathFound) {
int currentNode = bfsQueue.poll();
for (int neighborNode : adjacencyGraph.get(currentNode)) {
if (matchingArray[currentNode] == neighborNode) {
continue;
}
if (baseNode[currentNode] == baseNode[neighborNode]) {
continue;
}
if (parentPointer[neighborNode] == NO_MATCH) {
if (matchingArray[neighborNode] == NO_MATCH) {
parentPointer[neighborNode] = currentNode;
pathFound = true;
updateMatchedPairs(matchingArray, parentPointer, neighborNode);
break;
}
int matchedVertex = matchingArray[neighborNode];
parentPointer[neighborNode] = currentNode;
parentPointer[matchedVertex] = neighborNode;
if (!queueFlag[matchedVertex]) {
bfsQueue.add(matchedVertex);
queueFlag[matchedVertex] = true;
}
} else {
int lowestCommonAncestor = findLowestCommonAncestor(baseNode, parentPointer, currentNode, neighborNode);
if (lowestCommonAncestor != NO_MATCH) {
shrinkBlossom(new BlossomParameters(new AuxiliaryData(bfsQueue, parentPointer, baseNode, blossomFlag, matchingArray, queueFlag), currentNode, neighborNode, lowestCommonAncestor));
}
}
}
}
}
}
}
List<int[]> finalMatching = new ArrayList<>();
for (int vertexIdx = 0; vertexIdx < totalVertices; vertexIdx++) {
if (matchingArray[vertexIdx] != NO_MATCH && vertexIdx < matchingArray[vertexIdx]) {
finalMatching.add(new int[] {vertexIdx, matchingArray[vertexIdx]});
}
}
return finalMatching;
}

private static void updateMatchedPairs(int[] matchingArray, int[] parentPointer, int targetVertex) {
while (targetVertex != NO_MATCH) {
int previousVertex = parentPointer[targetVertex];
int nextVertex = matchingArray[previousVertex];
matchingArray[previousVertex] = targetVertex;
matchingArray[targetVertex] = previousVertex;
targetVertex = nextVertex;
}
}

private static int findLowestCommonAncestor(int[] baseNode, int[] parentPointer, int firstNode, int secondNode) {
boolean[] visitedFlag = new boolean[baseNode.length];
int currentFirst = firstNode;
while (true) {
currentFirst = baseNode[currentFirst];
visitedFlag[currentFirst] = true;
if (parentPointer[currentFirst] == NO_MATCH) {
break;
}
currentFirst = parentPointer[currentFirst];
}
int currentSecond = secondNode;
while (true) {
currentSecond = baseNode[currentSecond];
if (visitedFlag[currentSecond]) {
return currentSecond;
}
currentSecond = parentPointer[currentSecond];
}
}

private static void shrinkBlossom(BlossomParameters blossomData) {
for (int nodeX = blossomData.firstVertex; blossomData.auxData.baseNode[nodeX] != blossomData.lcaValue; nodeX = blossomData.auxData.parentPointer[blossomData.auxData.matchingArray[nodeX]]) {
int baseX = blossomData.auxData.baseNode[nodeX];
int matchBaseX = blossomData.auxData.baseNode[blossomData.auxData.matchingArray[nodeX]];
blossomData.auxData.blossomFlag[baseX] = true;
blossomData.auxData.blossomFlag[matchBaseX] = true;
}
for (int nodeY = blossomData.secondVertex; blossomData.auxData.baseNode[nodeY] != blossomData.lcaValue; nodeY = blossomData.auxData.parentPointer[blossomData.auxData.matchingArray[nodeY]]) {
int baseY = blossomData.auxData.baseNode[nodeY];
int matchBaseY = blossomData.auxData.baseNode[blossomData.auxData.matchingArray[nodeY]];
blossomData.auxData.blossomFlag[baseY] = true;
blossomData.auxData.blossomFlag[matchBaseY] = true;
}
for (int nodeIndex = 0; nodeIndex < blossomData.auxData.baseNode.length; nodeIndex++) {
if (blossomData.auxData.blossomFlag[blossomData.auxData.baseNode[nodeIndex]]) {
blossomData.auxData.baseNode[nodeIndex] = blossomData.lcaValue;
if (!blossomData.auxData.queueFlag[nodeIndex]) {
blossomData.auxData.traversalQueue.add(nodeIndex);
blossomData.auxData.queueFlag[nodeIndex] = true;
}
}
}
}

static class AuxiliaryData {
Queue<Integer> traversalQueue;
int[] parentPointer;
int[] baseNode;
boolean[] blossomFlag;
int[] matchingArray;
boolean[] queueFlag;

AuxiliaryData(Queue<Integer> traversalQueue, int[] parentPointer, int[] baseNode, boolean[] blossomFlag, int[] matchingArray, boolean[] queueFlag) {
this.traversalQueue = traversalQueue;
this.parentPointer = parentPointer;
this.baseNode = baseNode;
this.blossomFlag = blossomFlag;
this.matchingArray = matchingArray;
this.queueFlag = queueFlag;
}
}

static class BlossomParameters {
AuxiliaryData auxData;
int firstVertex;
int secondVertex;
int lcaValue;

BlossomParameters(AuxiliaryData auxData, int firstVertex, int secondVertex, int lcaValue) {
this.auxData = auxData;
this.firstVertex = firstVertex;
this.secondVertex = secondVertex;
this.lcaValue = lcaValue;
}
}
}
