package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;

class AdjacencyListGraph<E extends Comparable<E>> {

    ArrayList<Vertex> vertices;

    AdjacencyListGraph() {
        vertices = new ArrayList<>();
    }

    private class Vertex {

        E data;
        ArrayList<Vertex> adjacentVertices;

        Vertex(E data) {
            adjacentVertices = new ArrayList<>();
            this.data = data;
        }

        public boolean addAdjacentVertex(Vertex to) {
            for (Vertex v : adjacentVertices) {
                if (v.data.compareTo(to.data) == 0) {
                    return false; // the edge already exists
                }
            }
            return adjacentVertices.add(to); // this will return true;
        }

        public boolean removeAdjacentVertex(E to) {
            // use indexes here so it is possible to
            // remove easily without implementing
            // equals method that ArrayList.remove(Object o) uses
            for (int i = 0; i < adjacentVertices.size(); i++) {
                if (adjacentVertices.get(i).data.compareTo(to) == 0) {
                    adjacentVertices.remove(i);
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * this method removes an edge from the graph between two specified
     * vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns false if the edge doesn't exist, returns true if the edge
     * exists and is removed
     */
    public boolean removeEdge(E from, E to) {
        Vertex fromV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) {
                fromV = v;
                break;
            }
        }
        if (fromV == null) {
            return false;
        }
        return fromV.removeAdjacentVertex(to);
    }

    /**
     * this method adds an edge to the graph between two specified vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns true if the edge did not exist, return false if it
     * already did
     */
    public boolean addEdge(E from, E to) {
        Vertex fromV = null;
        Vertex toV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) { // see if from vertex already exists
                fromV = v;
            } else if (to.compareTo(v.data) == 0) { // see if to vertex already exists
                toV = v;
            }
            if (fromV != null && toV != null) {
                break; // both nodes exist so stop searching
            }
        }
        if (fromV == null) {
            fromV = new Vertex(from);
            vertices.add(fromV);
        }
        if (toV == null) {
            toV = new Vertex(to);
            vertices.add(toV);
        }
        return fromV.addAdjacentVertex(toV);
    }

    /**
     * this gives a list of vertices in the graph and their adjacencies
     *
     * @return returns a string describing this graph
     */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Vertex v : vertices) {
            sb.append("Vertex: ");
            sb.append(v.data);
            sb.append("\n");
            sb.append("Adjacent vertices: ");
            for (Vertex v2 : v.adjacentVertices) {
                sb.append(v2.data);
                sb.append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }
}

public final class Graphs {
    private Graphs() {
    }

    public static void main(String[] args) {
        AdjacencyListGraph<Integer> graph = new AdjacencyListGraph<>();
        assert graph.addEdge(1, 2);
        assert graph.addEdge(1, 5);
        assert graph.addEdge(2, 5);
        assert !graph.addEdge(1, 2);
        assert graph.addEdge(2, 3);
        assert graph.addEdge(3, 4);
        assert graph.addEdge(4, 1);
        assert !graph.addEdge(2, 3);
        System.out.println(graph);
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;

class AdjacencyListGraph<ElementType extends Comparable<ElementType>> {

ArrayList<GraphVertex> vertexList;

AdjacencyListGraph() {
vertexList = new ArrayList<>();
}

private class GraphVertex {
ElementType nodeValue;
ArrayList<GraphVertex> neighborList;

GraphVertex(ElementType nodeValue) {
neighborList = new ArrayList<>();
this.nodeValue = nodeValue;
}

public boolean addNeighbor(GraphVertex targetVertex) {
for (GraphVertex existingNeighbor : neighborList) {
if (existingNeighbor.nodeValue.compareTo(targetVertex.nodeValue) == 0) {
return false;
}
}
return neighborList.add(targetVertex);
}

public boolean removeNeighbor(ElementType neighborValue) {
for (int index = 0; index < neighborList.size(); index++) {
if (neighborList.get(index).nodeValue.compareTo(neighborValue) == 0) {
neighborList.remove(index);
return true;
}
}
return false;
}
}

/**
 * this method removes an edge from the graph between two specified
 * vertices
 *
 * @param startValue the data of the vertex the edge is from
 * @param endValue the data of the vertex the edge is going to
 * @return returns false if the edge doesn't exist, returns true if the edge
 * exists and is removed
 */
public boolean removeEdge(ElementType startValue, ElementType endValue) {
GraphVertex startVertex = null;
for (GraphVertex currentVertex : vertexList) {
if (startValue.compareTo(currentVertex.nodeValue) == 0) {
startVertex = currentVertex;
break;
}
}
if (startVertex == null) {
return false;
}
return startVertex.removeNeighbor(endValue);
}

/**
 * this method adds an edge to the graph between two specified vertices
 *
 * @param startValue the data of the vertex the edge is from
 * @param endValue the data of the vertex the edge is going to
 * @return returns true if the edge did not exist, return false if it
 * already did
 */
public boolean addEdge(ElementType startValue, ElementType endValue) {
GraphVertex startVertex = null;
GraphVertex endVertex = null;
for (GraphVertex currentVertex : vertexList) {
if (startValue.compareTo(currentVertex.nodeValue) == 0) {
startVertex = currentVertex;
} else if (endValue.compareTo(currentVertex.nodeValue) == 0) {
endVertex = currentVertex;
}
if (startVertex != null && endVertex != null) {
break;
}
}
if (startVertex == null) {
startVertex = new GraphVertex(startValue);
vertexList.add(startVertex);
}
if (endVertex == null) {
endVertex = new GraphVertex(endValue);
vertexList.add(endVertex);
}
return startVertex.addNeighbor(endVertex);
}

/**
 * this gives a list of vertices in the graph and their adjacencies
 *
 * @return returns a string describing this graph
 */
@Override
public String toString() {
StringBuilder outputBuilder = new StringBuilder();
for (GraphVertex currentVertex : vertexList) {
outputBuilder.append("Vertex: ");
outputBuilder.append(currentVertex.nodeValue);
outputBuilder.append("\n");
outputBuilder.append("Adjacent vertices: ");
for (GraphVertex neighborVertex : currentVertex.neighborList) {
outputBuilder.append(neighborVertex.nodeValue);
outputBuilder.append(" ");
}
outputBuilder.append("\n");
}
return outputBuilder.toString();
}
}

public final class Graphs {
private Graphs() {
}

public static void main(String[] args) {
AdjacencyListGraph<Integer> sampleGraph = new AdjacencyListGraph<>();
assert sampleGraph.addEdge(1, 2);
assert sampleGraph.addEdge(1, 5);
assert sampleGraph.addEdge(2, 5);
assert !sampleGraph.addEdge(1, 2);
assert sampleGraph.addEdge(2, 3);
assert sampleGraph.addEdge(3, 4);
assert sampleGraph.addEdge(4, 1);
assert !sampleGraph.addEdge(2, 3);
System.out.println(sampleGraph);
}
}

package com.thealgorithms.datastructures.graphs;

import java.util.Arrays;

/**
 * Java program to find a Hamiltonian Cycle in a graph.
 * A Hamiltonian Cycle is a cycle that visits every vertex exactly once
 * and returns to the starting vertex.
 *
 * <p>For more details, see the
 * <a href="https://en.wikipedia.org/wiki/Hamiltonian_path">Wikipedia article</a>.
 *
 * @author  <a href="https://github.com/itsAkshayDubey">Akshay Dubey</a>
 */
public class HamiltonianCycle {

    private int vertex;
    private int pathCount;
    private int[] cycle;
    private int[][] graph;

    /**
     * Finds a Hamiltonian Cycle for the given graph.
     *
     * @param graph Adjacency matrix representing the graph G(V, E), where V is
     *              the set of vertices and E is the set of edges.
     * @return An array representing the Hamiltonian cycle if found, otherwise an
     *         array filled with -1 indicating no Hamiltonian cycle exists.
     */
    public int[] findHamiltonianCycle(int[][] graph) {
        // Single vertex graph
        if (graph.length == 1) {
            return new int[] {0, 0};
        }

        this.vertex = graph.length;
        this.cycle = new int[this.vertex + 1];

        // Initialize the cycle array with -1 to represent unvisited vertices
        Arrays.fill(this.cycle, -1);

        this.graph = graph;
        this.cycle[0] = 0;
        this.pathCount = 1;
        if (!isPathFound(0)) {
            Arrays.fill(this.cycle, -1);
        } else {
            this.cycle[this.cycle.length - 1] = this.cycle[0];
        }

        return cycle;
    }

    /**
     * Recursively searches for a Hamiltonian cycle from the given vertex.
     *
     * @param vertex The current vertex from which to explore paths.
     * @return {@code true} if a Hamiltonian cycle is found, otherwise {@code false}.
     */
    public boolean isPathFound(int vertex) {
        boolean isLastVertexConnectedToStart = this.graph[vertex][0] == 1 && this.pathCount == this.vertex;
        if (isLastVertexConnectedToStart) {
            return true;
        }

        // If all vertices are visited but the last vertex is not connected to the start
        if (this.pathCount == this.vertex) {
            return false;
        }

        for (int v = 0; v < this.vertex; v++) {
            if (this.graph[vertex][v] == 1) { // Check if there is an edge
                this.cycle[this.pathCount++] = v; // Add the vertex to the cycle
                this.graph[vertex][v] = 0;
                this.graph[v][vertex] = 0;

                // Recursively attempt to complete the cycle
                if (!isPresent(v)) {
                    return isPathFound(v);
                }

                // Restore the edge if the path does not work
                this.graph[vertex][v] = 1;
                this.graph[v][vertex] = 1;

                this.cycle[--this.pathCount] = -1;
            }
        }
        return false;
    }

    /**
     * Checks if a vertex is already part of the current Hamiltonian path.
     *
     * @param vertex The vertex to check.
     * @return {@code true} if the vertex is already in the path, otherwise {@code false}.
     */
    public boolean isPresent(int vertex) {
        for (int i = 0; i < pathCount - 1; i++) {
            if (cycle[i] == vertex) {
                return true;
            }
        }
        return false;
    }
}

