package com.thealgorithms.datastructures.graphs;

import java.util.Comparator;
import java.util.HashSet;
import java.util.PriorityQueue;

/**
 * The Kruskal class implements Kruskal's Algorithm to find the Minimum Spanning Tree (MST)
 * of a connected, undirected graph. The algorithm constructs the MST by selecting edges
 * with the least weight, ensuring no cycles are formed, and using union-find to track the
 * connected components.
 *
 * <p><strong>Key Features:</strong></p>
 * <ul>
 *   <li>The graph is represented using an adjacency list, where each node points to a set of edges.</li>
 *   <li>Each edge is processed in ascending order of weight using a priority queue.</li>
 *   <li>The algorithm stops when all nodes are connected or no more edges are available.</li>
 * </ul>
 *
 * <p><strong>Time Complexity:</strong> O(E log V), where E is the number of edges and V is the number of vertices.</p>
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class KruskalMST {

/**
 * Represents an edge in the graph with a source, destination, and weight.
 */
static class GraphEdge {
int sourceVertex;
int targetVertex;
int edgeWeight;

GraphEdge(int sourceVertex, int targetVertex, int edgeWeight) {
this.sourceVertex = sourceVertex;
this.targetVertex = targetVertex;
this.edgeWeight = edgeWeight;
}
}

/**
 * Adds an edge to the graph.
 *
 * @param adjacencySet the adjacency list representing the graph
 * @param startNode the source vertex of the edge
 * @param endNode the destination vertex of the edge
 * @param weightValue the weight of the edge
 */
static void insertEdge(HashSet<GraphEdge>[] adjacencySet, int startNode, int endNode, int weightValue) {
adjacencySet[startNode].add(new GraphEdge(startNode, endNode, weightValue));
}

/**
 * Kruskal's algorithm to find the Minimum Spanning Tree (MST) of a graph.
 *
 * @param inputGraph the adjacency list representing the input graph
 * @return the adjacency list representing the MST
 */
public HashSet<GraphEdge>[] findMinimumSpanningTree(HashSet<GraphEdge>[] inputGraph) {
int totalNodes = inputGraph.length;
int[] parentLeader = new int[totalNodes];
HashSet<Integer>[] componentGroups = new HashSet[totalNodes];
HashSet<GraphEdge>[] mstGraph = new HashSet[totalNodes];
PriorityQueue<GraphEdge> edgeQueue = new PriorityQueue<>(Comparator.comparingInt(edgeItem -> edgeItem.edgeWeight));
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
mstGraph[nodeIndex] = new HashSet<>();
componentGroups[nodeIndex] = new HashSet<>();
componentGroups[nodeIndex].add(nodeIndex);
parentLeader[nodeIndex] = nodeIndex;
edgeQueue.addAll(inputGraph[nodeIndex]);
}
int connectedCount = 0;
while (connectedCount != totalNodes && !edgeQueue.isEmpty()) {
GraphEdge currentEdge = edgeQueue.poll();
if (!componentGroups[parentLeader[currentEdge.sourceVertex]].contains(currentEdge.targetVertex) &&
!componentGroups[parentLeader[currentEdge.targetVertex]].contains(currentEdge.sourceVertex)) {
componentGroups[parentLeader[currentEdge.sourceVertex]].addAll(componentGroups[parentLeader[currentEdge.targetVertex]]);
componentGroups[parentLeader[currentEdge.sourceVertex]].forEach(nodeItem -> parentLeader[nodeItem] = parentLeader[currentEdge.sourceVertex]);
insertEdge(mstGraph, currentEdge.sourceVertex, currentEdge.targetVertex, currentEdge.edgeWeight);
connectedCount = componentGroups[parentLeader[currentEdge.sourceVertex]].size();
}
}
return mstGraph;
}
}
