public final class MatrixGraphs {
private MatrixGraphs() {
}

public static void main(String[] args) {
AdjacencyMatrixGraph sampleGraph = new AdjacencyMatrixGraph(10);
sampleGraph.addEdge(1, 2);
sampleGraph.addEdge(1, 5);
sampleGraph.addEdge(2, 5);
sampleGraph.addEdge(1, 2);
sampleGraph.addEdge(2, 3);
sampleGraph.addEdge(3, 4);
sampleGraph.addEdge(4, 1);
sampleGraph.addEdge(2, 3);
sampleGraph.addEdge(3, 9);
sampleGraph.addEdge(9, 1);
sampleGraph.addEdge(9, 8);
sampleGraph.addEdge(1, 8);
