package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.ArrayList;
import java.util.LinkedList;

/**
 * A generic implementation of a hash map using an array list of linked lists for collision resolution.
 * This class allows storage of key-value pairs with average-case constant time complexity for insertion,
 * deletion, and retrieval operations.
 *
 * <p>
 * The hash map uses separate chaining to handle collisions. Each bucket in the hash map is represented
 * by a linked list that holds nodes containing key-value pairs. When multiple keys hash to the same index,
 * they are stored in the same linked list.
 * </p>
 *
 * <p>
 * The hash map automatically resizes itself when the load factor exceeds 0.5. The load factor is defined
 * as the ratio of the number of entries to the number of buckets. When resizing occurs, all existing entries
 * are rehashed and inserted into the new buckets.
 * </p>
 *
 * @param <KeyType> the type of keys maintained by this hash map
 * @param <ValueType> the type of mapped values
 */
public class GenericHashMapUsingArrayList<KeyType, ValueType> {

private ArrayList<LinkedList<DataNode>> bucketList;
private int elementCount;

/**
 * Constructs a new empty hash map with an initial capacity of 10 buckets.
 */
public GenericHashMapUsingArrayList() {
bucketList = new ArrayList<>();
for (int bucketSlot = 0; bucketSlot < 10; bucketSlot++) {
bucketList.add(new LinkedList<>());
}
elementCount = 0;
}

/**
 * Associates the specified value with the specified key in this map.
 * If the map previously contained a mapping for the key, the old value is replaced.
 *
 * @param insertKey the key with which the specified value is to be associated
 * @param insertValue the value to be associated with the specified key
 */
public void put(KeyType insertKey, ValueType insertValue) {
int hashIndex = Math.abs(insertKey.hashCode() % bucketList.size());
LinkedList<DataNode> targetBucket = bucketList.get(hashIndex);
for (DataNode existingNode : targetBucket) {
if (existingNode.keyData.equals(insertKey)) {
existingNode.valueData = insertValue;
return;
}
}
targetBucket.add(new DataNode(insertKey, insertValue));
elementCount++;
float resizingThreshold = 0.5f;
if ((float) elementCount / bucketList.size() > resizingThreshold) {
resizeAndRehash();
}
}

/**
 * Resizes the hash map by doubling the number of buckets and rehashing existing entries.
 */
private void resizeAndRehash() {
ArrayList<LinkedList<DataNode>> oldBuckets = bucketList;
bucketList = new ArrayList<>();
elementCount = 0;
for (int bucketIndex = 0; bucketIndex < oldBuckets.size() * 2; bucketIndex++) {
bucketList.add(new LinkedList<>());
}
for (LinkedList<DataNode> currentBucket : oldBuckets) {
for (DataNode nodeEntry : currentBucket) {
put(nodeEntry.keyData, nodeEntry.valueData);
}
}
}

/**
 * Returns the value to which the specified key is mapped, or null if this map contains no mapping for the key.
 *
 * @param searchKey the key whose associated value is to be returned
 * @return the value associated with the specified key, or null if no mapping exists
 */
public ValueType get(KeyType searchKey) {
int hashIndex = Math.abs(searchKey.hashCode() % bucketList.size());
LinkedList<DataNode> targetBucket = bucketList.get(hashIndex);
for (DataNode currentNode : targetBucket) {
if (currentNode.keyData.equals(searchKey)) {
return currentNode.valueData;
}
}
return null;
}

/**
 * Removes the mapping for the specified key from this map if present.
 *
 * @param targetKey the key whose mapping is to be removed from the map
 */
public void remove(KeyType targetKey) {
int hashIndex = Math.abs(targetKey.hashCode() % bucketList.size());
LinkedList<DataNode> targetBucket = bucketList.get(hashIndex);
DataNode nodeToRemove = null;
for (DataNode currentNode : targetBucket) {
if (currentNode.keyData.equals(targetKey)) {
nodeToRemove = currentNode;
break;
}
}
if (nodeToRemove != null) {
targetBucket.remove(nodeToRemove);
elementCount--;
}
}

/**
 * Returns true if this map contains a mapping for the specified key.
 *
 * @param searchKey the key whose presence in this map is to be tested
 * @return true if this map contains a mapping for the specified key
 */
public boolean containsKey(KeyType searchKey) {
return get(searchKey) != null;
}

/**
 * Returns the number of key-value pairs in this map.
 *
 * @return the number of key-value pairs
 */
public int getElementCount() {
return this.elementCount;
}

/**
 * Returns a string representation of the map, containing all key-value pairs.
 *
 * @return a string representation of the map
 */
@Override
public String toString() {
StringBuilder outputBuilder = new StringBuilder();
outputBuilder.append("{");
for (LinkedList<DataNode> currentBucket : bucketList) {
for (DataNode nodeEntry : currentBucket) {
outputBuilder.append(nodeEntry.keyData);
outputBuilder.append(" : ");
outputBuilder.append(nodeEntry.valueData);
outputBuilder.append(", ");
}
}
if (outputBuilder.length() > 1) {
outputBuilder.setLength(outputBuilder.length() - 2);
}
outputBuilder.append("}");
return outputBuilder.toString();
}

/**
 * A private inner class representing a key-value pair (node) in the hash map.
 */
private class DataNode {
KeyType keyData;
ValueType valueData;

/**
 * Constructs a new Node with the specified key and value.
 *
 * @param inputKey the key of the key-value pair
 * @param inputValue the value of the key-value pair
 */
DataNode(KeyType inputKey, ValueType inputValue) {
this.keyData = inputKey;
this.valueData = inputValue;
}
}
}
