package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.Objects;

/**
 * This class implements a hash table using Cuckoo Hashing.
 * Cuckoo hashing is a type of open-addressing hash table that resolves collisions
 * by relocating existing keys. It utilizes two hash functions to minimize collisions
 * and automatically resizes the table when the load factor exceeds 0.7.
 *
 * For more information on cuckoo hashing, refer to
 * <a href="https://en.wikipedia.org/wiki/Cuckoo_hashing">this Wikipedia page</a>.
 */
public class CuckooHashMap {

private int currentCapacity;
private Integer[] hashArray;
private final Integer DELETED_MARKER;
private int elementCount;
private int maxLoopLimit;

/**
 * Constructs a CuckooHashMap object with the specified initial table size.
 *
 * @param initialCapacity the initial size of the hash map
 */
public CuckooHashMap(int initialCapacity) {
this.hashArray = new Integer[initialCapacity];
this.currentCapacity = initialCapacity;
this.DELETED_MARKER = Integer.MIN_VALUE;
this.elementCount = 0;
this.maxLoopLimit = (int) (Math.log(initialCapacity) / Math.log(2)) + 2;
}

/**
 * Computes the first hash index for a given key using the modulo operation.
 *
 * @param inputKey the key for which the hash index is computed
 * @return an integer index corresponding to the key
 */
public int firstHash(int inputKey) {
int hashValue = inputKey % currentCapacity;
if (hashValue < 0) {
hashValue += currentCapacity;
}
return hashValue;
}

/**
 * Computes the second hash index for a given key using integer division.
 *
 * @param inputKey the key for which the hash index is computed
 * @return an integer index corresponding to the key
 */
public int secondHash(int inputKey) {
int hashValue = inputKey / currentCapacity;
hashValue %= currentCapacity;
if (hashValue < 0) {
hashValue += currentCapacity;
}
return hashValue;
}

/**
 * Inserts a key into the hash table using cuckoo hashing.
 * If the target bucket is occupied, it relocates the existing key and attempts to insert
 * it into its alternate location. If the insertion process exceeds the threshold,
 * the table is resized.
 *
 * @param insertKey the key to be inserted into the hash table
 * @throws IllegalArgumentException if the key already exists in the table
 */
public void insertKey(int insertKey) {
Integer wrappedKey = insertKey;
Integer tempHolder;
int loopCounter = 0;
if (isStorageFull()) {
System.out.println("Hash table is full, lengthening & rehashing table");
increaseAndRehash();
}
if (containsKey(insertKey)) {
throw new IllegalArgumentException("Key already exists; duplicates are not allowed.");
}
while (loopCounter <= maxLoopLimit) {
loopCounter++;
int firstPos = firstHash(insertKey);
if ((hashArray[firstPos] == null) || Objects.equals(hashArray[firstPos], DELETED_MARKER)) {
hashArray[firstPos] = wrappedKey;
elementCount++;
verifyLoadRatio();
return;
}
tempHolder = hashArray[firstPos];
hashArray[firstPos] = wrappedKey;
wrappedKey = tempHolder;
int secondPos = secondHash(tempHolder);
if (Objects.equals(hashArray[secondPos], DELETED_MARKER)) {
hashArray[secondPos] = wrappedKey;
elementCount++;
verifyLoadRatio();
return;
} else if (hashArray[secondPos] == null) {
hashArray[secondPos] = wrappedKey;
elementCount++;
verifyLoadRatio();
return;
}
tempHolder = hashArray[secondPos];
hashArray[secondPos] = wrappedKey;
wrappedKey = tempHolder;
}
System.out.println("Infinite loop occurred, lengthening & rehashing table");
increaseAndRehash();
insertKey(insertKey);
}

/**
 * Rehashes the current table to a new size (double the current size) and reinserts existing keys.
 */
public void increaseAndRehash() {
CuckooHashMap newTable = new CuckooHashMap(currentCapacity * 2);
for (int bucketIndex = 0; bucketIndex < currentCapacity; bucketIndex++) {
if (hashArray[bucketIndex] != null && !Objects.equals(hashArray[bucketIndex], DELETED_MARKER)) {
newTable.insertKey(this.hashArray[bucketIndex]);
}
}
this.currentCapacity *= 2;
this.hashArray = newTable.hashArray;
this.maxLoopLimit = (int) (Math.log(currentCapacity) / Math.log(2)) + 2;
}

/**
 * Deletes a key from the hash table, marking its position as available.
 *
 * @param targetKey the key to be deleted from the hash table
 * @throws IllegalArgumentException if the table is empty or if the key is not found
 */
public void deleteKey(int targetKey) {
Integer wrappedTarget = targetKey;
if (isEmpty()) {
throw new IllegalArgumentException("Table is empty, cannot delete.");
}
int firstPos = firstHash(targetKey);
if (Objects.equals(hashArray[firstPos], wrappedTarget)) {
hashArray[firstPos] = DELETED_MARKER;
elementCount--;
return;
}
int secondPos = secondHash(targetKey);
if (Objects.equals(hashArray[secondPos], wrappedTarget)) {
hashArray[secondPos] = DELETED_MARKER;
elementCount--;
return;
}
throw new IllegalArgumentException("Key " + targetKey + " not found in the table.");
}

/**
 * Displays the hash table contents, bucket by bucket.
 */
public void displayTable() {
for (int bucketIndex = 0; bucketIndex < currentCapacity; bucketIndex++) {
if ((hashArray[bucketIndex] == null) || Objects.equals(hashArray[bucketIndex], DELETED_MARKER)) {
System.out.println("Bucket " + bucketIndex + ": Empty");
} else {
System.out.println("Bucket " + bucketIndex + ": " + hashArray[bucketIndex].toString());
}
}
System.out.println();
}

/**
 * Finds the index of a given key in the hash table.
 *
 * @param searchKey the key to be found
 * @return the index where the key is located
 * @throws IllegalArgumentException if the table is empty or the key is not found
 */
public int locateKey(int searchKey) {
Integer wrappedSearch = searchKey;
if (isEmpty()) {
throw new IllegalArgumentException("Table is empty; cannot find keys.");
}
int firstPos = firstHash(searchKey);
if (Objects.equals(hashArray[firstPos], wrappedSearch)) {
return firstPos;
}
int secondPos = secondHash(searchKey);
if (!Objects.equals(hashArray[secondPos], wrappedSearch)) {
throw new IllegalArgumentException("Key " + searchKey + " not found in the table.");
} else {
return secondPos;
}
}

/**
 * Checks if the given key is present in the hash table.
 *
 * @param searchKey the key to be checked
 * @return true if the key exists, false otherwise
 */
public boolean containsKey(int searchKey) {
return ((hashArray[firstHash(searchKey)] != null && hashArray[firstHash(searchKey)].equals(searchKey)) ||
(hashArray[secondHash(searchKey)] != null && hashArray[secondHash(searchKey)].equals(searchKey)));
}

/**
 * Checks the load factor of the hash table. If the load factor exceeds 0.7,
 * the table is resized to prevent further collisions.
 *
 * @return the current load factor of the hash table
 */
public double verifyLoadRatio() {
double loadFactor = (double) elementCount / currentCapacity;
if (loadFactor > 0.7) {
System.out.printf("Load factor is %.2f, rehashing table.%n", loadFactor);
increaseAndRehash();
}
return loadFactor;
}

/**
 * Checks if the hash map is full.
 *
 * @return true if the hash map is full, false otherwise
 */
public boolean isStorageFull() {
for (int bucketIndex = 0; bucketIndex < currentCapacity; bucketIndex++) {
if (hashArray[bucketIndex] == null || Objects.equals(hashArray[bucketIndex], DELETED_MARKER)) {
return false;
}
}
return true;
}

/**
 * Checks if the hash map is empty.
 *
 * @return true if the hash map is empty, false otherwise
 */
public boolean isEmpty() {
for (int bucketIndex = 0; bucketIndex < currentCapacity; bucketIndex++) {
if (hashArray[bucketIndex] != null) {
return false;
}
}
return true;
}

/**
 * Returns the current number of keys in the hash table.
 *
 * @return the number of keys present in the hash table
 */
public int getKeyCount() {
return elementCount;
}
}
