package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.ArrayList;

/**
 * This class implements a hash table using linear probing to resolve collisions.
 * Linear probing is a collision resolution method where each slot in the hash table is checked in a sequential manner
 * until an empty slot is found.
 *
 * <p>
 * The class allows for storing key-value pairs, where both the key and value are generic types.
 * The key must be of a type that implements the Comparable interface to ensure that the keys can be compared for sorting.
 * </p>
 *
 * <p>
 * This implementation supports basic operations such as:
 * <ul>
 *     <li><b>put(Key key, Value value)</b>: Adds a key-value pair to the hash table. If the key already exists, its value is updated.</li>
 *     <li><b>get(Key key)</b>: Retrieves the value associated with the given key.</li>
 *     <li><b>delete(Key key)</b>: Removes the key and its associated value from the hash table.</li>
 *     <li><b>contains(Key key)</b>: Checks if the hash table contains a given key.</li>
 *     <li><b>size()</b>: Returns the number of key-value pairs in the hash table.</li>
 *     <li><b>keys()</b>: Returns an iterable collection of keys stored in the hash table.</li>
 * </ul>
 * </p>
 *
 * <p>
 * The internal size of the hash table is automatically resized when the load factor exceeds 0.5 or falls below 0.125,
 * ensuring efficient space utilization.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Linear_probing">Linear Probing Hash Table</a>
 *
 * @param <KeyType> the type of keys maintained by this map
 * @param <ValueType> the type of mapped values
 */
@SuppressWarnings("rawtypes")
public class LinearProbingHashMap<KeyType extends Comparable<KeyType>, ValueType> extends MapBase<KeyType, ValueType> {
private int tableCapacity;
private KeyType[] keyStorage;
private ValueType[] valueStorage;
private int elementCount;

public LinearProbingHashMap() {
this(16);
}

@SuppressWarnings("unchecked")
public LinearProbingHashMap(int initialCapacity) {
this.tableCapacity = initialCapacity;
keyStorage = (KeyType[]) new Comparable[initialCapacity];
valueStorage = (ValueType[]) new Object[initialCapacity];
}

@Override
public boolean put(KeyType inputKey, ValueType inputValue) {
if (inputKey == null) {
return false;
}
if (elementCount > tableCapacity / 2) {
expandTable(tableCapacity * 2);
}
int position = computeHash(inputKey, tableCapacity);
while (keyStorage[position] != null) {
if (inputKey.equals(keyStorage[position])) {
valueStorage[position] = inputValue;
return true;
}
position = advancePosition(position);
}
keyStorage[position] = inputKey;
valueStorage[position] = inputValue;
elementCount++;
return true;
}

@Override
public ValueType get(KeyType searchKey) {
if (searchKey == null) {
return null;
}
for (int slot = computeHash(searchKey, tableCapacity); keyStorage[slot] != null; slot = advancePosition(slot)) {
if (searchKey.equals(keyStorage[slot])) {
return valueStorage[slot];
}
}
return null;
}

@Override
public boolean delete(KeyType targetKey) {
if (targetKey == null || !contains(targetKey)) {
return false;
}
int currentSlot = computeHash(targetKey, tableCapacity);
while (!targetKey.equals(keyStorage[currentSlot])) {
currentSlot = advancePosition(currentSlot);
}
keyStorage[currentSlot] = null;
valueStorage[currentSlot] = null;
currentSlot = advancePosition(currentSlot);
while (keyStorage[currentSlot] != null) {
KeyType rehashKey = keyStorage[currentSlot];
ValueType rehashValue = valueStorage[currentSlot];
keyStorage[currentSlot] = null;
valueStorage[currentSlot] = null;
elementCount--;
put(rehashKey, rehashValue);
currentSlot = advancePosition(currentSlot);
}
elementCount--;
if (elementCount > 0 && elementCount <= tableCapacity / 8) {
shrinkTable(tableCapacity / 2);
}
return true;
}

@Override
public boolean contains(KeyType targetKey) {
return get(targetKey) != null;
}

@Override
int getElementCount() {
return elementCount;
}

@Override
Iterable<KeyType> getAllKeys() {
ArrayList<KeyType> keyList = new ArrayList<>(elementCount);
for (int slotIndex = 0; slotIndex < tableCapacity; slotIndex++) {
if (keyStorage[slotIndex] != null) {
keyList.add(keyStorage[slotIndex]);
}
}
keyList.sort(Comparable::compareTo);
return keyList;
}

private int advancePosition(int currentIndex) {
return (currentIndex + 1) % tableCapacity;
}

private void expandTable(int newCapacity) {
LinearProbingHashMap<KeyType, ValueType> temporaryMap = new LinearProbingHashMap<>(newCapacity);
for (int slotIndex = 0; slotIndex < tableCapacity; slotIndex++) {
if (keyStorage[slotIndex] != null) {
temporaryMap.put(keyStorage[slotIndex], valueStorage[slotIndex]);
}
}
this.keyStorage = temporaryMap.keyStorage;
this.valueStorage = temporaryMap.valueStorage;
this.tableCapacity = newCapacity;
}

private void shrinkTable(int newCapacity) {
LinearProbingHashMap<KeyType, ValueType> temporaryMap = new LinearProbingHashMap<>(newCapacity);
for (int slotIndex = 0; slotIndex < tableCapacity; slotIndex++) {
if (keyStorage[slotIndex] != null) {
temporaryMap.put(keyStorage[slotIndex], valueStorage[slotIndex]);
}
}
this.keyStorage = temporaryMap.keyStorage;
this.valueStorage = temporaryMap.valueStorage;
this.tableCapacity = newCapacity;
}
}
