package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.List;

/**
 * Threaded binary tree implementation that supports insertion and
 * in-order traversal without recursion or stack by using threads.
 *
 * <p>In this implementation, a node's null left/right pointers are used
 * to point to the in-order predecessor/successor respectively. Two flags
 * indicate whether left/right pointers are real children or threads.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Threaded_binary_tree">Wikipedia:
 * Threaded binary tree</a>
 */
public final class ThreadedBinaryTree {

    private Node root;

    private static final class Node {
        int value;
        Node left;
        Node right;
        boolean leftIsThread;
        boolean rightIsThread;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
            this.leftIsThread = false;
            this.rightIsThread = false;
        }
    }

    public ThreadedBinaryTree() {
        this.root = null;
    }

    /**
     * Inserts a value into the threaded binary tree. Duplicate values are inserted
     * to the right subtree (consistent deterministic rule).
     *
     * @param value the integer value to insert
     */
    public void insert(int value) {
        Node newNode = new Node(value);
        if (root == null) {
            root = newNode;
            return;
        }

        Node current = root;
        Node parent = null;

        while (true) {
            parent = current;
            if (value < current.value) {
                if (!current.leftIsThread && current.left != null) {
                    current = current.left;
                } else {
                    break;
                }
            } else { // value >= current.value
                if (!current.rightIsThread && current.right != null) {
                    current = current.right;
                } else {
                    break;
                }
            }
        }

        if (value < parent.value) {
            // attach newNode as left child
            newNode.left = parent.left;
            newNode.leftIsThread = parent.leftIsThread;
            newNode.right = parent;
            newNode.rightIsThread = true;

            parent.left = newNode;
            parent.leftIsThread = false;
        } else {
            // attach newNode as right child
            newNode.right = parent.right;
            newNode.rightIsThread = parent.rightIsThread;
            newNode.left = parent;
            newNode.leftIsThread = true;

            parent.right = newNode;
            parent.rightIsThread = false;
        }
    }

    /**
     * Returns the in-order traversal of the tree as a list of integers.
     * Traversal is done without recursion or an explicit stack by following threads.
     *
     * @return list containing the in-order sequence of node values
     */
    public List<Integer> inorderTraversal() {
        List<Integer> result = new ArrayList<>();
        Node current = root;
        if (current == null) {
            return result;
        }

        // Move to the leftmost node
        while (current.left != null && !current.leftIsThread) {
            current = current.left;
        }

        while (current != null) {
            result.add(current.value);

            // If right pointer is a thread, follow it
            if (current.rightIsThread) {
                current = current.right;
            } else {
                // Move to leftmost node in right subtree
                current = current.right;
                while (current != null && !current.leftIsThread && current.left != null) {
                    current = current.left;
                }
            }
        }

        return result;
    }

    /**
     * Helper: checks whether the tree is empty.
     *
     * @return true if tree has no nodes
     */
    public boolean isEmpty() {
        return root == null;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.Random;

/**
 * Treap -> Tree + Heap
 * Also called as cartesian tree
 *
 * @see
 * <a href = "https://cp-algorithms.com/data_structures/treap.html" />
 */

public class Treap {

    public static class TreapNode {
        /**
         * TreapNode class defines the individual nodes in the Treap
         *
         * value -> holds the value of the node.
         * Binary Search Tree is built based on value.
         *
         * priority -> holds the priority of the node.
         * Heaps are maintained based on priority.
         * It is randomly assigned
         *
         * size -> holds the size of the subtree with current node as root
         *
         * left -> holds the left subtree
         * right -> holds the right subtree
         */
        public int value;
        private int priority;
        private int size;
        public TreapNode left;
        public TreapNode right;

        public TreapNode(int valueParam, int priorityParam) {
            value = valueParam;
            priority = priorityParam;
            size = 1;
            left = null;
            right = null;
        }

        /**
         * updateSize -> updates the subtree size of the current node
         */
        private void updateSize() {
            size = 1;
            if (left != null) {
                size += left.size;
            }
            if (right != null) {
                size += right.size;
            }
        }
    }

    /**
     * root -> holds the root node in the Treap
     * random -> to generate random priority for the nodes in the Treap
     */
    private TreapNode root;
    private Random random = new Random();

    /**
     * Constructors
     *
     * Treap() -> create an empty Treap
     * Treap(int[] nodeValues) -> add the elements given in the array to the Treap
     */
    public Treap() {
        root = null;
    }

    /**
     * merges two Treaps left and right into a single Treap
     *
     * @param left left Treap
     * @param right right Treap
     * @return root of merged Treap
     */
    private TreapNode merge(TreapNode left, TreapNode right) {
        if (left == null) {
            return right;
        }
        if (right == null) {
            return left;
        }

        if (left.priority > right.priority) {
            left.right = merge(left.right, right);
            left.updateSize();
            return left;
        } else {
            right.left = merge(left, right.left);
            right.updateSize();
            return right;
        }
    }

    /**
     * split the Treap into two Treaps where left Treap has nodes <= key and right Treap has nodes > key
     *
     * @param node root node to be split
     * @param key key to compare the nodes
     * @return TreapNode array of size 2.
     * TreapNode[0] contains the root of left Treap after split
     * TreapNode[1] contains the root of right Treap after split
     */
    private TreapNode[] split(TreapNode node, int key) {
        if (node == null) {
            return new TreapNode[] {null, null};
        }

        TreapNode[] result;

        if (node.value <= key) {
            result = split(node.right, key);
            node.right = result[0];
            node.updateSize();
            result[0] = node;
        } else {
            result = split(node.left, key);
            node.left = result[1];
            node.updateSize();
            result[1] = node;
        }

        return result;
    }

    /**
     * insert a node into the Treap
     *
     * @param value value to be inserted into the Treap
     * @return root of the Treap where the value is inserted
     */
    public TreapNode insert(int value) {
        if (root == null) {
            root = new TreapNode(value, random.nextInt());
            return root;
        }

        TreapNode[] splitted = split(root, value);

        TreapNode node = new TreapNode(value, random.nextInt());

        TreapNode tempMerged = merge(splitted[0], node);
        tempMerged.updateSize();

        TreapNode merged = merge(tempMerged, splitted[1]);
        merged.updateSize();

        root = merged;

        return root;
    }

    /**
     * delete a value from root if present
     *
     * @param value value to be deleted from the Treap
     * @return root of the Treap where delete has been performed
     */
    public TreapNode delete(int value) {
        root = deleteNode(root, value);
        return root;
    }

    private TreapNode deleteNode(TreapNode root, int value) {
        if (root == null) {
            return null;
        }

        if (value < root.value) {
            root.left = deleteNode(root.left, value);
        } else if (value > root.value) {
            root.right = deleteNode(root.right, value);
        } else {
            root = merge(root.left, root.right);
        }

        if (root != null) {
            root.updateSize();
        }
        return root;
    }

    /**
     * print inorder traversal of the Treap
     */
    public void inOrder() {
        System.out.print("{");
        printInorder(root);
        System.out.print("}");
    }

    private void printInorder(TreapNode root) {
        if (root == null) {
            return;
        }
        printInorder(root.left);
        System.out.print(root.value + ",");
        printInorder(root.right);
    }

    /**
     * print preOrder traversal of the Treap
     */
    public void preOrder() {
        System.out.print("{");
        printPreOrder(root);
        System.out.print("}");
    }

    private void printPreOrder(TreapNode root) {
        if (root == null) {
            return;
        }
        System.out.print(root.value + ",");
        printPreOrder(root.left);
        printPreOrder(root.right);
    }

    /**
     * print postOrder traversal of the Treap
     */
    public void postOrder() {
        System.out.print("{");
        printPostOrder(root);
        System.out.print("}");
    }

    private void printPostOrder(TreapNode root) {
        if (root == null) {
            return;
        }
        printPostOrder(root.left);
        printPostOrder(root.right);
        System.out.print(root.value + ",");
    }

    /**
     * Search a value in the Treap
     *
     * @param value value to be searched for
     * @return node containing the value
     * null if not found
     */
    public TreapNode search(int value) {
        return searchVal(root, value);
    }

    private TreapNode searchVal(TreapNode root, int value) {
        if (root == null) {
            return null;
        }

        if (root.value == value) {
            return root;
        } else if (root.value < value) {
            return searchVal(root.right, value);
        } else {
            return searchVal(root.left, value);
        }
    }

    /**
     * find the lowerBound of a value in the Treap
     *
     * @param value value for which lowerBound is to be found
     * @return node which is the lowerBound of the value passed
     */
    public TreapNode lowerBound(int value) {
        TreapNode lowerBoundNode = null;
        TreapNode current = root;

        while (current != null) {
            if (current.value >= value) {
                lowerBoundNode = current;
                current = current.left;
            } else {
                current = current.right;
            }
        }

        return lowerBoundNode;
    }

    /**
     * find the upperBound of a value in the Treap
     *
     * @param value value for which upperBound is to be found
     * @return node which is the upperBound of the value passed
     */
    public TreapNode upperBound(int value) {
        TreapNode upperBoundNode = null;
        TreapNode current = root;

        while (current != null) {
            if (current.value > value) {
                upperBoundNode = current;
                current = current.left;
            } else {
                current = current.right;
            }
        }

        return upperBoundNode;
    }

    /**
     * returns size of the Treap
     */
    public int size() {
        if (root == null) {
            return 0;
        }
        return root.size;
    }

    /**
     * returns if Treap is empty
     */
    public boolean isEmpty() {
        return root == null;
    }

    /**
     * returns root node of the Treap
     */
    public TreapNode getRoot() {
        return root;
    }

    /**
     * returns left node of the TreapNode
     */
    public TreapNode getLeft(TreapNode node) {
        return node.left;
    }

    /**
     * returns the right node of the TreapNode
     */
    public TreapNode getRight(TreapNode node) {
        return node.right;
    }

    /**
     * prints the value, priority, size of the subtree of the TreapNode, left TreapNode and right TreapNode of the node
     */
    public String toString(TreapNode node) {
        return "{value : " + node.value + ", priority : " + node.priority + ", subTreeSize = " + node.size + ", left = " + node.left + ", right = " + node.right + "}";
    }
}

package com.thealgorithms.datastructures.trees;

/* Author : Suraj Kumar
  Github : https://github.com/skmodi649
 */

/* PROBLEM DESCRIPTION :
  There is a Binary Search Tree given, and we are supposed to find a random node in the given binary
  tree.
 */

/* ALGORITHM :
  Step 1: START
  Step 2: First create a binary tree using the steps mentioned in the first approach
  Step 3: Now use a method inOrder() that takes a node as input parameter to traverse through the
          binary tree in inorder fashion as also store the values in a ArrayList simultaneously.
  Step 4: Now define a method getRandom() that takes a node as input parameter, in this first call
          the inOrder() method to store the values in the arraylist, then find the size of the
  binary tree and now just generate a random number between 0 to n-1. Step 5: After generating the
  number display the value of the ArrayList at the generated index Step 6: STOP
 */

import java.util.ArrayList;

// Using auxiliary array to find the random node in a given binary tree

public class TreeRandomNode {

    private final class Node {

        int item;
        Node left;
        Node right;
    }

    // Using an arraylist to store the inorder traversal of the given binary tree
    static ArrayList<Integer> list = new ArrayList<>();
    // root of Tree
    Node root;

    TreeRandomNode() {
        root = null;
    }

    // Now lets find the inorder traversal of the given binary tree
    static void inOrder(Node node) {
        if (node == null) {
            return;
        }

        // traverse the left child
        inOrder(node.left);

        list.add(node.item);
        // traverse the right child
        inOrder(node.right);
    }

    public void getRandom(Node val) {
        inOrder(val);
        // getting the count of node of the binary tree
        int n = list.size();
        int min = 0;
        int max = n - 1;
        // Generate random int value from 0 to n-1
        int b = (int) (Math.random() * (max - min + 1) + min);
        // displaying the value at the generated index
        int random = list.get(b);
        System.out.println("Random Node : " + random);
    }
}
/* Explanation of the Approach :
  (a) Form the required binary tree
  (b) Now use the inOrder() method to get the nodes in inOrder fashion and also store them in the
  given arraylist 'list' (c) Using the getRandom() method generate a random number between 0 to n-1,
  then get the value at the generated random number from the arraylist using get() method and
  finally display the result.
 */
/* OUTPUT :
  First output :
  Random Node : 15
  Second output :
  Random Node : 99
 */
/* Time Complexity : O(n)
  Auxiliary Space Complexity : O(1)
 */

package com.thealgorithms.datastructures.trees;

import java.util.HashMap;

/**
 * Represents a Trie Node that stores a character and pointers to its children.
 * Each node has a hashmap which can point to all possible characters.
 * Each node also has a boolean value to indicate if it is the end of a word.
 */
class TrieNode {
    char value;
    HashMap<Character, TrieNode> child;
    boolean end;

    /**
     * Constructor to initialize a TrieNode with an empty hashmap
     * and set end to false.
     */
    TrieNode(char value) {
        this.value = value;
        this.child = new HashMap<>();
        this.end = false;
    }
}

/**
 * Trie Data structure implementation without any libraries.
 * <p>
 * The Trie (also known as a prefix tree) is a special tree-like data structure
 * that is used to store a dynamic set or associative array where the keys are
 * usually strings. It is highly efficient for prefix-based searches.
 * <p>
 * This implementation supports basic Trie operations like insertion, search,
 * and deletion.
 * <p>
 * Each node of the Trie represents a character and has child nodes for each
 * possible character.
 *
 * @author <a href="https://github.com/dheeraj92">Dheeraj Kumar Barnwal</a>
 * @author <a href="https://github.com/sailok">Sailok Chinta</a>
 */

public class Trie {
    private static final char ROOT_NODE_VALUE = '*';

    private final TrieNode root;

    /**
     * Constructor to initialize the Trie.
     * The root node is created but doesn't represent any character.
     */
    public Trie() {
        root = new TrieNode(ROOT_NODE_VALUE);
    }

    /**
     * Inserts a word into the Trie.
     * <p>
     * The method traverses the Trie from the root, character by character, and adds
     * nodes if necessary. It marks the last node of the word as an end node.
     *
     * @param word The word to be inserted into the Trie.
     */
    public void insert(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);

            if (node == null) {
                node = new TrieNode(word.charAt(i));
                currentNode.child.put(word.charAt(i), node);
            }
            currentNode = node;
        }

        currentNode.end = true;
    }

    /**
     * Searches for a word in the Trie.
     * <p>
     * This method traverses the Trie based on the input word and checks whether
     * the word exists. It returns true if the word is found and its end flag is
     * true.
     *
     * @param word The word to search in the Trie.
     * @return true if the word exists in the Trie, false otherwise.
     */
    public boolean search(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);

            if (node == null) {
                return false;
            }
            currentNode = node;
        }

        return currentNode.end;
    }

    /**
     * Deletes a word from the Trie.
     * <p>
     * The method traverses the Trie to find the word and marks its end flag as
     * false.
     * It returns true if the word was successfully deleted, false if the word
     * wasn't found.
     *
     * @param word The word to be deleted from the Trie.
     * @return true if the word was found and deleted, false if it was not found.
     */
    public boolean delete(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);
            if (node == null) {
                return false;
            }

            currentNode = node;
        }

        if (currentNode.end) {
            currentNode.end = false;
            return true;
        }

        return false;
    }

    /**
     * Counts the number of words in the trie
     *<p>
     * The method traverses the Trie and counts the number of words.
     *
     * @return count of words
     */
    public int countWords() {
        return countWords(root);
    }

    private int countWords(TrieNode node) {
        if (node == null) {
            return 0;
        }

        int count = 0;
        if (node.end) {
            count++;
        }

        for (TrieNode child : node.child.values()) {
            count += countWords(child);
        }

        return count;
    }

    /**
     * Check if the prefix exists in the trie
     *
     * @param prefix the prefix to be checked in the Trie
     * @return true / false depending on the prefix if exists in the Trie
     */
    public boolean startsWithPrefix(String prefix) {
        TrieNode currentNode = root;

        for (int i = 0; i < prefix.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(prefix.charAt(i), null);
            if (node == null) {
                return false;
            }

            currentNode = node;
        }

        return true;
    }

    /**
     * Count the number of words starting with the given prefix in the trie
     *
     * @param prefix the prefix to be checked in the Trie
     * @return count of words
     */
    public int countWordsWithPrefix(String prefix) {
        TrieNode currentNode = root;

        for (int i = 0; i < prefix.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(prefix.charAt(i), null);
            if (node == null) {
                return 0;
            }

            currentNode = node;
        }

        return countWords(currentNode);
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;

/* The following class implements a vertical order traversal
in a tree from top to bottom and left to right, so for a tree :
           1
          / \
         2   3
        / \   \
       4   5   6
        \     / \
         7   8   10
          \
           9
 the sequence will be :
 4 2 7 1 5 9 3 8 6 10
 */
public final class VerticalOrderTraversal {
    private VerticalOrderTraversal() {
    }

    /*Function that receives a root Node and prints the tree
        in Vertical Order.*/
    public static ArrayList<Integer> verticalTraversal(BinaryTree.Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        /*Queue to store the Nodes.*/
        Queue<BinaryTree.Node> queue = new LinkedList<>();

        /*Queue to store the index of particular vertical
                 column of a tree , with root at 0, Nodes on left
                 with negative index and Nodes on right with positive
                 index. */
        Queue<Integer> index = new LinkedList<>();

        /*Map of Integer and ArrayList to store all the
                 elements in a particular index in a single arrayList
                 that will have a key equal to the index itself. */
        Map<Integer, ArrayList<Integer>> map = new HashMap<>();

        /* min and max stores leftmost and right most index to
                 later print the tree in vertical fashion.*/
        int max = 0;
        int min = 0;
        queue.offer(root);
        index.offer(0);

        while (!queue.isEmpty()) {
            if (queue.peek().left != null) {
                /*Adding the left Node if it is not null
                                and its index by subtracting 1 from it's
                                parent's index*/
                queue.offer(queue.peek().left);
                index.offer(index.peek() - 1);
            }
            if (queue.peek().right != null) {
                /*Adding the right Node if it is not null
                                and its index by adding 1 from it's
                                parent's index*/
                queue.offer(queue.peek().right);
                index.offer(index.peek() + 1);
            }
            /*If the map does not contains the index a new
                         ArrayList is created with the index as key.*/
            if (!map.containsKey(index.peek())) {
                ArrayList<Integer> a = new ArrayList<>();
                map.put(index.peek(), a);
            }
            /*For a index, corresponding Node data is added
                         to the respective ArrayList present at that
                         index. */
            map.get(index.peek()).add(queue.peek().data);
            max = Math.max(max, index.peek());
            min = Math.min(min, index.peek());
            /*The Node and its index are removed
                         from their respective queues.*/
            index.poll();
            queue.poll();
        }
        /*Finally map data is printed here which has keys
                from min to max. Each ArrayList represents a
                vertical column that is added in ans ArrayList.*/
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = min; i <= max; i++) {
            ans.addAll(map.get(i));
        }
        return ans;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

/**
 * Given a binary tree.
 * This code returns the zigzag level order traversal of its nodes' values.
 * Binary tree:
 *                               7
 *                   /                         \
 *                6                           3
 *         /                \             /             \
 *      2                    4         10                19
 * Zigzag traversal:
 * [[7], [3, 6], [2, 4, 10, 19]]
 * <p>
 * This solution implements the breadth-first search (BFS) algorithm using a queue.
 * 1. The algorithm starts with a root node. This node is added to a queue.
 * 2. While the queue is not empty:
 *  - each time we enter the while-loop we get queue size. Queue size refers to the number of nodes
 * at the current level.
 *  - we traverse all the level nodes in 2 ways: from left to right OR from right to left
 *    (this state is stored on `prevLevelFromLeftToRight` variable)
 *  - if the current node has children we add them to a queue
 *  - add level with nodes to a result.
 * <p>
 * Complexities:
 * O(N) - time, where N is the number of nodes in a binary tree
 * O(N) - space, where N is the number of nodes in a binary tree
 *
 * @author Albina Gimaletdinova on 11/01/2023
 */
public final class ZigzagTraversal {
    private ZigzagTraversal() {
    }
    public static List<List<Integer>> traverse(BinaryTree.Node root) {
        if (root == null) {
            return List.of();
        }

        List<List<Integer>> result = new ArrayList<>();

        // create a queue
        Deque<BinaryTree.Node> q = new ArrayDeque<>();
        q.offer(root);
        // start with writing nodes from left to right
        boolean prevLevelFromLeftToRight = false;

        while (!q.isEmpty()) {
            int nodesOnLevel = q.size();
            List<Integer> level = new LinkedList<>();
            // traverse all the level nodes
            for (int i = 0; i < nodesOnLevel; i++) {
                BinaryTree.Node node = q.poll();
                if (prevLevelFromLeftToRight) {
                    level.add(0, node.data);
                } else {
                    level.add(node.data);
                }
                if (node.left != null) {
                    q.offer(node.left);
                }
                if (node.right != null) {
                    q.offer(node.right);
                }
            }
            // the next level node traversal will be from the other side
            prevLevelFromLeftToRight = !prevLevelFromLeftToRight;
            result.add(level);
        }
        return result;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.Scanner;
import java.util.concurrent.ThreadLocalRandom;

final class NearestRightKey {
    private NearestRightKey() {
    }

    public static void main(String[] args) {
        NRKTree root = buildTree();
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter first number: ");
        int inputX0 = sc.nextInt();
        int toPrint = nearestRightKey(root, inputX0);
        System.out.println("Key: " + toPrint);
        sc.close();
    }

    public static NRKTree buildTree() {
        int randomX = ThreadLocalRandom.current().nextInt(0, 100 + 1);
        NRKTree root = new NRKTree(null, null, randomX);

        for (int i = 0; i < 1000; i++) {
            randomX = ThreadLocalRandom.current().nextInt(0, 100 + 1);
            root = root.insertKey(root, randomX);
        }

        return root;
    }

    public static int nearestRightKey(NRKTree root, int x0) {
        // Check whether tree is empty
        if (root == null) {
            return 0;
        } else {
            if (root.data - x0 > 0) {
                // Go left
                int temp = nearestRightKey(root.left, x0);
                if (temp == 0) {
                    return root.data;
                }
                return temp;
            } else {
                // Go right
                return nearestRightKey(root.right, x0);
            }
        }
    }
}

class NRKTree {

    public NRKTree left;
    public NRKTree right;
    public int data;

    NRKTree(int x) {
        this.left = null;
        this.right = null;
        this.data = x;
    }

    NRKTree(NRKTree right, NRKTree left, int x) {
        this.left = left;
        this.right = right;
        this.data = x;
    }

    public NRKTree insertKey(NRKTree current, int value) {
        if (current == null) {
            return new NRKTree(value);
        }

        if (value < current.data) {
            current.left = insertKey(current.left, value);
        } else if (value > current.data) {
            current.right = insertKey(current.right, value);
        }

        return current;
    }
}

package com.thealgorithms.datastructures;

import java.util.ArrayList;
import java.util.List;

public class Node<T> {

    private final T value;
    private final List<Node<T>> children;

    public Node(final T value) {
        this.value = value;
        this.children = new ArrayList<>();
    }

    public Node(final T value, final List<Node<T>> children) {
        this.value = value;
        this.children = children;
    }

    public T getValue() {
        return value;
    }

    public void addChild(Node<T> child) {
        children.add(child);
    }

    public List<Node<T>> getChildren() {
        return children;
    }
}

package com.thealgorithms.devutils.nodes;

import java.util.Collection;

/**
 * {@link TreeNode} extension that holds a {@link Collection} of references to
 * child Nodes.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public class LargeTreeNode<E> extends TreeNode<E> {

    /**
     * {@link Collection} that holds the Nodes' child nodes.
     */
    private Collection<LargeTreeNode<E>> childNodes;

    /**
     * Empty constructor.
     */
    public LargeTreeNode() {
        super();
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see TreeNode#TreeNode(Object)
     */
    public LargeTreeNode(E data) {
        super(data);
    }

    /**
     * Initializes the Nodes' data and parent node reference.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @see TreeNode#TreeNode(Object, Node)
     */
    public LargeTreeNode(E data, LargeTreeNode<E> parentNode) {
        super(data, parentNode);
    }

    /**
     * Initializes the Nodes' data and parent and child nodes references.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @param childNodes {@link Collection} of child Nodes.
     * @see TreeNode#TreeNode(Object, Node)
     */
    public LargeTreeNode(E data, LargeTreeNode<E> parentNode, Collection<LargeTreeNode<E>> childNodes) {
        super(data, parentNode);
        this.childNodes = childNodes;
    }

    /**
     * @return True if the node is a leaf node, otherwise false.
     * @see TreeNode#isLeafNode()
     */
    @Override
    public boolean isLeafNode() {
        return (childNodes == null || childNodes.isEmpty());
    }

    public Collection<LargeTreeNode<E>> getChildNodes() {
        return childNodes;
    }

    public void setChildNodes(Collection<LargeTreeNode<E>> childNodes) {
        this.childNodes = childNodes;
    }
}

package com.thealgorithms.devutils.nodes;

/**
 * Base class for any node implementation which contains a generic type
 * variable.
 *
 * All known subclasses: {@link TreeNode}, {@link SimpleNode}.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public abstract class Node<E> {

    /**
     * Generic type data stored in the Node.
     */
    private E data;

    /**
     * Empty constructor.
     */
    public Node() {
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     */
    public Node(E data) {
        this.data = data;
    }

    public E getData() {
        return data;
    }

    public void setData(E data) {
        this.data = data;
    }
}

package com.thealgorithms.devutils.nodes;

/**
 * Simple Node implementation that holds a reference to the next Node.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public class SimpleNode<E> extends Node<E> {

    /**
     * Reference to the next Node.
     */
    private SimpleNode<E> nextNode;

    /**
     * Empty constructor.
     */
    public SimpleNode() {
        super();
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see Node#Node(Object)
     */
    public SimpleNode(E data) {
        super(data);
    }

    /**
     * Initializes the Nodes' data and next node reference.
     *
     * @param data Value to which data will be initialized.
     * @param nextNode Value to which the next node reference will be set.
     */
    public SimpleNode(E data, SimpleNode<E> nextNode) {
        super(data);
        this.nextNode = nextNode;
    }

    /**
     * @return True if there is a next node, otherwise false.
     */
    public boolean hasNext() {
        return (nextNode != null);
    }

    public SimpleNode<E> getNextNode() {
        return nextNode;
    }

    public void setNextNode(SimpleNode<E> nextNode) {
        this.nextNode = nextNode;
    }
}

package com.thealgorithms.devutils.nodes;

/**
 * Simple TreeNode extension that holds references to two child Nodes (left and
 * right).
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public class SimpleTreeNode<E> extends TreeNode<E> {

    /**
     * Reference to the child Node on the left.
     */
    private SimpleTreeNode<E> leftNode;
    /**
     * Reference to the child Node on the right.
     */
    private SimpleTreeNode<E> rightNode;

    /**
     * Empty constructor.
     */
    public SimpleTreeNode() {
        super();
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see TreeNode#TreeNode(Object)
     */
    public SimpleTreeNode(E data) {
        super(data);
    }

    /**
     * Initializes the Nodes' data and parent node reference.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @see TreeNode#TreeNode(Object, Node)
     */
    public SimpleTreeNode(E data, SimpleTreeNode<E> parentNode) {
        super(data, parentNode);
    }

    /**
     * Initializes the Nodes' data and parent and child nodes references.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @param leftNode Value to which the nodes' left child reference will be
     * set.
     * @param rightNode Value to which the nodes' right child reference will be
     * set.
     */
    public SimpleTreeNode(E data, SimpleTreeNode<E> parentNode, SimpleTreeNode<E> leftNode, SimpleTreeNode<E> rightNode) {
        super(data, parentNode);
        this.leftNode = leftNode;
        this.rightNode = rightNode;
    }

    /**
     * @return True if the node is a leaf node, otherwise false.
     * @see TreeNode#isLeafNode()
     */
    @Override
    public boolean isLeafNode() {
        return (leftNode == null && rightNode == null);
    }

    public SimpleTreeNode<E> getLeftNode() {
        return leftNode;
    }

    public void setLeftNode(SimpleTreeNode<E> leftNode) {
        this.leftNode = leftNode;
    }

    public SimpleTreeNode<E> getRightNode() {
        return rightNode;
    }

    public void setRightNode(SimpleTreeNode<E> rightNode) {
        this.rightNode = rightNode;
    }
}

package com.thealgorithms.devutils.nodes;

/**
 * Base class for any tree node which holds a reference to the parent node.
 *
 * All known subclasses: {@link SimpleTreeNode}, {@link LargeTreeNode}.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public abstract class TreeNode<E> extends Node<E> {

    /**
     * Reference to the parent Node.
     */
    private TreeNode<E> parentNode;
    /**
     * Indicates the depth at which this node is in the tree.
     */
    private int depth;

    /**
     * Empty constructor.
     */
    public TreeNode() {
        super();
        depth = 0;
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see Node#Node(Object)
     */
    public TreeNode(E data) {
        super(data);
        depth = 0;
    }

    /**
     * Initializes the Nodes' data and parent node reference.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     */
    public TreeNode(E data, TreeNode<E> parentNode) {
        super(data);
        this.parentNode = parentNode;
        depth = this.parentNode.getDepth() + 1;
    }

    /**
     * @return True if the node is a leaf node, otherwise false.
     */
    public abstract boolean isLeafNode();

    /**
     * @return True if the node is the root node, otherwise false.
     */
    public boolean isRootNode() {
        return (parentNode == null);
    }

    public TreeNode<E> getParent() {
        return parentNode;
    }

    public void setParent(TreeNode<E> parentNode) {
        this.parentNode = parentNode;
        depth = this.parentNode.getDepth() + 1;
    }

    public int getDepth() {
        return depth;
    }
}

package com.thealgorithms.devutils.searches;

/**
 * The common interface of most searching algorithms that search in matrixes.
 *
 * @author Aitor Fidalgo (https://github.com/aitorfi)
 */
public interface MatrixSearchAlgorithm {
    /**
     * @param key is an element which should be found
     * @param matrix is a matrix where the element should be found
     * @param <T> Comparable type
     * @return array containing the first found coordinates of the element
     */
    <T extends Comparable<T>> int[] find(T[][] matrix, T key);
}
